@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../anchors/outline';

.js .paginated-list {
    margin-left: 0;

    .page {
        list-style-type: none;
        max-width: unset;
    }

    @include include-media.media('screen') {
        .page {
            display: none;
            margin-top: 0;

            &[data-open='true'] {
                display: list-item;
                margin-top: measurements.$measure--basic;

                &:focus {
                    @include outline.outline-properties(
                        colors.$color-nearblack
                    );
                }
            }

            ul {
                list-style: disc;

                ul {
                    list-style: circle;
                }
            }
        }
    }
}
