@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/functions';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/palette';
@use '../../abstracts/variables';
@use '../../anchors/inline';
@use '../../base/typography';
@use '../../layout/grid';

.swiper-viewport {
    @include grid.standard-grid();

    overflow: hidden;
    width: 100%;
}

.swiper-container {
    grid-column: 1/-1;
    position: relative;
    width: 100%;
    padding-bottom: measurements.$measure--medium4;

    @include include-media.media('>between') {
        width: 70%;
        grid-column: 4/-1;
    }
}

.js {
    .swiper-wrapper {
        --n: 1;
        --tx: 0px;
        display: flex;
        align-items: center;
        overflow-y: hidden;
        width: 100%;
        width: calc(var(--n) * 100%);
        // height: 50vw;
        // max-height: 100vh;
        transform: translate(
            calc(var(--tx, 0px) + var(--i, 0) / var(--n) * -100%)
        );
        align-items: baseline;
        list-style: none;
        max-width: none;
        margin-top: 0;
        margin-left: 0;

        @include include-media.media('<=between') {
            height: inherit;
            max-height: 25rem;
        }
    }
}

.swiper-slide {
    width: 100%;
    width: calc(100% / var(--n));
    user-select: none;
    pointer-events: none;

    @include include-media.media('>between') {
        margin-right: measurements.$measure--basic;
    }

    picture {
        display: flex;
        width: 100%;
    }
}

.js {
    .swiper-slide {
        opacity: 0.7;

        &.active {
            opacity: 1;
            transition: opacity 0.6s;

            .swiper-slide__text {
                opacity: 1;
            }
        }
    }

    .swiper-slide__text {
        position: relative;
        top: -(measurements.$measure--small4);
        padding: measurements.$measure--small2;
        color: colors.$color-purewhite;
        background-color: colors.$color-gray11;
        width: calc(100% - 5rem);
        margin-right: auto;
        margin-left: auto;
        opacity: 0;
        transition: opacity 0.6s;
        @include typography.smalltype();
        font-weight: variables.$font-weight-book;
        line-height: measurements.$measure--small1;

        p {
            max-width: none;
            @include typography.smalltype();
            font-weight: variables.$font-weight-book;
            line-height: measurements.$measure--small1;
        }

        a {
            @include inline.anchor-inline(
                colors.$color-gray4,
                colors.$color-gray4,
                colors.$color-nearblack,
                palette.$color-outline--dark
            );

            pointer-events: auto;
        }

        @include include-media.media('<=between') {
            margin-right: none;
            margin-left: measurements.$measure--basic;
            padding: measurements.$measure--basic;
        }
    }
}

.swiper-slide__image-wrapper {
    display: flex;
    justify-content: center;
    overflow: hidden;
    background-color: colors.$color-gray2;

    picture[data-tooltipdisplay='true'] {
        position: relative;
    }
    @include include-media.media('<=between') {
        overflow: hidden;
        max-height: 350px;
    }

    img {
        object-fit: cover;
        width: 100%;
        @include include-media.media('<desktop') {
            max-height: 17rem;
        }
        @include include-media.media('>=desktop') {
            max-height: 25rem;
        }
    }
}

.js {
    .lazy {
        display: none;
    }
}

.no-js {
    .lazy-img {
        display: none;
    }
}

.swiper-indicator {
    position: absolute;
    font-size: typography.$font-size--extrasmalltype;
    font-weight: variables.$font-weight-book;
    color: colors.$color-gray7;
    bottom: measurements.$measure--basic;
    right: measurements.$measure--huge3;

    @include include-media.media('>between') {
        bottom: measurements.$measure--medium3;
        right: measurements.$measure--basic;
    }
}

.swiper-indicator__active-slider {
    color: colors.$color-gray11;
}

.swiper-indicator__slider-length {
    color: colors.$color-gray12;
}

.swiper-buttons-wrap {
    bottom: measurements.$measure--half;
    right: measurements.$measure--basic;
    display: flex;
    position: absolute;
    z-index: functions.z-index('above');

    @include include-media.media('>between') {
        bottom: measurements.$measure--medium1;
        right: -(measurements.$measure--large4);
    }

    .swiper-slider-arrow {
        @include mixins.control-button(colors.$color-gray11);
        display: flex;
        justify-content: center;
    }
}

.swiper-button-prev {
    margin-right: measurements.$measure--basic;
}

.smooth {
    transition: transform 0.5s ease-out;
}
