@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../anchors/pathway-card';
@use '../../base/typography';

.pathway {
    margin-top: measurements.$measure--small2;
    padding-top: measurements.$measure--basic;

    .pathway__heading {
        margin-top: 0;
        padding-left: measurements.$measure--half;
        padding-right: measurements.$measure--half;
    }

    .pathway__cards {
        @include include-media.media('>tablet') {
            display: grid;
            grid-column: 2/-2;
            grid-template-columns: repeat(3, 1fr);
            grid-column-gap: measurements.$measure--small2;
        }

        list-style: none;
        margin: 0;
        max-width: unset;
        padding-bottom: measurements.$measure--small1;
        padding-left: measurements.$measure--half;
        padding-right: measurements.$measure--half;

        .card--pathway {
            margin-top: measurements.$measure--basic;

            a {
                @include pathway-card.pathway-card();
            }

            a.card--pathway__content--border {
                border-top: measurements.$measure--half solid
                    colors.$color-red50;
            }

            .card--pathway__content {
                overflow: hidden;

                img {
                    display: block;
                    width: 100%;
                }

                @include include-media.media('>mobile', '<=tablet') {
                    display: flex;
                    flex-direction: row;
                    flex-wrap: nowrap;

                    picture {
                        max-width: measurements.$measure--huge5;
                    }
                }
            }

            .card--pathway__content__text {
                padding-bottom: measurements.$measure--basic;
                padding-left: measurements.$measure--basic;
                padding-right: measurements.$measure--basic;
            }

            .card--pathway__content__heading {
                @include typography.betatype();

                .icon {
                    margin-left: measurements.$measure--quarter;
                }
            }
        }
    }

    &.background--pink90 {
        .pathway__heading {
            color: colors.$color-purewhite;
        }

        .pathway__cards {
            .card--pathway {
                a {
                    @include pathway-card.pathway-card(
                        $card-text-color: colors.$color-purewhite,
                        $card-text-hover-color: colors.$color-purewhite,
                        $card-background-color: transparent,
                        $card-background-hover-color: colors.$color-pink80,
                        $card-heading-color: colors.$color-purewhite,
                        $section-title-color: colors.$color-purewhite,
                        $border-color: colors.$color-pink80,
                        $outline-color: colors.$color-purewhite
                    );
                }
            }
        }
    }
}
