@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/measurements';
@use '../abstracts/mixins';
@use '../abstracts/palette';
@use '../abstracts/variables';
@use '../anchors/img-linked-pattern';
@use '../anchors/inline';
@use '../anchors/mixins-cta';
@use '../base/content';
@use '../base/page';
@use '../base/typography';
@use '../layout/grid';

// <Desktop-specific layout - secondary navigation never present
main > .event {
    @include include-media.media('<small') {
        .wrapper--event__content,
        .event__formassembly__form {
            @include page.default-margin();
        }

        .event__content,
        .event__contact {
            @include page.default-padding();
        }
    }

    @include include-media.media('>=tablet', '<small') {
        .wrapper--event__content {
            @include grid.standard-grid();

            margin-left: 0;
            margin-right: 0;

            .event__content {
                grid-column: 4 / span 18;
                padding-left: 0;
                padding-right: 0;
            }
        }
    }

    @include include-media.media('<tablet') {
        .event__content {
            padding: 0;
        }
    }
}

// Desktop-specific layout
main {
    @include include-media.media('>=small') {
        > .event {
            grid-column: span 24;

            .wrapper--event__content,
            .event__contact {
                @include grid.standard-grid();
            }

            .event__content {
                grid-column: 6 / span 14;
            }

            .event__contact {
                @include grid.standard-grid();

                .event__contact__details {
                    grid-column: 2 / span 9;
                }

                .event__contact__location {
                    grid-column: 11 / span 13;
                }

                .event__contact__details:only-child,
                .event__contact__location:only-child {
                    grid-column: 2 / span 22;
                }
            }
        }
    }

    @include include-media.media('>=desktop') {
        > .event {
            .event__content {
                grid-column: 7 / span 12;
            }
        }
    }
}

// Desktop specific layout if secondary navigation is present
main {
    @include include-media.media('>=small') {
        .navigation--secondary {
            grid-column: 1 / span 6;

            & + .event {
                grid-column: 7 / span 18;

                .wrapper--event__content {
                    @include grid.content-grid();
                }

                .event__content {
                    grid-column: 4 / span 12;
                }

                .event__contact {
                    @include grid.content-grid();

                    .event__contact__details {
                        grid-column: 2 / span 7;
                    }

                    .event__contact__location {
                        grid-column: 9 / span 9;
                    }

                    .event__contact__details:only-child,
                    .event__contact__location:only-child {
                        grid-column: 2 / span 16;
                    }
                }
            }
        }
    }
}

.event {
    .embedded-video,
    .carousel-gallery-default {
        margin: measurements.$measure--threequarters 0;
    }

    .related-content {
        li:only-child {
            grid-column: 1/-1;
        }
    }

    .footer-cards {
        grid-column: 1 / -1;
        color: colors.$color-purewhite;

        h2 {
            border-bottom: variables.$border-width-hairline solid
                colors.$color-red30;
        }

        a {
            @include inline.anchor-inline(
                colors.$color-gray4,
                colors.$color-gray4,
                colors.$color-gray11,
                palette.$color-outline--dark
            );
        }
    }

    .pathway .pathway__cards {
        padding-left: 0;
    }
}

// standfirst

.event__standfirst {
    @include typography.gammatype();
    @include typography.font-family('heading');
    font-weight: variables.$font-weight-light;
}

//event video

.event {
    .embedded-video {
        padding: 0;
    }
}

//event social card

.event__social-cards {
    margin-top: 0;
    margin-left: 0;
    max-width: unset;
}

//event agenda card

.event__agenda {
    list-style-type: none;
    margin-top: 0;
    margin-left: 0;
    max-width: unset;
}

.event__agenda--card {
    background-color: colors.$color-purewhite;
    padding: measurements.$measure--basic;
    display: flex;
    @include mixins.box-shadow();
}

.event__agenda--card__icon {
    min-width: measurements.$measure--medium3;

    span {
        background-color: colors.$color-red50;
        color: colors.$color-purewhite;
        padding: measurements.$measure--half;
        @include typography.smalltype();
    }
}

.event__agenda--card__details--time {
    color: colors.$color-gray7;
    @include typography.smalltype();
}

//speaker
.event__speakers {
    list-style-type: none;
    margin-top: 0;
    margin-left: 0;

    li:after {
        content: '';
        display: inline-block;
        width: 100%;
        height: measurements.$measure--basic;
        border-bottom: variables.$border-width-default dotted
            colors.$color-gray7;
    }
}

.event__speakers__name {
    @include typography.gammatype();
}

.event__speakers__name,
.event__speakers__description {
    display: block;
}

.event__speakers__description {
    color: colors.$color-gray7;
}

.event__speakers__details {
    display: flex;
    @include typography.smalltype();
    span {
        @include typography.alphatype();
        margin-right: measurements.$measure--half;
    }
}

//sponsor

.event__sponsors {
    margin-top: 0;
    margin-left: 0;
    display: flex;
    flex-wrap: wrap;
    list-style: none;
    justify-content: space-between;

    li {
        margin-top: measurements.$measure--half;
        width: 40%;
    }
    @include img-linked-pattern.linked-img();
}

//event tags

.event__tags {
    h2 {
        font-family: typography.$font-family-plex-sans;
        color: colors.$color-gray7;
        margin-bottom: measurements.$measure--basic;
        @include typography.smalltype();
    }

    .cta-block__cta {
        margin: 0 measurements.$measure--small2
            measurements.$measure--threequarters 0;
    }
}

//event guide

.event__guide {
    margin: measurements.$measure--basic 0;
}

.event_related-events {
    grid-column: 1/ -1;
    background-color: colors.$color-gray1;

    .event_related-events__wrapper {
        padding: measurements.$measure--basic 0;
        @include page.default-margin();
    }

    h2 {
        text-align: center;
    }

    .related-content {
        flex-wrap: wrap;

        @include include-media.media('<small') {
            @include page.default-margin;
        }

        @include include-media.media('>mobile') {
            display: flex;
            justify-content: space-between;
        }
    }

    li {
        @include include-media.media('>small') {
            width: 32%;
        }
        @include include-media.media('>=mobile', '<=small') {
            width: 47%;
        }
    }
}

.wrapper--event__social-icons {
    margin-bottom: measurements.$measure--small4;
    margin-left: 0;
    margin-right: 0;
    margin-top: measurements.$measure--small4;
}

.event__social-icons {
    border-bottom: variables.$border-width-hairline
        variables.$border-style-solid colors.$color-gray2;
    border-top: variables.$border-width-hairline variables.$border-style-solid
        colors.$color-gray2;
    position: relative;
}

.wrapper--event__contact {
    margin-top: measurements.$measure--basic;
    padding-bottom: measurements.$measure--small4;
    padding-top: measurements.$measure--basic;

    .event__contact__heading {
        border-bottom-style: variables.$border-style-solid;
        border-bottom-width: variables.$border-width-thicker;
        padding-bottom: measurements.$measure--half;
        text-align: left;
    }

    .event__contact {
        .related-content {
            align-items: flex-start;
            display: inline-flex;
            flex-direction: column;

            .card--contact {
                background: initial;
                box-shadow: initial;

                .card__details__text {
                    padding-left: 0;
                    padding-right: 0;
                }
            }

            li + li {
                @include include-media.media('<small') {
                    border-top-style: variables.$border-style-solid;
                    border-top-width: variables.$border-width-hairline;
                    padding-top: measurements.$measure--small4;
                }
            }
        }
    }
}

.wrapper--event__contact {
    .event__contact__heading {
        border-bottom-color: colors.$color-red50;
    }

    .event__contact {
        .related-content {
            li + li {
                border-top-color: colors.$color-red70;
            }
        }
    }
}

// Pattern overrides
.js .event .slider[data-style='arrows'] + .slider__controls,
.js .event .slider[data-style='responsive'] + .slider__controls {
    @include include-media.media('<tablet') {
        margin-right: measurements.$measure--basic;
    }
}

/// new banner
///
///

.banner-standfirst-label--event {
    @include include-media.media('<tablet') {
        h1,
        .evnt__info {
            text-align: left;
        }
    }
}

main {
    header {
        .evnt__info {
            padding-top: measurements.$measure--small4;
            p {
                @include content.content-style();
            }
        }

        .evnt__info__status {
            p {
                line-height: typography.$line-height-ratio--override--gamma;
            }
        }

        .evnt__formassembly__form {
            @include page.default-margin();
        }

        .event__formassembly__button {
            @include mixins-cta.cta-basic-light-bg();
        }

        .event__formassembly__form {
            margin-top: measurements.$measure--basic;
        }
    }
}

.evnt__info__details {
    margin-bottom: measurements.$measure--basic;
    text-align: left;

    @include include-media.media('>small') {
        text-align: center;
    }

    .icon {
        margin-right: measurements.$measure--half;
        @include typography.smalltype();
        color: colors.$color-red50;
        font-weight: variables.$font-weight-normal;
    }

    p {
        margin-top: 0;
        text-align: left;
    }

    ul {
        margin-top: 0;
        margin-left: 0;
        list-style: none;
        max-width: initial;
    }

    ul.evnt__info__details--block {
        @include include-media.media('>small') {
            display: grid;
            @include grid.x-column-grid(2);
        }
    }

    ul.evnt__info__details--inline {
        @include include-media.media('>small') {
            display: inline-flex;
            flex-wrap: wrap;
        }
    }

    li {
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        margin-top: 0;

        @include include-media.media('>=tablet') {
            margin-bottom: measurements.$measure--half;
            margin-right: measurements.$measure--half;
        }
    }
}

.evnt__info__status {
    @include include-media.media('>tablet') {
        margin-bottom: measurements.$measure--basic;
    }

    @include include-media.media('<=tablet') {
        margin-top: measurements.$measure--basic;
        margin-left: measurements.$measure--half;
    }

    p {
        display: inline;
        background-color: colors.$color-gray12;
        box-shadow: measurements.$measure--half 0 0 colors.$color-gray12,
            -(measurements.$measure--half) 0 0 colors.$color-gray12;
        padding: measurements.$measure--half;
        color: colors.$color-purewhite;
    }
}

.evnt__info__status.evnt__cancel-postponed {
    p {
        background-color: colors.$color-red50;
        box-shadow: measurements.$measure--half 0 0 colors.$color-red50,
            -(measurements.$measure--half) 0 0 colors.$color-red50;
    }
}

.evnt__info__status.evnt__past {
    p {
        background-color: colors.$color-nearblack;
        box-shadow: measurements.$measure--half 0 0 colors.$color-nearblack,
            -(measurements.$measure--half) 0 0 colors.$color-nearblack;
    }
}

.evnt__info__status + .evnt__info__cta {
    @include include-media.media('<tablet') {
        margin-top: measurements.$measure--basic;
    }
}

.evnt__info__cta {
    grid-column: 11 / span 6;

    ul {
        list-style: none;
        margin-top: 0;
        margin-left: 0;
        max-width: initial;
    }

    li {
        display: inline;
        margin-top: 0;

        @include include-media.media('>small') {
            margin-right: measurements.$measure--basic;
        }

        @include include-media.media('>mobile', '<small') {
            display: inline;
            margin-right: measurements.$measure--basic;
        }

        @include include-media.media('<=mobile') {
            display: block;
            padding-bottom: measurements.$measure--threequarters;
        }
    }
}

.evnt__info__text {
    margin: measurements.$measure--threequarters 0;
    border-top: variables.$border-width-hairline dotted colors.$color-gray6;
    border-bottom: variables.$border-width-hairline dotted colors.$color-gray6;

    .evnt__info__text--recurring {
        padding: measurements.$measure--threequarters 0;

        .fa-redo {
            margin-right: measurements.$measure--half;
        }

        p {
            max-width: initial;
            margin-top: 0;
        }

        .evnt__info__text--recurring--text {
            color: colors.$color-gray8;
        }
    }
}
