@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/measurements';
@use '../abstracts/mixins';
@use '../abstracts/variables';
@use '../base/content';
@use '../base/page';
@use '../base/typography';
@use '../layout/grid';
@use '../layout/heading-full-width';

// <Desktop-specific layout - secondary navigation never present
main > .news {
    grid-column: 1 / -1;

    @include include-media.media('<small') {
        grid-column: 1 / -1 !important;

        .banner__standfirst {
            @include grid.x-column-grid(22);

            h1,
            .labels,
            .standfirst {
                grid-column: 3 / 21;
            }
        }

        .news__summary,
        .news__wrap,
        .news__body,
        .news__hashtags__wrap,
        .news__social-icons,
        .news__related-courses,
        .news__related-subjects,
        .news__related-academics,
        .news__schools,
        .news__related-centres,
        .news__related-events,
        .news__related-people {
            grid-column: 4 / 22;
        }

        .news__contact,
        .news__related-news,
        .news__related-bayes-courses {
            grid-column: 1 / -1;
        }

        &.news--fullwidth {
            grid-column: 1 / span 24; /* dimitra said never navigation present, thus always full width */
        }
    }

    @include include-media.media('<tablet') {
        .banner__standfirst {
            @include grid.x-column-grid(24);

            h1,
            .labels,
            .standfirst {
                grid-column: 1/-1;
            }
        }

        .news__summary,
        .news__wrap,
        .news__body,
        .news__hashtags__wrap,
        .news__social-icons,
        .news__related-courses,
        .news__related-subjects,
        .news__related-academics,
        .news__schools,
        .news__related-centres,
        .news__related-events,
        .news__related-people {
            grid-column: 3 / 23;
            overflow: hidden;

            @include include-media.media('<=mobile') {
                grid-column: 1 / 24;
            }
        }
    }
}

// Desktop-specific layout
main {
    @include include-media.media('>=small') {
        > .news {
            grid-column: 1 / -1 !important;

            .banner__standfirst {
                @include grid.x-column-grid(20);
            }

            .news__summary,
            .news__wrap,
            .news__body,
            .news__hashtags__wrap,
            .news__social-icons,
            .news__related-courses,
            .news__related-subjects,
            .news__related-academics,
            .news__schools,
            .news__related-centres,
            .news__related-events,
            .news__related-people {
                grid-column: 7 / 19;
            }

            .news__contact,
            .news__related-news,
            .news__related-bayes-courses {
                grid-column: 1 / -1;
            }

            &.news--fullwidth {
                grid-column: 1 / span 24; /* dimitra said never navigation present, thus always full width */
            }
        }
    }
}

// Desktop specific layout if secondary navigation is present
main {
    @include include-media.media('>=small') {
        .navigation--secondary {
            grid-column: 1 / span 6;

            & + .news {
                grid-column: 7 / -1;
            }
        }
    }
}

// Generic styles
main > .news {
    .content {
        padding: 0;
        margin: 0;
    }

    .banner__standfirst {
        display: grid;

        h1,
        .labels,
        .standfirst {
            grid-column: 1/-1;
        }
    }

    .news__container {
        @include grid.standard-grid();
        @include include-media.media('<mobile') {
            @include page.default-margin();
        }

        > div:last-child {
            border-bottom: none;
        }
    }

    .news__summary {
        padding-bottom: measurements.$measure--small2;

        p {
            @include content.standfirst();
            margin-top: 0;
        }
    }

    .news__wrap {
        border-top: variables.$border-width-hairline
            variables.$border-style-solid colors.$color-gray4;
        padding-bottom: measurements.$measure--threequarters;
        border-bottom: variables.$border-width-hairline
            variables.$border-style-solid colors.$color-gray4;
    }

    .news__published {
        p {
            @include typography.smalltype();

            color: colors.$color-gray8;
            max-width: unset;
        }
    }

    .news__body {
        blockquote {
            p {
                @include typography.font-family('heading');
                @include typography.gammatype();
                @include typography.heading-font-features();

                font-weight: variables.$font-weight-light;
                line-height: typography.$line-height-ratio--body;
            }
        }

        .embedded-video {
            margin-top: measurements.$measure--small2;
            padding: 0;
        }

        .carousel-gallery-default {
            margin-top: measurements.$measure--small2;
            margin-bottom: measurements.$measure--small2;
            overflow: hidden;
        }
    }

    .news__hashtags__title {
        color: colors.$color-gray7;
        font-weight: variables.$font-weight-medium;
        margin-top: measurements.$measure--small2;
    }

    ul.news__hashtags {
        flex-wrap: wrap;
    }

    .news__social-icons {
        margin: measurements.$measure--basic 0;

        @include include-media.media('>=tablet') {
            margin: measurements.$measure--small4 0;
        }

        p {
            font-weight: variables.$font-weight-medium;
            margin-right: measurements.$measure--basic;
        }

        ul {
            margin-left: 0;
            margin-right: 0;
            display: flex;
            flex-direction: row;
        }

        li {
            list-style: none;
            margin-right: measurements.$measure--half;
        }
    }

    .news__related-courses {
        .card--related-course a {
            width: 100%;
        }
    }

    .news__related-academics {
        border-bottom: variables.$border-width-hairline
            variables.$border-style-solid colors.$color-gray4;
        .related-content {
            li:only-child {
                grid-column: 1/-1;
            }
            &.card--profile {
                padding: 0;
                margin-bottom: measurements.$measure--basic;
            }
        }
    }

    .news__related-subjects,
    .news__related-centres,
    .news__schools {
        padding-bottom: measurements.$measure--small1;
        border-bottom: variables.$border-width-hairline
            variables.$border-style-solid colors.$color-gray4;

        ul {
            margin-left: 0;
        }

        li {
            list-style: none;

            &:before {
                @include typography.font-family('sharp');

                color: colors.$color-red50;
                content: '\f0a9';
                display: inline-block;
                font-weight: variables.$font-weight-hairline;
                margin-right: measurements.$measure--half;
            }
        }
    }

    .news__related-news,
    .news__related-bayes-courses {
        background: colors.$color-purewhite;
        .news__related-news__container,
        .news__related-bayes-courses__container {
            @include include-media.media('<small') {
                @include page.default-margin();
            }
            margin: 0 measurements.$measure--small2;
            h2 {
                text-align: center;
            }
        }
    }

    .news__contact {
        @include mixins.footer-cards--dark();
        @include page.default-padding();

        background-color: colors.$color-red70;

        h2 {
            @include heading-full-width.full-width-heading(colors.$color-red60);
        }

        .card--contact .card__details .card__tag .icon {
            color: colors.$color-purewhite;
        }
    }
}

.js .news__related-news .news__related-news__container .slider__controls {
    @include include-media.media('>=small') {
        @include page.default-margin();
    }
}
