@use '../../../abstracts/media' as include-media;
@use '../../../abstracts/colors';
@use '../../../abstracts/measurements';
@use '../../../abstracts/mixins';
@use '../../../abstracts/palette';
@use '../../../abstracts/variables';
@use '../../../anchors/inline';
@use '../../../anchors/outline';
@use '../../../base/typography';

.carousel-gallery {
    overflow: hidden;
    position: relative;

    h2,
    h3,
    h4 {
        margin-top: 0;
        padding-bottom: measurements.$measure--half;
        color: colors.$color-purewhite;
    }

    .swiper-slide {
        margin-right: 0;
        margin-top: 0;
    }

    .swiper-slide__text {
        @include typography.smalltype;
        display: block;
        top: 0;
        background-color: initial;
        width: 100%;
        margin-right: unset;
        margin-left: unset;
        padding: measurements.$measure--basic 0;

        a {
            @include inline.anchor-inline(
                colors.$color-gray4,
                colors.$color-gray4,
                colors.$color-nearblack,
                palette.$color-outline--dark
            );
        }
    }

    .swiper-buttons-wrap {
        bottom: measurements.$measure--half;
        right: measurements.$measure--half;

        @include include-media.media('<between') {
            position: initial;
            padding: measurements.$measure--half;
            justify-content: flex-end;
        }

        .swiper-slider-arrow {
            @include mixins.control-button(colors.$color-purewhite);
            display: flex;
            justify-content: center;

            &:focus {
                background-color: transparent;
            }
            &:hover,
            &:active {
                color: colors.$color-pink90;
                background-color: colors.$color-purewhite;
            }

            &:hover,
            &:focus:focus,
            &:active:active {
                outline-color: colors.$color-purewhite;
            }
        }
    }

    .swiper-slide__image-wrapper {
        height: 22rem;
        background-color: colors.$color-gray10;

        @include include-media.media('<desktop') {
            height: 16rem;
        }

        @include include-media.media('<tablet') {
            height: measurements.$measure--huge5;
        }

        picture {
            display: flex;
        }

        & img {
            object-fit: contain;
        }
    }
}

.galleria-thumbnails-wrap {
    width: calc(100% - 7rem);
    overflow: hidden;

    @include include-media.media('<between') {
        width: calc(100%);
    }
}

.no-js {
    .galleria-thumbnails-wrap {
        display: none;
    }
}

.js {
    .carousel-gallery-default {
        padding: measurements.$measure--basic;
        background-color: colors.$color-gray8;
        margin-top: measurements.$measure--basic;
        display: grid; // FF fix
    }

    .swiper-wrapper {
        align-items: initial;
    }

    .galleria-thumbnails-list {
        --thumbnails: 1;
        display: flex;
        list-style: none;
        margin: 0;
        width: calc(var(--thumbnails) * 25%);
        max-width: none;
        align-items: baseline;
        transition: transform 0.5s;

        @include include-media.media('<between') {
            width: calc(var(--thumbnails) * 33%);
        }

        .galleria-thumbnail {
            max-width: calc(100% / var(--thumbnails));
            margin-top: 0;
            margin-right: measurements.$measure--half;

            &:first-child {
                margin-left: variables.$border-width-default;
            }

            & input {
                opacity: 0.7;
                max-width: 100%;
                height: auto;
                border: 0;
                max-height: measurements.$measure--medium3;
                margin-top: measurements.$measure--quarter;
                transition: opacity 0.6s;

                @include outline.anchor-default-outline(
                    palette.$color-outline--dark
                );

                &:focus {
                    opacity: 1;
                    outline-offset: 0;
                }

                &:active {
                    outline-style: solid;
                    outline-color: colors.$color-red50;
                    outline-width: variables.$border-width-default;
                    outline-offset: 0;
                }

                &:hover {
                    opacity: 1;
                }
            }

            &.active input,
            &.active input:focus {
                opacity: 1;
                outline-style: solid;
                outline-color: colors.$color-purewhite;
                outline-width: variables.$border-width-default;
                outline-offset: 0;
            }

            &.blurSlider {
                opacity: 0.7;
            }

            .galleria-thumbnail__current-thumbnail {
                @include mixins.screenreader-only;
            }
        }
    }
}
