@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../base/typography';

@use './card--mixin';

.finder__results,
.search__results {
    .card--contact {
        @include card--mixin.search-contact-research-card();
    }
}

.card--contact {
    @include card--mixin.contact-research-card();
}

.related-content {
    .card.card--contact {
        margin-top: 0;
        margin-bottom: 0;
        padding-bottom: measurements.$measure--small2;

        & + .card--contact {
            border-top-style: variables.$border-style-solid;
            border-top-color: colors.$color-nearblack;
            border-top-width: variables.$border-width-hairline;
            padding-top: measurements.$measure--small2;
        }

        .card__details {
            .card__details__text {
                padding-bottom: measurements.$measure--basic;
                padding-top: inherit;
                padding-left: 0;
            }
        }

        .card__tag + .card__tag {
            margin-top: measurements.$measure--half;
        }
    }
}

.card--contact__content .icon {
    font-size: typography.$font-size--gamma;
}
