@use 'promo-content--v2';
@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../base/content';
@use '../../base/typography';

// Pattern primarily used for content
.promo-content {
    border: variables.$border-width-hairline variables.$border-style-solid
        colors.$color-purple70;
    background-color: colors.$color-purple5;
    padding: measurements.$measure--threequarters measurements.$measure--small4
        measurements.$measure--small4;
    margin-top: measurements.$measure--medium3;

    @include include-media.media('>between') {
        padding: measurements.$measure--threequarters
            measurements.$measure--medium11 measurements.$measure--small4
            measurements.$measure--medium11;
    }
}

.promo-content__heading {
    @include content.h2style;
    color: colors.$color-purple70;
}

.promo-content__short-text {
    color: colors.$color-purple70;
}

.promo-content__long-text {
    @include include-media.media('>tablet') {
        margin-top: measurements.$measure--threequarters;
    }
}
.promo-content__rows-2 {
    display: flex;
    flex-direction: column;

    .promo-content__logo__wrap {
        display: flex;
        flex-direction: row;

        .promo-content__logo:first-child {
            margin-right: measurements.$measure--small4;

            @include include-media.media('<mobile') {
                margin-right: measurements.$measure--basic;
            }
        }

        .promo-content__logo {
            @include include-media.media('<tablet') {
                max-width: 50%;
            }
        }
    }
}

.promo-content__cols-2 {
    margin-top: measurements.$measure--basic;

    @include include-media.media('>tablet') {
        display: flex;
        flex-direction: row;
    }

    .promo-content__long-text {
        @include include-media.media('>tablet') {
            margin-top: 0;
            margin-left: measurements.$measure--small5;
        }

        @include include-media.media('>between') {
            margin-left: measurements.$measure--medium3;
        }
    }
}

.promo-content__logo {
    margin-top: measurements.$measure--threequarters;

    span {
        color: colors.$color-purple70;
    }

    span.fad {
        font-size: measurements.$measure--medium3;
    }

    max-width: 14rem;

    img {
        max-width: 100%;
    }
}

.promo-content--icon-graphic {
    .promo-content__graphic {
        border-top: variables.$border-width-thicker
            variables.$border-style-solid colors.$color-purple70;
        padding-top: measurements.$measure--small2;
    }

    .promo-content__graphic__icon {
        width: measurements.$measure--medium4;
    }
}

.promo-content__graphic--stat {
    @include typography.font-family('heading');
    @include typography.thetatype;
    font-weight: variables.$font-weight-light;
}
