@use '../abstracts/media' as include-media;
@use '../abstracts/measurements';
@use '../base/page';

main {
    @include include-media.media('>=small') {
        > .error {
            .content {
                grid-column: 4/-4;
                padding: 0;
            }
        }
    }

    @include include-media.media('<small') {
        > .error {
            grid-column: 1/-1;
            @include page.default-margin();
        }
    }
}

// Generic styles
main {
    > .error {
        padding: measurements.$measure--small2 0;
    }
}
