@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/measurements';
@use '../abstracts/variables';
@use 'outline';
@use 'reset';

@mixin cta--basic(
    $color: colors.$color-purewhite,
    $background: colors.$color-red50,
    $hover-color: colors.$color-purewhite,
    $hover-background: colors.$color-red70,
    $outline: colors.$color-purewhite,
    $corners: square
) {
    @include reset.anchor-reset();
    @include outline.anchor-default-outline($outline);

    display: inline-block;
    padding-bottom: measurements.$measure--half;
    padding-left: measurements.$measure--small2;
    padding-right: measurements.$measure--small2;
    padding-top: measurements.$measure--half;
    transition: background-color variables.$transition-duration--long;

    @if $corners == round {
        border-radius: measurements.$measure--quarter;
    }

    &,
    &:focus,
    &:active {
        background-color: $background;
        color: $color;
    }

    &:hover {
        @include include-media.media('hover') {
            background-color: $hover-background;
            color: $hover-color;
        }
    }
}

@mixin cta--basic--subelement(
    $color: colors.$color-purewhite,
    $background: colors.$color-red50,
    $hover-color: colors.$color-purewhite,
    $hover-background: colors.$color-red70,
    $outline: colors.$color-purewhite,
    $corners: square,
    $class: 'text'
) {
    @include reset.anchor-reset();

    display: inline-block;
    padding-bottom: measurements.$measure--half;
    padding-left: measurements.$measure--small2;
    padding-right: measurements.$measure--small2;
    padding-top: measurements.$measure--half;
    transition: background-color variables.$transition-duration--long;

    @if $corners == round {
        border-radius: measurements.$measure--quarter;
    }

    &,
    &:focus,
    &:active {
        background-color: $background;
        color: $color;
    }

    &:focus {
        .#{$class} {
            @include outline.outline-properties($outline);
        }
    }

    &:hover {
        @include include-media.media('hover') {
            background-color: $hover-background;
            color: $hover-color;
        }
    }
}
