@use 'sass:meta';
@use '../../../abstracts/media' as include-media;
@use '../../../abstracts/colors';
@use '../../../abstracts/measurements';
@use '../../../abstracts/variables';
@use '../../../base/page';
@use '../../../layout/grid';

.v26-finder__query {
    grid-column: 1 / -1;
}
.v26-finder__main {
    @include grid.standard-grid();
}
.wrapper--v26-finder__filters {
    grid-column: 1 / span 8;
    padding: measurements.$measure--basic measurements.$measure--threequarters;
    @include include-media.media('<desktop') {
        grid-column: 1 / span 9;
    }
    @include include-media.media('<small') {
        grid-column: 1 / -1;
        padding: measurements.$measure--basic measurements.$measure--basic 0
            measurements.$measure--basic;
        &[data-open='true'] {
            padding: measurements.$measure--medium3
                measurements.$measure--medium3 measurements.$measure--medium2
                measurements.$measure--medium3;
        }
    }
}

.v26-finder__results {
    grid-column: 10 / span 18;
    padding: measurements.$measure--basic measurements.$measure--small4;
    @include include-media.media('<desktop') {
        grid-column: 10 / span 15;
    }
    @include include-media.media('<small') {
        padding: measurements.$measure--basic;
        grid-column: 1 / -1;
    }
}
.v25-finder__header {
    padding-top: measurements.$measure--medium3;
    padding-left: measurements.$measure--basic;
    padding-right: measurements.$measure--basic;

    @include include-media.media('<small') {
        padding-top: measurements.$measure--small2;
    }
}
.v26-finder__fullwidth__wrapper {
    width: 100vw;
    margin-left: calc(50% - 50vw);
    margin-right: calc(50% - 50vw);
    display: flex;
    justify-content: center;
    background-color: colors.$color-gray10;
    color: colors.$color-purewhite;
    .v26-finder__fullwidth__inner {
        max-width: variables.$width--max;
        width: 100%;
        @include include-media.media('>=small') {
            //Match the same margin/paddings that are applied to <main>
            @include page.default-padding();
            @include page.default-margin();
        }
    }
}

//Styles for buttons on finder.
.v26-finder__btn {
    padding: measurements.$measure--threequarters measurements.$measure--half;
    background-color: colors.$color-gray11;
    border: variables.$border-width-hairline solid colors.$color-gray11;
    border-radius: measurements.$measure--quarter;
    color: colors.$color-purewhite;
    min-width: measurements.$measure--large4;
}
.v26-finder__btn_alt {
    @extend .v26-finder__btn;
    background-color: colors.$color-purewhite;
    color: colors.$color-gray11;
}

.v26-finder .v26-finder__results {
    .v26-pagination__wrapper {
        max-width: unset;
    }

    .v26-pagination__controls {
        justify-content: center;
    }
}

@include meta.load-css('finder-query');
@include meta.load-css('finder-accordion');
@include meta.load-css('finder-filters');
