@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../anchors/mixins-cta';
@use '../../fontawesome-7/variables';

.cta-block {
    list-style: none;
    margin: 0;
}

.primary-cta-arrow--bright {
    @include mixins-cta.cta-primary-icon-light-bg();
}

.primary-cta--bright {
    @include mixins-cta.cta-primary-light-bg();
}

.primary-cta-arrow--dark {
    @include mixins-cta.cta-primary-icon-dark-bg();
}

.primary-cta--dark {
    @include mixins-cta.cta-primary-dark-bg();
}

.outline-cta-arrow--bright {
    @include mixins-cta.cta-outlined-icon-light-bg();
}

.outline-cta--bright {
    @include mixins-cta.cta-outlined-light-bg();
}

.outline-cta-arrow--dark {
    @include mixins-cta.cta-outlined-icon-dark-bg();
}

.outline-cta--dark {
    @include mixins-cta.cta-outlined-dark-bg();
}

.basic-cta--bright {
    @include mixins-cta.cta-basic-light-bg();
}

.basic-cta--dark {
    @include mixins-cta.cta-basic-dark-bg();
}

.primary-cta--grey--bright {
    @include mixins-cta.cta-primary-light-bg(
        colors.$color-gray3,
        colors.$color-nearblack
    );

    &:hover,
    &:active {
        color: colors.$color-purewhite;
    }
}

.basic-cta--lifelong-learning-primary {
    @include mixins-cta.cta-primary-icon-light-bg(colors.$color-pink90);
}

.basic-cta--lifelong-learning-secondary {
    @include mixins-cta.cta-basic-light-bg(colors.$color-pink90);
}

.primary-cta--grey--bright {
    @include mixins-cta.cta-primary-dark-bg(
        colors.$color-gray3,
        colors.$color-nearblack
    );
    &:hover,
    &:active {
        color: colors.$color-purewhite;
    }
}

.outline-cta--bright-rounded-border {
    @include mixins-cta.cta-outlined-light-bg();
    border-radius: measurements.$measure--small4;
}

.outline-cta--bright-square {
    @include mixins-cta.cta-outlined-light-bg();
    border-radius: 0;
}

.cta-block--inline {
    .cta-block__cta {
        display: inline-block;

        &:not(:last-of-type) {
            margin-right: measurements.$measure--basic;
        }
    }
}

.outline-cta--bright-red-ol {
    @include mixins-cta.cta-outlined-light-bg();
    border-color: colors.$color-red50;

    &:active,
    &:hover {
        border-color: colors.$color-red50;
        background-color: colors.$color-red50;
    }
}

.outline-cta--mixed-red-gray {
    @include mixins-cta.cta-outlined-light-bg(
        colors.$color-gray11,
        colors.$color-red50
    );
}

.outline-cta-play--dark {
    @include mixins-cta.cta-outlined-icon-dark-bg(
        colors.$color-purewhite,
        colors.$color-purewhite,
        colors.$color-gray11,
        '\f144'
    );
}

.outline-cta-play--light {
    @include mixins-cta.cta-outlined-icon-light-bg(
        colors.$color-gray11,
        colors.$color-gray11,
        variables.$var-play-circle
    );
}

.outline-cta--rounded-edges {
    @include mixins-cta.cta-outlined-dark-bg();
    padding: measurements.$measure--quarter measurements.$measure--small2;
    border-radius: measurements.$measure--small4;
    margin-bottom: measurements.$measure--half;
}
