@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../anchors/discreet';
@use '../../base/content';
@use '../../base/page';
@use '../../base/typography';

////
/// Breadcrumbs
/// @group patterns
////
.breadcrumbs {
    background-color: colors.$color-gray1;
    color: colors.$color-nearblack;

    ol {
        @include include-media.media('<small') {
            @include page.default-margin();
        }

        @include include-media.media('>=small') {
            @include page.standard-box();
        }

        display: flex;
        flex-wrap: wrap;
        list-style: none;
        padding-bottom: measurements.$measure--half;
        padding-top: measurements.$measure--half;

        li {
            @include content.content-style();
            @include typography.smalltype();

            font-weight: variables.$font-weight-text;
            line-height: measurements.$measure--small1;
            max-width: unset;

            &:not(:last-of-type) {
                margin-right: measurements.$measure--half;
                margin-bottom: measurements.$measure--quarter;

                &:after {
                    @include typography.font-family('sharp');
                    font-size: typography.$font-size--icon;
                    content: '\f105';
                    font-weight: variables.$font-weight-light;
                    margin-left: measurements.$measure--quarter;
                }
            }

            a {
                @include discreet.anchor-discreet--notransition(
                    colors.$color-gray8,
                    colors.$color-gray8,
                    colors.$color-nearblack,
                    colors.$color-nearblack,
                    colors.$color-red50
                );
            }
        }
    }

    @include include-media.media('print') {
        display: none;
    }
}
