@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';

.banner__standfirst {
    background: colors.$color-blue90;
    color: colors.$color-purewhite;
    padding: measurements.$measure--small4;
    position: relative;

    @include include-media.media('<desktop') {
        grid-column: 1 / -1;
    }

    @include include-media.media('<tablet') {
        padding: measurements.$measure--small4 measurements.$measure--basic
            measurements.$measure--small4 measurements.$measure--basic;
    }

    @include include-media.media('>=desktop') {
        grid-column: 4 / 16;
        margin-top: -#{measurements.$measure--medium9};
    }
}
