@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/functions';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/palette';
@use '../../abstracts/variables';
@use '../../anchors/discreet';
@use '../../anchors/inline';
@use '../../anchors/outline';
@use '../../anchors/reset';
@use '../../base/content';
@use '../../base/typography';

// Vary modal width on modal type
.dialog {
    &[data-type='video'] {
        .dialog__inner {
            max-height: calc(100% - 10vh);
            @include include-media.media('>=tablet') {
                width: 80%;
            }
            @include include-media.media('>=between') {
                width: 70%;
            }
            @include include-media.media('>=small') {
                width: 60%;
            }
        }
    }
}

.no-scroll {
    overflow-y: hidden;
    margin-right: var(--scrollbar-width);
}

.dialog {
    @include mixins.veil();
    position: fixed;
    left: 0;
    top: 0;
    bottom: 0;
    z-index: functions.z-index('modal');
    display: block;
}

.dialog__heading {
    @include content.standfirst;
    @include content.h4style();
    font-weight: variables.$font-weight-book;
}

.dialog__strapline {
    color: colors.$color-red50;
    @include typography.smalltype();
}

.dialog__inner {
    display: block;
    width: 90%;
    margin-left: auto;
    margin-right: auto;
    margin-top: measurements.$measure--medium1;
    max-height: calc(100% - #{2 * measurements.$measure--small1});
    overflow-y: scroll;
    position: relative;

    @include include-media.media('>=tablet') {
        width: 65%;
        margin-top: 15vh;
        max-height: calc(100% - 30vh);
    }

    @include include-media.media('>=between') {
        width: 60%;
    }

    @include include-media.media('>=small') {
        width: 50%;
    }

    @include include-media.media('>=desktop') {
        width: 45%;
    }
}

.dialog__content {
    background: colors.$color-purewhite;
    position: relative;
    margin-left: auto;
    margin-right: auto;
    padding: measurements.$measure--small4 measurements.$measure--medium1
        measurements.$measure--medium1;

    p {
        max-width: typography.$max-line-length;
    }

    a {
        @include inline.anchor-inline();
    }

    .dialog__close {
        color: colors.$color-gray7;
        padding: measurements.$measure--threequarters;
        position: absolute;
        right: variables.$border-width-default;
        top: variables.$border-width-default;
        @include outline.anchor-default-outline(palette.$color-outline);
        display: flex;
        justify-content: center;

        &:hover {
            @include include-media.media('hover') {
                background-image: none;
                border: none;
                background-color: colors.$color-gray1;
                color: colors.$color-gray10;
            }

            &:before {
                font-size: typography.$font-size--icon + 0.2;
            }
        }

        &:active {
            background-color: colors.$color-gray1;
            color: colors.$color-gray10;
        }

        &:focus {
            color: colors.$color-gray10;
        }

        &:active,
        &:focus {
            outline-offset: 0;
        }
    }
}

.dialog__body-copy {
    margin-top: measurements.$measure--basic;

    hr {
        border-top: variables.$border-width-hairline dotted colors.$color-gray5;
        border-bottom: initial;
    }
}

.dialog__underline-transition {
    @include discreet.anchor-discreet--notransition(
        colors.$color-nearblack,
        colors.$color-nearblack,
        colors.$color-nearblack,
        transparent,
        colors.$color-red50
    );
}

.dialog__slider-control {
    color: colors.$color-nearblack;
    margin-top: measurements.$measure--medium1;
    display: flex;
    max-width: typography.$max-line-length;

    button {
        @include outline.anchor-default-outline();
        @include typography.font-family('default');
        @include typography.body-font-features();
        @include typography.smalltype;
        font-weight: variables.$font-weight-book;

        min-height: measurements.$measure--medium9;
        flex: 1;
        display: flex;
        text-align: left;

        &:first-of-type {
            border-right: variables.$border-width-default solid
                colors.$color-red50;
            flex-direction: row;
            padding-right: measurements.$measure--small1;

            .icon {
                margin-right: measurements.$measure--small1;
            }
        }

        &:last-of-type {
            flex-direction: row-reverse;
            padding-left: measurements.$measure--small1;

            .icon {
                margin-left: measurements.$measure--half;
            }
        }

        .dialog__underline-transition {
            display: inline;
        }

        .icon {
            align-self: center;
            display: inline-block;
        }

        @include include-media.media('<=mobile') {
            justify-content: flex-end;

            &:first-of-type {
                flex-direction: column-reverse;
                .icon {
                    align-self: flex-start;
                }
            }

            &:last-of-type {
                flex-direction: column-reverse;
                text-align: right;
                .icon {
                    align-self: flex-end;
                }
            }

            .icon {
                margin-top: measurements.$measure--half;
            }
        }
    }
}

// classnames starting with 'modal' are from Squiz, classnames starting with 'dialog' are JS generated

.modal__buttons {
    max-width: typography.$max-line-length;

    @include include-media.media('>=tablet') {
        display: flex;
    }
}

.modal__buttons--calendar {
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    a {
        @include reset.anchor-reset-properties;
        @include outline.anchor-default-outline(palette.$color-outline);
        border: variables.$border-width-hairline variables.$border-style-solid
            colors.$color-gray3;
        border-bottom-color: colors.$color-gray3;
        border-bottom-width: variables.$border-width-hairline;
        color: colors.$color-gray8;
        display: block;
        font-size: typography.$font-size--alpha;
        margin-top: measurements.$measure--small4;
        padding: measurements.$measure--threequarters;
        position: relative;
        flex-basis: 48%;

        &:visited {
            border-bottom-color: colors.$color-gray3;
            color: colors.$color-gray8;
        }

        &:hover {
            @include include-media.media('hover') {
                @include reset.anchor-reset-properties;
                color: colors.$color-purewhite;
                border: variables.$border-width-hairline
                    variables.$border-style-solid colors.$color-pink90;
                border-bottom-color: colors.$color-pink90;
                border-bottom-width: variables.$border-width-hairline;
                background-color: colors.$color-pink90;
                background-image: none;
                background-size: initial;
            }

            &:after {
                content: '\f271';
            }
        }

        &:focus {
            background-color: colors.$color-gray1;
            border: variables.$border-width-hairline
                variables.$border-style-solid colors.$color-gray4;
            border-bottom-color: colors.$color-gray4;
            border-bottom-width: variables.$border-width-hairline;
            color: colors.$color-gray11;
        }

        &:active {
            background-color: colors.$color-pink100;
            border: variables.$border-width-hairline
                variables.$border-style-solid colors.$color-pink100;
            border-bottom-color: colors.$color-pink100;
            border-bottom-width: variables.$border-width-hairline;
            color: colors.$color-purewhite;

            &:after {
                content: '\f274';
            }
        }

        &:after {
            @include typography.font-family('sharp');

            content: '\f133';
            position: absolute;
            right: measurements.$measure--threequarters;
        }
    }
}

.js .modal__body {
    display: none;
}

.modal__button {
    @include outline.anchor-default-outline(palette.$color-outline);

    .inline-text {
        @include inline.anchor-inline;
    }

    min-height: unset;
}

.no-js .modal {
    li {
        // Hide CTA on no-js
        &[data-keepformat='true'] {
            a,
            button {
                display: none;
            }
        }
    }
}
