@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/measurements';
@use '../abstracts/mixins';
@use '../abstracts/variables';
@use '../anchors/cta--basic';
@use '../anchors/outline';
@use '../base/content';
@use '../base/page';
@use '../base/typography';
@use '../layout/grid';

// <Desktop-specific layout - secondary navigation never present
main > .search {
    @include include-media.media('<small') {
        .wrapper--search {
            @include page.default-margin();
        }
    }
}

// Desktop-specific layout
main {
    @include include-media.media('>=small') {
        > .search {
            grid-column: 1 / span 24;

            .wrapper--search,
            .search-form {
                @include grid.standard-grid();
                grid-template-rows: repeat(3, auto);
            }

            .tabs,
            .wrapper--search__results,
            .wrapper--search__bestbets {
                grid-column: 1 / span 16;
            }

            .wrapper--search__othersites {
                grid-column: 17 / span 8;
                grid-row: 2 / span 2;
                margin-top: measurements.$measure--medium3;
            }

            .search-form {
                grid-column: span 24;

                .search-form__query {
                    grid-column: 4 / span 18;
                }
            }
        }
    }
}

.search {
    .content {
        padding: 0;
    }

    .banner--search {
        background-color: colors.$color-gray10;
        color: colors.$color-purewhite;
        display: block;
        height: measurements.$measure--huge5;
        text-align: center;

        h1 {
            margin-top: measurements.$measure--medium1;
        }
    }

    .wrapper--search {
        margin-top: -#{measurements.$measure--medium1};
        padding-bottom: measurements.$measure--small4;
        position: relative;
    }

    .search-form {
        @include include-media.media('>=small') {
            @include page.standard-box();
        }
    }

    .search-form__query {
        @include mixins.box-shadow();

        background-color: colors.$color-purewhite;
        width: 100%;

        @include include-media.media('>=tablet') {
            height: measurements.$measure--medium11;
        }

        .wrapper--search-form__query__fields {
            align-items: center;
            display: flex;
            flex-wrap: nowrap;
            height: 100%;
            padding: measurements.$measure--basic;

            @include include-media.media('<tablet') {
                align-items: stretch;
                flex-direction: column;
            }

            @include include-media.media('>=tablet') {
                flex-direction: row;
            }

            .wrapper--search-form__query__fields__input {
                display: flex;
                flex-direction: row;
                flex-wrap: nowrap;
                width: 100%;
            }
        }
    }

    .search__query {
        background-color: colors.$color-red50;
        padding: measurements.$measure--small2;
        position: relative;

        & > div {
            display: flex;
            flex-direction: row;
            flex-wrap: nowrap;
            height: 100%;
        }

        @include include-media.media('>=tablet') {
            margin-left: measurements.$measure--small2;
            margin-right: measurements.$measure--small2;
        }
    }

    .search__query__input {
        @include typography.font-family('default');
        @include typography.body-font-features();
        @include typography.alphatype();

        @include include-media.media('>=tablet') {
            @include typography.gammatype();
        }

        background-color: colors.$color-purewhite;
        display: flex;
        flex-grow: 1;
        font-weight: variables.$font-weight-text;
        padding: 0;
        position: relative;

        &:focus-within {
            @include outline.outline-properties(colors.$color-nearblack);
        }

        input {
            @include typography.font-family('default');
            @include typography.body-font-features();
            @include typography.gammatype();

            border-bottom: variables.$border-width-hairline solid
                colors.$color-gray3;
            border-right: variables.$border-width-hairline solid
                colors.$color-gray3;
            border-top: variables.$border-width-hairline solid
                colors.$color-gray3;
            border-left: 0;
            font-style: normal;
            height: 100%;
            min-width: 0; // Constrains width in Firefox
            padding-bottom: measurements.$measure--half;
            padding-left: measurements.$measure--half;
            padding-right: measurements.$measure--medium5;
            padding-top: measurements.$measure--half;
            width: 100%;

            @include include-media.media('<tablet') {
                border-left: variables.$border-width-hairline solid
                    colors.$color-gray3;
            }

            &:focus {
                color: colors.$color-gray10;
                font-style: normal;
                font-weight: variables.$font-weight-medium;
                outline: 0;
            }

            &::placeholder {
                font-style: italic;
            }

            &:placeholder-shown {
                color: colors.$color-gray7;
            }
        }

        .search__clear {
            @include typography.epsilontype();

            align-items: center;
            display: flex;
            flex-direction: row;
            flex-wrap: nowrap;
            height: measurements.$measure--small5;
            justify-content: center;
            position: absolute;
            right: measurements.$measure--half;
            top: measurements.$measure--quarter;
            width: measurements.$measure--small5;

            &:focus {
                @include outline.outline-properties();

                outline-offset: -#{variables.$border-width-thicker};
            }

            .search__clear__text {
                @include mixins.sr-only();
            }

            .icon {
                /*
                // temp overide with xmark-temp-styling below

                --fa-primary-color: #{colors.$color-gray7};
                --fa-primary-opacity: 1;
                --fa-secondary-color: #{colors.$color-gray1};
                --fa-secondary-opacity: 1;
                */
                @include content.xmark-temp-styling;

                letter-spacing: 0;
                line-height: 1;
            }
        }
    }

    .search__query__icon--wrapper {
        background-color: colors.$color-purewhite;
        border-bottom: variables.$border-width-hairline solid
            colors.$color-gray3;
        border-left: variables.$border-width-hairline solid colors.$color-gray3;
        border-top: variables.$border-width-hairline solid colors.$color-gray3;
        border-right: 0;
        padding-bottom: measurements.$measure--half;
        padding-left: measurements.$measure--half;
        padding-right: measurements.$measure--basic;
        padding-top: 0.375rem; // FIXME

        @include include-media.media('<tablet') {
            display: none;
        }
    }

    .search__query__submit {
        @include typography.gammatype();
        @include cta--basic.cta--basic(
            colors.$color-purewhite,
            colors.$color-red50,
            colors.$color-purewhite,
            colors.$color-red70,
            colors.$color-nearblack,
            round
        );

        flex-shrink: 0;
        font-weight: variables.$font-weight-book;
        margin-left: measurements.$measure--half;

        &:hover {
            cursor: pointer;
        }

        @include include-media.media('>=tablet') {
            margin-left: measurements.$measure--basic;
        }

        @include include-media.media('<tablet') {
            padding: measurements.$measure--basic measurements.$measure--small1;

            &:hover {
                padding: measurements.$measure--basic
                    measurements.$measure--small1;
            }
        }

        span {
            margin: auto;
        }

        .search__query__submit__text {
            @include include-media.media('<tablet') {
                @include mixins.screenreader-only();
            }
        }

        .search__query__submit__icon {
            @include include-media.media('<tablet') {
                display: block;
                padding: 0;
            }

            @include include-media.media('>=tablet') {
                display: none;
            }
        }
    }

    .tabs__links {
        li button > span .icon {
            border: unset;
            font-size: measurements.$measure--basic;
            line-height: unset;
        }
    }
}
