@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/palette';
@use '../../abstracts/variables';
@use '../../anchors/inline';
@use '../../base/page';

////
/// Footer - This is for the reusable footer element on course pages paint layouts asset id 503750
/// @group patterns
////

.course-footer {
    @include page.default-padding();
    padding-top: variables.$heading-margin;
    padding-bottom: measurements.$measure--small2;

    h2 {
        border-bottom: variables.$border-width-thicker
            variables.$border-style-solid colors.$color-red50;
        padding-bottom: measurements.$measure--basic;
        margin-top: measurements.$measure--small4;
    }

    h2:nth-child(2) {
        margin-top: measurements.$measure--medium3;
    }

    .related-content {
        justify-content: left;

        .card.card--contact {
            padding-top: 0;
            padding-bottom: 0;
            margin-top: measurements.$measure--basic;

            &:not(:first-child) {
                .card__details {
                    .card__details__text {
                        padding-top: 0;
                    }
                }
            }

            .card__details__text {
                padding-left: 0;
            }
            & + .card--contact {
                padding-top: 0;
                border-top: 0;
            }
        }
    }

    .ul:first-of-type {
        margin-top: measurements.$measure--basic;
    }

    .related-content .card.card--contact + .card--contact {
        border-top: none;
    }

    &.background--pink80 {
        color: colors.$color-purewhite;

        h2 {
            border-bottom: variables.$border-width-hairline
                variables.$border-style-solid colors.$color-pink70;
        }

        a {
            @include inline.anchor-inline(
                colors.$color-gray4,
                colors.$color-gray4,
                colors.$color-gray11,
                palette.$color-outline--dark
            );
        }

        .card .card__details .card__tag .icon {
            color: colors.$color-purewhite;
        }
    }

    .card .card__details .card__details__text {
        @include include-media.media('>tablet') {
            padding-top: 0;
        }
    }

    .related-content:not(.slider) {
        @include include-media.media('>tablet') {
            flex-wrap: nowrap;
        }
    }
}
