@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../base/typography';

.highlighted-content__border {
    border-left: measurements.$measure--half variables.$border-style-solid
        colors.$color-red50;
    margin-bottom: measurements.$measure--basic;
    margin-top: measurements.$measure--basic;
    padding-bottom: measurements.$measure--basic;
    padding-left: measurements.$measure--medium1;
    padding-top: measurements.$measure--basic;
}

.highlighted-content__info {
    margin-bottom: measurements.$measure--basic;
    margin-top: measurements.$measure--basic;
    padding-bottom: measurements.$measure--basic;
    padding-left: measurements.$measure--medium3;
    padding-top: measurements.$measure--basic;
    position: relative;

    &:before {
        @include typography.smalltype();
        @include typography.font-family('sharp');

        color: colors.$color-gray6;
        content: '\f05a';
        font-size: typography.$font-size--icon;
        left: measurements.$measure--quarter;
        margin-top: measurements.$measure--quarter;
        position: absolute;
    }
}

.highlighted-content__info,
.highlighted-content__border {
    p {
        margin: 0;
        max-width: calc(
            #{typography.$max-line-length} - #{measurements.$measure--medium3}
        );
    }

    p:nth-child(n + 2) {
        display: none;
    }
}
