@use 'dropdown-entry-requirement-page';
@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/variables';
@use '../../anchors/outline';
@use '../../base/typography';

.dropdown-filter {
    margin-top: measurements.$measure--basic;
    ul {
        &.data-group {
            // Filter content is grouped into list items, so when user selects option from
            // dropdown filter, disable list item type and left margin.
            margin-left: 0;
            li {
                list-style-type: none;
                // Nested list items should default back to standard bullet point styles
                ul {
                    margin-left: measurements.$measure--small1;

                    li {
                        list-style-type: disc;
                    }
                }
            }
        }

        li[data-hidden='true'] {
            display: none;
        }
    }

    select {
        @include typography.font-family('default');
        @include typography.body-font-features();
        @include typography.alphatype();
        @include mixins.dropdown-filter-select(
            colors.$color-gray7,
            colors.$color-nearblack,
            colors.$color-purewhite
        );

        bottom: measurements.$measure--quarter;
        font-weight: variables.$font-weight-medium;
        height: measurements.$measure--medium4;
        position: relative;
        width: 100%;
        margin-top: measurements.$measure--basic;
        border-color: colors.$color-gray7;

        @include include-media.media('<between') {
            -webkit-appearance: menulist;
        }

        &:focus {
            @include outline.outline-properties();
        }
    }

    ul:first-of-type {
        li {
            list-style-type: none;
        }
    }
}
