@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../base/content';
@use '../../base/typography';

////
/// Quotation
/// @group patterns
////
.blockquote__body {
    padding-left: measurements.$measure--small1;
    padding-right: measurements.$measure--small1;
    padding-bottom: measurements.$measure--half;
    color: colors.$color-gray11;
}

.blockquote__body p {
    @include content.standfirst();

    em {
        font-style: normal;
    }

    &:before,
    &:after {
        font-weight: variables.$font-weight-light;
    }

    &:before {
        content: '“';
    }

    &:after {
        content: '”';
    }
}

.blockquote__body--text-align-left {
    text-align: left;
}

.blockquote__body--text-align-right {
    text-align: right;
}

.blockquote__body--text-align-center {
    text-align: center;
}

blockquote footer {
    padding-left: measurements.$measure--small1;
    margin-bottom: measurements.$measure--small3;
    text-align: left;
    font-size: typography.$font-size--alpha;
    color: colors.$color-gray7;

    cite {
        font-style: normal;
    }
}
