@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/measurements';
@use '../abstracts/variables';
@use '../base/page';

// < Desktop-specific layout - secondary navigation never present
main > .documentation {
    @include include-media.media('>=small') {
        .content {
            grid-column: 4/-4;
        }
    }
}

// > Desktop (secondary navigation present)
main {
    @include include-media.media('>=small') {
        .navigation--secondary {
            & + .documentation {
                .content {
                    grid-column: 2/-2;
                }
            }
        }
    }
}

// Generic styles
.documentation {
    @include include-media.media('<small') {
        .content {
            grid-column: 1/-1;
            @include page.default-margin();
        }
    }

    .content {
        margin-top: measurements.$measure--small2;
        margin-bottom: measurements.$measure--small2;
        padding: 0;
    }

    .slider.doc-slider {
        list-style: none;
        margin: 0 auto;

        li {
            height: measurements.$measure--large2;
            width: 100%;
            border: variables.$border-width-default
                variables.$border-style-solid colors.$color-nearblack;
        }
    }
}
