@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';

.unibuddy-card {
    background-color: var(--color-purewhite);
    padding: measurements.$measure--basic;
    @include mixins.box-shadow;
}

.unibuddy-card--info {
    display: flex;
}

.unibuddy-card--info__image {
    img {
        max-width: measurements.$measure--large2;
        height: measurements.$measure--large2;
        object-fit: cover;
        border-radius: 100%;
    }

    .fa-user {
        font-size: measurements.$measure--medium7;
    }
}

.unibuddy-card--info__details {
    display: flex;
    flex-direction: column;
    padding-left: measurements.$measure--basic;

    .unibuddy-card--info__details--name {
        color: colors.$color-red50;
        font-weight: bold;
    }

    .unibuddy-card--info__details--level {
        font-weight: bold;
    }
}

.unibuddy-card--text {
    padding-bottom: measurements.$measure--basic;
}
