@use '../../abstracts/colors';
@use '../../abstracts/functions';
@use '../../abstracts/measurements';
@use '../../abstracts/palette';
@use '../../abstracts/variables';
@use '../../anchors/inline';
@use '../../base/content';

.show-more {
    .show-more__button__container {
        padding-top: measurements.$measure--small2;
        text-align: center;
    }

    .show-more__content {
        @include content.content-style();

        overflow: hidden;
        transition: max-height variables.$transition-duration--long;
    }

    .show-more__content[data-hidden='true'] {
        max-height: measurements.$measure--huge1;
        position: relative;

        &:after {
            background-image: linear-gradient(
                to bottom,
                rgba(255, 255, 255, 0),
                rgba(255, 255, 255, 1) 90%
            );

            bottom: 0;
            content: '';
            height: 90%;
            left: 0;
            position: absolute;
            width: 100%;
            z-index: functions.z-index('above');
        }
    }

    &[data-open='true'] {
        .show-more__button {
            .icon {
                &:after {
                    content: '\f056';
                }
            }
        }

        .show-more__content {
            max-height: 100%;
        }
    }

    .show-more__button {
        border-top-color: colors.$color-linkblue--dark;
        border-top-style: variables.$border-style-solid;
        border-top-width: variables.$border-width-default;
        padding-top: measurements.$measure--half;

        .icon {
            margin-right: measurements.$measure--quarter;
            border-bottom: variables.$border-width-default
                variables.$border-style-solid transparent;

            &:after {
                content: '\f055';
            }
        }

        .show-more__link-text {
            border-bottom: variables.$border-width-default
                variables.$border-style-solid colors.$color-linkblue;
        }

        button {
            @include inline.anchor-inline(
                palette.$color-inline-link,
                palette.$color-inline-link,
                palette.$color-text--dark,
                palette.$color-outline
            );

            border-bottom: none;

            &:hover,
            &:active {
                border-bottom: none;

                .icon {
                    border-bottom: variables.$border-width-default
                        variables.$border-style-solid transparent;
                }

                .show-more__link-text {
                    border-bottom: variables.$border-width-default
                        variables.$border-style-solid transparent;
                }
            }

            &:focus {
                border-bottom: none;

                .icon {
                    border-bottom: variables.$border-width-default
                        variables.$border-style-solid transparent;
                }

                .show-more__link-text {
                    border-bottom: variables.$border-width-default
                        variables.$border-style-solid colors.$color-linkblue;
                }
            }
        }
    }
}

// Blend background linear gradient to match tabs' light grey background
.tabs .show-more .show-more__content[data-hidden='true']:after,
.accordion .show-more .show-more__content[data-hidden='true']:after {
    background-image: linear-gradient(
        to bottom,
        rgba(242, 242, 242, 0),
        rgba(242, 242, 242, 1) 90%
    );
}
