@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/variables';
@use '../../anchors/mixins-cta';
@use '../../anchors/outline';
@use '../../base/typography';

.key-information--lifelong-learning-group {
    .lifelong-learning__start-date__cta {
        max-width: unset;
        .cta-block__cta {
            @include include-media.media('<=between') {
                display: flex;
                flex-direction: column;
                margin-top: measurements.$measure--small4;
            }

            a,
            button {
                @include mixins-cta.cta-basic-light-bg(
                    colors.$color-pink80,
                    colors.$color-purewhite
                );

                @include include-media.media('<=between') {
                    justify-content: center;
                }
            }
        }
    }

    ul {
        list-style-type: none;
        margin-left: 0;
        margin-top: 0;
    }

    > ul {
        > li {
            display: grid;

            padding-bottom: measurements.$measure--basic;

            @include include-media.media('>=tablet') {
                border-bottom: variables.$border-width-hairline
                    variables.$border-style-solid colors.$color-gray6;

                &:last-of-type {
                    border-bottom: none;
                }
            }

            @include include-media.media('<=mobile') {
                background-color: colors.$color-purewhite;
                border: variables.$border-width-default
                    variables.$border-style-solid colors.$color-gray6;
                padding: measurements.$measure--basic;

                grid-column-gap: measurements.$measure--basic;
                grid-template-columns: repeat(6, 1fr);
                grid-template-rows: repeat(4, auto);
                grid-template-areas:
                    'heading heading heading heading heading heading'
                    'date date date date date date'
                    'location location location location location location'
                    'button button button button button button'
                    'explanation explanation explanation explanation explanation explanation';
            }

            @include include-media.media('>mobile', '<=tablet') {
                grid-column-gap: measurements.$measure--basic;
                grid-template-columns: repeat(12, 1fr);
                grid-template-rows: repeat(4, auto);
                grid-template-areas:
                    'heading heading heading heading heading heading heading heading heading heading heading heading'
                    'date date date date date date date date date date date date'
                    'location location location location location location location location location location location location'
                    'button button button button button button button button button button button button'
                    'explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation';
            }

            @include include-media.media('>tablet', '<=between') {
                grid-column-gap: measurements.$measure--basic;
                grid-template-columns: repeat(12, 1fr);
                grid-template-rows: repeat(2, auto);
                grid-template-areas:
                    'heading heading heading heading heading heading heading heading heading heading heading heading'
                    'date date date date date location location location location location button button'
                    'explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation';
            }

            @include include-media.media('>between') {
                grid-column-gap: measurements.$measure--small2;
                grid-template-columns: repeat(18, 1fr);
                grid-template-rows: repeat(2, auto);
                grid-template-areas:
                    'heading heading heading heading heading heading heading heading heading heading heading heading heading heading heading heading heading heading'
                    'date date date date date date date location location location location location location location button button button button'
                    'explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation';
            }

            @include include-media.media('>desktop') {
                grid-template-areas:
                    'heading heading heading heading heading heading heading heading heading heading heading heading heading heading heading heading heading heading'
                    'date date date date date date location location location location location location location button button button button button'
                    'explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation';
            }

            > h3 {
                grid-area: heading;
            }

            > ul {
                @include include-media.media('<tablet') {
                    margin-left: measurements.$measure--small4;
                    margin-right: measurements.$measure--small4;
                }

                &:nth-of-type(1) {
                    grid-area: date;
                }

                &:nth-of-type(2) {
                    grid-area: location;
                }

                &:nth-of-type(3) {
                    grid-area: button;
                }
            }

            .lifelong-learning__start-date__fee-explanation {
                grid-area: explanation;
            }
        }
    }
}

.ki-shortc__list__dates {
    display: grid;
    margin-top: measurements.$measure--small4; // 2rem

    @include include-media.media('<=mobile') {
        grid-column-gap: measurements.$measure--basic;
        grid-template-columns: repeat(6, 1fr);
        grid-template-rows: repeat(4, auto);
        grid-template-areas:
            'h h h h h h'
            'd d d d d d'
            'b b b b b b';
    }

    @include include-media.media('>mobile', '<=tablet') {
        grid-column-gap: measurements.$measure--basic;
        grid-template-columns: repeat(12, 1fr);
        grid-template-rows: repeat(4, auto);
        grid-template-areas:
            'h h h h h h h h h h h h'
            'd d d d d d d d d d d d'
            'b b b b b b b b b b b b';
    }

    @include include-media.media('>tablet', '<=between') {
        grid-column-gap: measurements.$measure--basic;
        grid-template-columns: repeat(12, 1fr);
        grid-template-rows: repeat(2, auto);
        grid-template-areas:
            'h h h h h h h h h h h h'
            'd d d d d d d d b b b b';
    }

    @include include-media.media('>between') {
        grid-column-gap: measurements.$measure--small2;
        grid-template-columns: repeat(18, 1fr);
        grid-template-rows: repeat(2, auto);
        grid-template-areas:
            'h h h h h h h h h h h h h h h h h h'
            'd d d d d d d d d d d d d d b b b b';
    }

    @include include-media.media('>desktop') {
        grid-template-areas:
            'h h h h h h h h h h h h h h h h h h'
            'd d d d d d d d d d d d d b b b b b';
    }

    .ki-shortc__list__head {
        grid-area: h;
    }

    .ki-shortc__cta {
        a {
            @include mixins-cta.cta-basic-light-bg(
                colors.$color-pink80,
                colors.$color-purewhite
            );
            display: inline-block;
            @include include-media.media('<=between') {
                width: 100%;
            }
        }
        grid-area: b;
        text-align: center;
        max-width: unset;
        width: 100%;
    }

    .ki-shortc__list__dates__item {
        grid-area: d;
    }
}

