// Key info for research templates

.key-information--research__main {
    background: colors.$color-purewhite;
    border: variables.$border-style-solid variables.$border-width-hairline
        colors.$color-gray3;
    padding: measurements.$measure--basic;
}

.key-information--research__main__dates {
    @include mixins.table-reset();
    display: block;
    overflow: hidden;
    text-align: left;
    margin-bottom: measurements.$measure--small2;
    margin-top: 0;
    padding-bottom: measurements.$measure--small2;
    border-bottom: variables.$border-style-solid variables.$border-width-thicker
        colors.$color-purple70;

    thead,
    tbody {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        grid-column-gap: 1.5rem;

        @include include-media.media('<desktop') {
            grid-template-columns: repeat(2, 1fr);
        }
    }

    tr {
        display: flex;
        grid-column: 1 / 3;
        border-bottom: solid colors.$color-gray3
            variables.$border-width-hairline;
        padding: variables.$border-width-default 0;

        th {
            flex: 1;
            color: colors.$color-gray9;
            @include typography.font-family('heading');
            @include typography.betatype();
            margin-top: 0;
            font-weight: variables.$font-weight-medium;

            &:nth-of-type(2) {
                margin-left: measurements.$measure--small2;
            }
        }

        td {
            flex: 1;
            line-height: 1.625;

            &:nth-of-type(2) {
                margin-left: measurements.$measure--small2;
            }
        }
    }
}

.key-information--research__main__dates .date--short {
    @include include-media.media('>=mobile') {
        display: none;
    }
}

.key-information--research__main__dates .date--long {
    @include include-media.media('<mobile') {
        display: none;
    }
}

.key-information--research__main__duration {
    display: grid;
    grid-gap: 1.5rem;
    grid-template-columns: repeat(3, 1fr);

    @include include-media.media('<between') {
        grid-template-columns: repeat(2, 1fr);
        grid-gap: 0;
    }

    @include include-media.media('<mobile') {
        grid-template-columns: repeat(1, 1fr);
        grid-gap: 0;
    }
}

.key-information--research__main__duration__heading {
    color: colors.$color-gray9;
    @include typography.betatype();
    font-weight: variables.$font-weight-medium;
    @include typography.font-family('heading');
    margin-bottom: measurements.$measure--half;
}

.key-information--research__main__duration__item {
    @include typography.alphatype();

    span {
        color: colors.$color-purple70;
        font-weight: variables.$font-weight-medium;
    }

    @include include-media.media('<between') {
        margin-bottom: measurements.$measure--basic;
    }
}

.key-information--research__main__duration__item__label {
    display: block;
    color: colors.$color-gray10;
}

.js .key-information--lifelong-learning__dates--controllable {
    .key-information--lifelong-learning__dates,
    .ki-shortc__list__dates {
        overflow: hidden;
        position: relative;

        & > li {
            &:focus {
                @include outline.outline-properties(colors.$color-nearblack);

                outline-offset: -#{variables.$border-width-thick};
            }

            @include include-media.media('>=between') {
                display: none;

                &[data-loadmorevisible='true'] {
                    display: grid;
                }
            }

            @include include-media.media('<between') {
                position: absolute;
                top: 0;
                transition: left variables.$transition-duration--medium
                    ease-in-out;

                @include include-media.media('reducemotion') {
                    transition: none;
                }

                &[data-sliderposition='-1'] {
                    left: -100%;

                    &[data-hidden='true'] {
                        visibility: hidden;
                    }
                }

                &[data-sliderposition='0'] {
                    left: 0;
                    position: relative;
                }

                &[data-sliderposition='1'] {
                    left: 100%;

                    &[data-hidden='true'] {
                        visibility: hidden;
                    }
                }
            }
        }
    }

    .key-information--lifelong-learning__controls {
        align-items: center;
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        justify-content: center;
        margin-top: measurements.$measure--basic;

        .key-information--lifelong-learning__indicator {
            @include typography.smalltype();

            display: block;

            @include include-media.media('>=between') {
                display: none;
            }

            .key-information--lifelong-learning__indicator__current,
            .key-information--lifelong-learning__indicator__divider {
                color: colors.$color-gray7;
            }

            .key-information--lifelong-learning__indicator__divider {
                margin-left: measurements.$measure--quarter;
                margin-right: measurements.$measure--quarter;

                .key-information--lifelong-learning__indicator__divider--sr {
                    @include mixins.sr-only();
                }
            }

            .key-information--lifelong-learning__indicator__total {
                color: colors.$color-red50;
            }
        }

        .key-information--lifelong-learning__controls__prev,
        .key-information--lifelong-learning__controls__next,
        .key-information--lifelong-learning__controls__loadmore {
            background-color: transparent;
            border-color: colors.$color-red50;
            border-style: variables.$border-style-solid;
            border-width: variables.$border-width-hairline;
            color: colors.$color-red50;
            padding: measurements.$measure--threequarters;
            transition: background-color variables.$transition-duration ease-in,
                border-color variables.$transition-duration ease-in,
                color variables.$transition-duration ease-in;

            @include include-media.media('reducemotion') {
                /* We can't completely disable the transition becasuse we action on transitionend */
                transition: background-color
                        variables.$transition-duration--instant ease-in,
                    border-color variables.$transition-duration--instant ease-in,
                    color variables.$transition-duration--instant ease-in;
            }

            &:focus:not(:disabled),
            &:active:not(:disabled) {
                @include outline.outline-properties(colors.$color-nearblack);
            }

            &:hover:not(:disabled) {
                @include include-media.media('hover') {
                    background-color: colors.$color-red50;
                    color: colors.$color-purewhite;
                }
            }

            &:disabled {
                border-color: transparent;
                color: colors.$color-gray7;
                cursor: default;
            }
        }

        .key-information--lifelong-learning__controls__prev,
        .key-information--lifelong-learning__controls__next {
            @include typography.font-family('sharp');

            font-weight: variables.$font-weight-normal;
            display: block;

            @include include-media.media('>=between') {
                display: none;
            }

            span {
                @include mixins.sr-only();
            }
        }

        .key-information--lifelong-learning__controls__prev {
            margin-left: measurements.$measure--basic;

            &:before {
                content: '\f060';
            }

            & + .key-information--lifelong-learning__controls__next {
                margin-left: measurements.$measure--basic;
            }
        }

        .key-information--lifelong-learning__controls__next {
            &:before {
                content: '\f061';
            }
        }

        .key-information--lifelong-learning__controls__loadmore {
            border-radius: measurements.$measure--quarter;
            display: block;

            @include include-media.media('<between') {
                display: none;
            }
        }
    }
}
