@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables' as abstracts-variables;
@use '../../base/typography';
@use '../../fontawesome-7/functions';
@use '../../fontawesome-7/variables';
@use '../../layout/grid';

////
/// Accordion
/// @group patterns
////

@mixin accordion() {
    border-bottom: abstracts-variables.$border-width-hairline
        abstracts-variables.$border-style-solid colors.$color-gray2;
    margin-top: 0;

    // Heading focus/active needed for Firefox and Safari. Other interaction states on button
    &:focus {
        outline: abstracts-variables.$border-width-default
            abstracts-variables.$border-style-dotted colors.$color-gray11;
        border: 0;
    }
    &:active {
        border: 0;
        border-bottom: abstracts-variables.$border-width-hairline
            abstracts-variables.$border-style-solid transparent;
        outline: 0;
    }

    button {
        @include typography.betatype();
        width: 100%;
        text-align: left;
        padding: measurements.$measure--basic;
        color: colors.$color-linkblue;
        outline: abstracts-variables.$border-width-default
            abstracts-variables.$border-style-solid transparent;

        div {
            @include grid.ninetyten-grid();
            grid-column-gap: 0;
        }

        .accordion__heading__indicator {
            align-self: center;
            text-align: right;
            height: 100%;
            width: 100%;

            &:before {
                content: functions.fa-content(variables.$var-plus);
                display: inline-block;
                text-decoration: none;
            }
        }

        &:hover {
            @include include-media.media('hover') {
                text-decoration: underline;
                color: colors.$color-linkblue;
                outline: abstracts-variables.$border-width-default
                    abstracts-variables.$border-style-solid transparent;
                background: colors.$color-gray1;
            }
        }
        &:focus {
            outline: abstracts-variables.$border-width-default
                abstracts-variables.$border-style-dotted colors.$color-gray11;
            border: 0;
        }
        &:active {
            outline: abstracts-variables.$border-width-default
                abstracts-variables.$border-style-dotted colors.$color-gray11;
        }
    }

    // Set top margin to give space to preceding content and stop 'jump' effect when first button is clicked
    &:first-of-type {
        margin-top: measurements.$measure--basic;
    }

    &[data-open='true'] {
        margin-top: measurements.$measure--basic;
        border-bottom: 0;

        &:focus,
        &:active {
            outline: 0;
        }

        button {
            border-top: abstracts-variables.$border-width-default
                abstracts-variables.$border-style-dotted colors.$color-gray11;
            border-left: abstracts-variables.$border-width-default
                abstracts-variables.$border-style-dotted colors.$color-gray11;
            border-right: abstracts-variables.$border-width-default
                abstracts-variables.$border-style-dotted colors.$color-gray11;
            border-bottom: abstracts-variables.$border-width-hairline
                abstracts-variables.$border-style-solid colors.$color-gray3;
            color: colors.$color-gray11;
            padding: 0;

            .accordion__heading__text,
            .accordion__heading__indicator {
                padding: measurements.$measure--basic;
            }

            .accordion__heading__text {
                &:hover {
                    @include include-media.media('hover') {
                        text-decoration: underline;
                    }
                }
            }

            .accordion__heading__indicator {
                &:before {
                    content: functions.fa-content(variables.$var-minus);
                    display: inline-block;
                    text-decoration: none;
                }
            }

            &:focus,
            &:active {
                border-top: abstracts-variables.$border-width-default
                    abstracts-variables.$border-style-dotted
                    colors.$color-gray11;
                border-left: abstracts-variables.$border-width-default
                    abstracts-variables.$border-style-dotted
                    colors.$color-gray11;
                border-right: abstracts-variables.$border-width-default
                    abstracts-variables.$border-style-dotted
                    colors.$color-gray11;
                border-bottom: abstracts-variables.$border-width-hairline
                    abstracts-variables.$border-style-solid colors.$color-gray3;
                outline: 0;
            }

            &:hover {
                @include include-media.media('hover') {
                    background: colors.$color-gray1;
                    color: colors.$color-gray11;
                }
            }
        }

        & + .accordion__body {
            border-top: 0;
            border-left: abstracts-variables.$border-width-default
                abstracts-variables.$border-style-dotted colors.$color-gray11;
            border-right: abstracts-variables.$border-width-default
                abstracts-variables.$border-style-dotted colors.$color-gray11;
            border-bottom: abstracts-variables.$border-width-default
                abstracts-variables.$border-style-dotted colors.$color-gray11;

            p {
                margin: measurements.$measure--basic 0;
            }

            &:focus,
            &:active {
                /// body with border on focus only
                border-style: abstracts-variables.$border-style-dotted;
                border-color: colors.$color-gray11;
            }

            & > :first-child {
                margin-top: 0;
            }

            & > :last-child {
                margin-bottom: 0;
            }
        }

        & + .accordion__body:first-child {
            margin-top: 0;
        }
    }
}

.js .accordion {
    @include include-media.media('screen') {
        & > .accordion__body {
            background-color: colors.$color-gray1;
            padding: measurements.$measure--basic;
        }

        & > .accordion__heading {
            @include accordion();

            &[data-open='true'] {
                button {
                    background: colors.$color-gray1;
                }

                & + .accordion__body {
                    margin-bottom: measurements.$measure--basic;
                }
            }

            & + .accordion__body {
                overflow-y: hidden;
                transition-duration: abstracts-variables.$transition-duration;
                transition-property: height;
                transition-timing-function: abstracts-variables.$transition-function;

                &[data-closed='true'] {
                    display: none;
                }
            }
        }
    }
}
