@use '../../../abstracts/media' as include-media;
@use '../../../abstracts/colors';
@use '../../../abstracts/functions';
@use '../../../abstracts/measurements';
@use '../../../abstracts/mixins';
@use '../../../abstracts/variables';
@use '../../../anchors/outline';
@use '../../../base/typography';

.v26-finder__query {
    padding: measurements.$measure--small2 measurements.$measure--basic
        measurements.$measure--medium3 measurements.$measure--basic;

    @include include-media.media('<small') {
        padding: measurements.$measure--small2 measurements.$measure--basic
            measurements.$measure--small2 measurements.$measure--basic;
    }
}

.v26-finder__query__input__wrapper {
    position: relative;
    display: flex;
    background: colors.$color-purewhite;
    padding: measurements.$measure--quarter;
    border: variables.$border-width-hairline solid colors.$color-gray8;
    width: 100%;
    max-width: 40rem;

    input {
        @include typography.font-family('default');
        @include typography.body-font-features();
        @include typography.alphatype();
        width: calc(
            100% - #{measurements.$measure--medium3}
        ); //100% minus the width of the submit button, helps keep the submit as a circle on mobile
        border: none;
        padding: measurements.$measure--half measurements.$measure--basic;
        &:focus {
            @include outline.outline-properties(colors.$color-gray11);
        }
        &::placeholder {
            font-style: italic;
        }
    }
    .v26-finder__query__submit {
        background: colors.$color-red50;
        color: white;
        padding: measurements.$measure--basic;
        margin-left: auto;
        &:hover {
            background: colors.$color-red60;
        }
        &:focus {
            @include outline.outline-properties(colors.$color-gray11);
        }
        @include include-media.media('<small') {
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: measurements.$measure--small2;
            height: measurements.$measure--medium3; //The value should also be subtracted off the input width to help keep the button shape
            width: measurements.$measure--medium3;
        }
    }

    .v26-finder__query__suggestions {
        position: absolute;
        padding: measurements.$measure--basic;
        background-color: colors.$color-gray11;
        color: colors.$color-purewhite;
        width: 100%;
        top: 100%;
        left: 0;
        margin: 0;
        list-style: none;
        max-width: none;
        z-index: functions.z-index('above');
        &.hide {
            display: none;
        }

        li button {
            &:focus {
                @include outline.outline-properties(colors.$color-purewhite);
            }
        }
    }
}

.v26-finder__query__submit__icon {
    display: none;
    color: colors.$color-purewhite;
    @include include-media.media('<small') {
        display: block;
    }
}
.v26-finder__query__submit__text {
    display: block;
    color: colors.$color-purewhite;
    @include include-media.media('<small') {
        display: none;
    }
}

.v26-finder__clear {
    display: flex;
    color: colors.$color-gray11;
    justify-content: center;
    align-items: center;
    padding: 0 measurements.$measure--threequarters;

    &:focus {
        @include outline.outline-properties(colors.$color-gray11);
    }

    .v26-finder__clear__text {
        @include mixins.sr-only();
    }
}
