@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../base/content';

@use './card--mixin' as *;

.finder__results__list,
.search__results {
    .card--research {
        @include search-contact-research-card();
    }
}

.card--research {
    @include contact-research-card();
}

.related-content {
    .card {
        &.card--research {
            background-color: colors.$color-purewhite;
            .card__details__text {
                padding: measurements.$measure--basic;
                .card--research__title-link {
                    @include content.h4style();
                    margin-top: 0;
                }
                .card__tag {
                    display: flex;
                    align-items: baseline;
                    .icon {
                        min-width: measurements.$measure--small2;
                    }
                }
            }
        }
    }
}
