}

main table thead tr {
  color: #ffffff;
}

main table thead tr:first-child th {
  background: #0c0c0e;
}

main table thead tr:nth-child(2) th {
  background: #1e1e1e;
}

main table thead tr .heading__secondary {
  background: #1e1e1e;
}

main table thead td,
main table thead th {
  padding: 1rem 0.5rem;
  vertical-align: middle;
}

main table tbody {
  color: #1e1e1e;
  background: #ffffff;
}

main table tbody tr:hover {
  background-color: #e5e5e5;
}

main table tbody th,
main table tbody td {
  padding: 0.5rem;
  vertical-align: bottom;
}

/* Banned embeds – these are not accessible so cannot be allowed on the website. */
iframe[src*=issuu], iframe[src*=prezi] {
  display: none !important;
}

.sr-only {
  border: 0;
  clip: rect(0, 0, 0, 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  padding: 0;
  position: absolute;
  width: 1px;
}

.sr-only-focusable-within:active, .sr-only-focusable-within:focus, .sr-only-focusable-within:focus-within {
  clip: auto;
  height: auto;
  margin: 0;
  overflow: visible;
  position: static;
  width: auto;
}

/**
    Used where card has two divs, one most likely
    being a thumbnail.
**/
.heading-centered {
  text-align: center;
}

.heading-centered:after {
  content: "";
  width: 2.5rem;
  height: 0.25rem;
  display: block;
  background: #d61726;
  margin: 0.25rem auto 1rem auto;
}

/**
 *  Example HTML
 *
 *  <div class="wrapper--text-highlight">
 *      <p class="text-highlight"><span>Highlighted text</span></p>
 *  </div> 
**/
.wrapper--text-highlight .text-highlight {
  background: #832c9e;
  color: #ffffff;
  font-weight: 500;
  display: inline;
  line-height: 2rem;
  box-shadow: 0.5rem 0 0 #832c9e, -0.5rem 0 0 #832c9e;
  box-decoration-break: clone;
}

.wrapper--text-highlight {
  max-width: 40ch;
}

.standard-grid-wrapper {
  grid-template-columns: repeat(18, 1fr);
  grid-column-gap: 0;
}

@media (min-width: 768px) {
  .standard-grid-wrapper {
    grid-column-gap: 1rem;
  }
}
@media (min-width: 901px) {
  .standard-grid-wrapper {
    grid-column-gap: 1.5rem;
  }
}
.standard-grid-wrapper {
  display: grid;
}

html {
  background-color: #f2f2f2;
  color: #1e1e1e;
  box-sizing: border-box;
  min-height: 100%;
  overflow-x: hidden;
  overflow-y: scroll;
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
}
body {
  min-height: 100vh;
  position: relative;
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  body {
    scroll-behavior: auto;
  }
}
*,
*:before,
*:after {
  box-sizing: inherit;
}

.logo {
  display: block;
  width: 4rem;
}

main article {
  background-color: #ffffff;
  grid-column: 1/-1;
  height: max-content;
}

main article:not(.container--no-shadow) {
  box-shadow: 0 0.25rem 1rem 0 rgba(0, 0, 0, 0.15);
}

main article .content-wrapper {
  grid-template-columns: repeat(24, 1fr);
  grid-column-gap: 0;
}

@media (min-width: 768px) {
  main article .content-wrapper {
    grid-column-gap: 1rem;
  }
}
@media (min-width: 901px) {
  main article .content-wrapper {
    grid-column-gap: 1.5rem;
  }
}
main article .content-wrapper {
  display: grid;
}

main article .content {
  margin-left: 1rem;
  margin-right: 1rem;
  max-width: 80rem;
}

@media (min-width: 901px) {
  main article .content {
    margin-left: 1.5rem;
    margin-right: 1.5rem;
  }
}
