  grid-column: 1/-1;
  padding: 0.5rem;
}

@media (min-width: 1024px) {
  main article .content {
    grid-column: 2/-2;
    margin: 0;
  }
}
main .navigation--secondary {
  grid-column: 1/span 6;
}

main .navigation--secondary + article {
  grid-column: 7/span 18;
}

