@use '../../abstracts/media' as include-media;
@use '../../abstracts/measurements';
@use '../../layout/grid';

.imageColLayout-wrap__section {
    @include grid.standard-grid();

    h2 {
        grid-column: 1/-1;
    }
}

.imageColLayout {
    &.imageColLayout--2,
    &.imageColLayout--3 {
        @include include-media.media('>between') {
            display: flex;
            .imageColLayout--card {
                &:not(:last-of-type) {
                    padding-right: measurements.$measure--basic;
                }
            }
        }
    }
    column-count: 3;
    column-gap: measurements.$measure--small2;
    grid-column: 1/-1;
    margin: measurements.$measure--basic 0;

    @include include-media.media('<=tablet') {
        column-count: 1;
    }
}

.imageColLayout--card {
    display: inline-block;
    width: 100%;
    @include include-media.media('<=tablet') {
        img {
            width: 100%;
        }
    }
}

.imageColLayout-card--image {
    img {
        min-width: 100%;
    }
}
