@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/variables';
@use '../../anchors/navigation';
@use '../../anchors/outline';
@use '../../base/content';
@use '../../base/typography';

.navigation--secondary__header {
    display: none;
}

.navigation--secondary {
    display: none;

    @include include-media.media('>=small') {
        display: block;
        margin-top: measurements.$measure--small2;

        .navigation__level2,
        .navigation__level3 {
            background-color: colors.$color-gray1;
        }

        .navigation__level3,
        .navigation__level4,
        .navigation__level5,
        .navigation__level6 {
            list-style: none;
            margin-left: 0;
            margin-top: 0;
            max-width: unset;

            & > li > .navigation__controls {
                & > button {
                    align-self: center;
                    margin-left: measurements.$measure--threequarters;
                    margin-right: measurements.$measure--threequarters;
                    padding-bottom: measurements.$measure--quarter;
                    padding-left: measurements.$measure--quarter;
                    padding-right: measurements.$measure--quarter;
                    padding-top: measurements.$measure--quarter;
                }
            }

            li {
                &.navigation__current > .navigation__controls > a > span {
                    display: inline;
                    border-bottom: variables.$border-width-default
                        variables.$border-style-solid colors.$color-red50;
                }
            }
        }

        .navigation__level3,
        .navigation__level4 {
            li {
                @include content.content-style();
                @include typography.smalltype();

                max-width: unset;

                &.navigation__hierarchy > .navigation__controls > a {
                    span {
                        border-bottom: variables.$border-width-default
                            variables.$border-style-solid
                            colors.$color-nearblack;
                    }
                }

                &.navigation__current > .navigation__controls > span:focus {
                    outline: none;

                    > span {
                        @include outline.outline-properties(
                            colors.$color-nearblack
                        );
                    }
                }
            }
        }

        .navigation__level5,
        .navigation__level6 {
            li {
                @include content.content-style();
                @include typography.smalltype();

                font-weight: variables.$font-weight-text;
                max-width: unset;

                &.navigation__hierarchy > .navigation__controls > a {
                    span {
                        border-bottom: variables.$border-width-default
                            variables.$border-style-solid
                            colors.$color-nearblack;
                    }
                }

                &.navigation__current > .navigation__controls > span:focus {
                    outline: none;

                    > span {
                        @include outline.outline-properties(
                            colors.$color-nearblack
                        );
                    }
                }
            }
        }

        .navigation__level3 {
            color: colors.$color-nearblack;

            > li {
                line-height: typography.$line-height-ratio--body;
            }

            & > li > .navigation__controls {
                border-bottom: variables.$border-width-hairline
                    variables.$border-style-solid colors.$color-gray4;

                & > a {
                    @include navigation.navigation-anchor(
                        colors.$color-nearblack,
                        colors.$color-gray1,
                        colors.$color-nearblack,
                        colors.$color-gray2,
                        colors.$color-nearblack
                    );
                }

                & > button {
                    @include navigation.navigation-button(
                        colors.$color-nearblack,
                        colors.$color-gray1,
                        colors.$color-gray2,
                        colors.$color-nearblack
                    );
                }

                & > a,
                & > span {
                    padding-left: measurements.$measure--half;
                }
            }
        }

        .navigation__level4 {
            background-color: colors.$color-gray2;
            color: colors.$color-nearblack;

            > li {
                line-height: typography.$line-height-ratio--body;
            }

            & > li > .navigation__controls {
                & > a {
                    @include navigation.navigation-anchor(
                        colors.$color-nearblack,
                        colors.$color-gray2,
                        colors.$color-nearblack,
                        colors.$color-gray4,
                        colors.$color-nearblack
                    );
                }

                & > button {
                    @include navigation.navigation-button(
                        colors.$color-nearblack,
                        colors.$color-gray2,
                        colors.$color-gray4,
                        colors.$color-nearblack
                    );
                }

                & > a,
                & > span {
                    padding-left: #{2 * measurements.$measure--half};
                }
            }
        }

        .navigation__level5 {
            background-color: colors.$color-gray3;
            color: colors.$color-nearblack;

            & > li > .navigation__controls {
                & > a {
                    @include navigation.navigation-anchor(
                        colors.$color-nearblack,
                        colors.$color-gray3,
                        colors.$color-nearblack,
                        colors.$color-gray5,
                        colors.$color-nearblack
                    );
                }

                & > button {
                    @include navigation.navigation-button(
                        colors.$color-nearblack,
                        colors.$color-gray3,
                        colors.$color-gray5,
                        colors.$color-nearblack
                    );
                }

                & > a,
                & > span {
                    padding-left: #{3 * measurements.$measure--half};
                }
            }
        }

        .navigation__level6 {
            background-color: colors.$color-gray4;
            color: colors.$color-nearblack;

            & > li > .navigation__controls {
                & > a {
                    @include navigation.navigation-anchor(
                        colors.$color-nearblack,
                        colors.$color-gray4,
                        colors.$color-nearblack,
                        colors.$color-gray6,
                        colors.$color-nearblack
                    );
                }

                & > button {
                    @include navigation.navigation-button(
                        colors.$color-nearblack,
                        colors.$color-gray4,
                        colors.$color-gray6,
                        colors.$color-nearblack
                    );
                }

                & > a,
                & > span {
                    padding-left: #{4 * measurements.$measure--half};
                }
            }
        }

        .navigation__level7 {
            background-color: colors.$color-gray5;
            color: colors.$color-nearblack;

            & > li > .navigation__controls {
                & > a {
                    @include navigation.navigation-anchor(
                        colors.$color-nearblack,
                        colors.$color-gray5,
                        colors.$color-nearblack,
                        colors.$color-gray7,
                        colors.$color-nearblack
                    );
                }

                & > button {
                    @include navigation.navigation-button(
                        colors.$color-nearblack,
                        colors.$color-gray5,
                        colors.$color-gray7,
                        colors.$color-nearblack
                    );
                }

                & > a,
                & > span {
                    padding-left: #{5 * measurements.$measure--half};
                }

                a > span {
                    display: inline;
                    border-bottom: variables.$border-width-default
                        variables.$border-style-solid colors.$color-red60;
                }
            }
        }

        & > .navigation--secondary__header {
            @include content.h6style();

            background-color: colors.$color-gray1;
            color: colors.$color-nearblack;
            display: block;
            line-height: typography.$line-height-ratio--body;
            margin-top: 0;

            a {
                @include navigation.navigation-anchor(
                    $color: colors.$color-nearblack,
                    $background: colors.$color-gray1,
                    $hover-color: colors.$color-nearblack,
                    $hover-background: colors.$color-gray2,
                    $outline: colors.$color-nearblack
                );

                &,
                &:active,
                &:focus,
                &:hover {
                    border-bottom: variables.$border-width-hairline
                        variables.$border-style-solid colors.$color-gray4;
                }
            }

            a > span {
                border-bottom: variables.$border-width-default
                    variables.$border-style-solid colors.$color-nearblack;
            }

            a,
            & > span {
                display: block;
                padding-bottom: measurements.$measure--half;
                padding-left: measurements.$measure--half;
                padding-right: measurements.$measure--half;
                padding-top: measurements.$measure--half;
                width: 100%;
            }

            & > span {
                @include outline.anchor-default-outline(
                    colors.$color-nearblack
                );

                border-bottom: variables.$border-width-hairline
                    variables.$border-style-solid colors.$color-gray4;
            }

            &.navigation--secondary__header--current {
                & > a {
                    background-color: colors.$color-gray1;
                    & > span {
                        border-bottom: variables.$border-width-default
                            variables.$border-style-solid colors.$color-red50;
                    }
                }
            }
        }

        .navigation__controls {
            display: flex;
            flex-direction: row;
            flex-wrap: nowrap;
            justify-content: space-between;
        }

        a,
        .navigation__current > .navigation__controls > span {
            display: block;
            padding: measurements.$measure--half;
            width: 100%;
        }

        li {
            margin: 0;
        }
    }
}

.js .navigation--secondary {
    .navigation__level4,
    .navigation__level5,
    .navigation__level6 {
        display: none;
    }

    li {
        &[data-open='true'] {
            & > .navigation__controls > a > span,
            & > .navigation__controls > span > span {
                font-weight: variables.$font-weight-bold;
            }

            & > ul {
                display: block;
            }
        }
    }

    button {
        .navigation__button__icon {
            &:before {
                @include typography.font-family('sharp');
                content: '\f067';
                font-weight: variables.$font-weight-light;
            }
        }

        .navigation__button__text {
            @include mixins.screenreader-only();
        }

        &[aria-expanded='true'] {
            .navigation__button__icon {
                &:before {
                    content: '\f068';
                }
            }
        }
    }
}
