@use 'sass:meta';
@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/variables';
@use '../../base/page';
@use '../../layout/grid';

// <Desktop-specific layout - secondary navigation never present
main > .landing--informational {
    @include include-media.media('<small') {
        .landing__contact {
            @include page.default-padding();
        }
    }
}

// Desktop-specific layout
main {
    @include include-media.media('>=small') {
        @include page.standard-box();
        @include grid.standard-grid();

        > .landing {
            grid-column: span 24;

            .landing__standfirst {
                p {
                    grid-column: 7 / 19;
                }
            }

            .landing__contact {
                @include grid.standard-grid();

                .landing__contact__details {
                    grid-column: 2 / span 9;
                }

                .landing__contact__location {
                    grid-column: 11 / span 13;
                }

                .landing__contact__details:only-child,
                .landing__contact__location:only-child {
                    grid-column: 2 / span 22;
                }
            }
        }
    }
}

// Desktop specific layout if secondary navigation is present
main {
    @include include-media.media('>=small') {
        .navigation--secondary {
            grid-column: 1 / span 6;

            & + .landing {
                grid-column: 7 / span 18;

                .landing__contact {
                    @include grid.content-grid();

                    .landing__contact__details {
                        grid-column: 2 / span 7;
                    }

                    .landing__contact__location {
                        grid-column: 9 / span 9;
                    }

                    .landing__contact__details:only-child,
                    .landing__contact__location:only-child {
                        grid-column: 2 / span 16;
                    }
                }
            }
        }
    }
}

// Generic styles
.landing {
    .banner {
        @include mixins.banner($color: colors.$color-gray9);
    }

    .landing__pathway {
        .pathway__heading,
        .pathway__cards {
            padding-left: 0;
            padding-right: 0;
        }
    }

    .swiper-viewport {
        @include include-media.media('>between') {
            grid-template-areas: '. . . . . . . slider-container slider-container slider-container slider-container slider-container slider-container slider-container slider-container slider-container slider-container slider-container slider-container slider-container slider-container slider-container slider-container slider-container slider-container slider-container';
        }
        @include include-media.media('<=between') {
            grid-template-areas: intial;

            .swiper-container {
                grid-column: 1 / -1;
            }

            .swiper-buttons-wrap {
                right: measurements.$measure--basic;
                bottom: measurements.$measure--half;
            }
            .swiper-indicator {
                right: measurements.$measure--huge3;
                bottom: measurements.$measure--basic;
            }
        }
    }

    .wrapper--landing__contact {
        margin-top: measurements.$measure--basic;
        padding-bottom: measurements.$measure--small4;
        padding-top: measurements.$measure--basic;

        .landing__contact__heading {
            border-bottom-style: variables.$border-style-solid;
            border-bottom-width: variables.$border-width-thicker;
            padding-bottom: measurements.$measure--half;
            text-align: left;
        }

        .landing__contact {
            .related-content {
                align-items: flex-start;
                display: inline-flex;
                flex-direction: column;

                .card--contact {
                    background: initial;
                    box-shadow: initial;

                    .card__details__text {
                        padding-left: 0;
                        padding-right: 0;
                    }
                }

                li + li {
                    @include include-media.media('<small') {
                        border-top-style: variables.$border-style-solid;
                        border-top-width: variables.$border-width-hairline;
                        padding-top: measurements.$measure--small4;
                    }
                }
            }
        }

        .landing__contact__location {
            .card--findus {
                a {
                    box-shadow: none;
                }

                .card--findus__content {
                    padding-top: 0;
                }

                .card--findus__content__header {
                    display: none;
                }
            }
        }
    }
}

@include meta.load-css('landing--informational');
@include meta.load-css('landing--functional');
@include meta.load-css('landing--latest');
@include meta.load-css('finder--mini');
