@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../anchors/mixins-cta';
@use '../../anchors/outline';
@use '../../base/page';

.event__formassembly__button {
    @include mixins-cta.cta-basic-light-bg();

    @include include-media.media('>=small') {
        display: block;
        margin-left: auto;
        margin-right: 0;
    }

    text-align: center;
}

.event__formassembly__form {
    @include page.default-padding();

    border: variables.$border-width-default variables.$border-style-solid
        colors.$color-gray3;

    .wFormHeader {
        display: none;
    }

    .wFormContainer .wForm {
        padding-top: 0;
    }

    &:focus {
        @include outline.outline-properties(colors.$color-nearblack);

        outline-offset: 0;
    }

    .wrapper--event__formassembly__form__heading {
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
    }
}

.event__formassembly__form__close-button {
    @include mixins-cta.cta-primary-light-bg(
        colors.$color-gray3,
        colors.$color-nearblack
    );

    display: block;
    margin-bottom: measurements.$measure--basic;
    margin-left: auto;
    margin-right: 0;
    margin-top: measurements.$measure--basic;

    &:hover,
    &:active {
        background-color: colors.$color-gray5;
        color: colors.$color-nearblack;
    }
}

.js .event__formassembly__form {
    overflow-y: hidden;
    transition-duration: variables.$transition-duration--long;
    transition-property: height;
    transition-timing-function: variables.$transition-function;

    &[data-open='false'] {
        display: none;
    }
}
