@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/measurements';
@use '../abstracts/mixins';
@use '../abstracts/palette';
@use '../abstracts/variables';
@use '../anchors/mixins-cta';
@use '../anchors/outline';
@use '../base/content';
@use '../base/page';
@use '../base/typography';
@use '../fontawesome-6/fa-extra';
@use '../layout/grid';

// <Desktop-specific layout - secondary navigation never present
main > .lifelong-learning {
    // Wider 'location' template area for short courses (non-City Health) to allow for application deadline
    &.shortcourse {
        .key-information--lifelong-learning-group > ul > li,
        .key-information--lifelong-learning > ul > li,
        .ki-shortc__list__head {
            @include include-media.media('>=between') {
                grid-template-areas: 'heading heading heading heading heading heading heading heading heading heading heading heading heading heading heading heading heading heading' 'date date date date date date location location location location location location location location button button button button' 'explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation';
            }
            @include include-media.media('>=tablet', '<between') {
                grid-template-areas: 'heading heading heading heading heading heading heading heading heading heading heading heading' 'date date date date location location location location location location button button' 'explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation explanation';
            }
        }
    }
    @include include-media.media('<small') {
        .key-information--lifelong-learning--bespoke {
            .key-information--lifelong-learning--bespoke__contact {
                @include grid.standard-grid();
                @include page.standard-box();

                grid-template-rows: repeat(3, auto);
                justify-items: center;

                .key-information--lifelong-learning--bespoke__contact__header {
                    grid-column: 1 / span 24;
                    grid-row: 1;
                }

                .key-information--lifelong-learning--bespoke__contact__location {
                    grid-column: 1 / span 12;
                    grid-row: 2;
                }

                .key-information--lifelong-learning--bespoke__contact__details {
                    grid-column: 13 / span 12;
                    grid-row: 2;
                }

                .key-information--lifelong-learning--bespoke__contact__related-links {
                    grid-column: 1 / span 24;
                    grid-row: 3;
                }
            }
        }

        .key-information--lifelong-learning-group,
        .key-information--lifelong-learning,
        .ki-shortc__list {
            @include grid.standard-grid();
        }

        .key-information--lifelong-learning-group,
        .ki-shortc__list {
            grid-column: 1 / -1;
        }

        .lifelong-learning__tutors,
        .lifelong-learning__testimonials {
            @include page.standard-box();
        }

        .related-content--profiles {
            @include grid.content-grid();

            .card {
                grid-column: 4 / -4;
            }
        }

        .lifelong-learning__video {
            @include page.default-margin();
        }

        .module-selector-wrapper {
            @include page.default-margin();
        }
    }

    @include include-media.media('<between') {
        .key-information--lifelong-learning--bespoke {
            .key-information--lifelong-learning--bespoke__contact {
                @include grid.standard-grid();

                grid-template-rows: repeat(4, auto);
                justify-items: center;

                .key-information--lifelong-learning--bespoke__contact__header {
                    grid-column: 1 / span 24;
                    grid-row: 1;
                }

                .key-information--lifelong-learning--bespoke__contact__location {
                    grid-column: 1 / span 24;
                    grid-row: 2;
                }

                .key-information--lifelong-learning--bespoke__contact__details {
                    grid-column: 1 / span 24;
                    grid-row: 3;
                }

                .key-information--lifelong-learning--bespoke__contact__related-links {
                    grid-column: 1 / span 24;
                    grid-row: 4;
                }
            }
        }
    }

    @include include-media.media('<tablet') {
        .related-content--profiles {
            display: initial;
        }
    }
}

// Desktop-specific layout
main {
    @include include-media.media('>=small') {
        @include page.standard-box();
        @include grid.x-column-grid(24);

        > .lifelong-learning {
            grid-column: 1 / span 24;

            .key-information--lifelong-learning--bespoke {
                .key-information--lifelong-learning--bespoke__contact {
                    @include grid.standard-grid();
                    grid-template-rows: repeat(2, auto);

                    .key-information--lifelong-learning--bespoke__contact__header {
                        grid-column: 1 / span 24;
                        grid-row: 1;
                    }

                    .key-information--lifelong-learning--bespoke__contact__location {
                        grid-column: 1 / span 8;
                        grid-row: 2;
                    }

                    .key-information--lifelong-learning--bespoke__contact__details {
                        grid-column: 9 / span 8;
                        grid-row: 2;
                    }

                    .key-information--lifelong-learning--bespoke__contact__related-links {
                        grid-column: 17 / span 8;
                        grid-row: 2;
                    }
                }
            }

            .key-information--lifelong-learning-group,
            .key-information--lifelong-learning,
            .ki-shortc__list {
                @include grid.standard-grid();
            }

            .key-information--lifelong-learning-group,
            .ki-shortc__list {
                grid-column: 1 / -1;
            }

            .lifelong-learning__tutors,
            .lifelong-learning__testimonials {
                @include grid.standard-grid();

                grid-template-rows: repeat(2, auto);

                h2 {
                    grid-column: 1 / span 24;
                }
            }

            .lifelong-learning__tutors {
                .related-content {
                    grid-column: 7 / span 12;
                }
            }

            .lifelong-learning__testimonials {
                .related-content {
                    grid-column: 1 / span 24;
                }

                .slider__controls {
                    grid-column: 1 / -1;
                }
            }

            header,
            .wrapper--lifelong-learning__introduction,
            .wrapper--lifelong-learning__announcement,
            .lifelong-learning__content,
            .wrapper--key-information--lifelong-learning,
            .lifelong-learning__tutors__wrap,
            .lifelong-learning__video,
            .lifelong-learning__contact,
            .related-content__heading,
            .lifelong-learning__testimonials,
            .related-content,
            .banner-text__content,
            .wrapper-ki-shortc {
                grid-column: 1/-1;
            }
        }
    }
}

// Desktop specific layout if secondary navigation is present
main {
    @include include-media.media('>=small') {
        .navigation--secondary {
            grid-column: 1 / span 6;

            & + .lifelong-learning {
                grid-column: 7 / span 18;
                @include grid.content-grid();

                .module-selector-wrapper,
                .lifelong-learning__related-courses,
                .related-content {
                    grid-column: 2/-2;
                }

                .banner-text {
                    .banner-text__content {
                        @include page.default-padding();
                        @include page.default-margin();
                    }
                }

                .key-information--lifelong-learning--bespoke {
                    .key-information--lifelong-learning--bespoke__contact {
                        @include grid.content-grid();
                        grid-template-rows: repeat(2, auto);

                        .key-information--lifelong-learning--bespoke__contact__header {
                            grid-column: 1 / span 18;
                            grid-row: 1;
                        }

                        .key-information--lifelong-learning--bespoke__contact__location {
                            grid-column: 1 / span 6;
                            grid-row: 2;
                        }

                        .key-information--lifelong-learning--bespoke__contact__details {
                            grid-column: 7 / span 6;
                            grid-row: 2;
                        }

                        .key-information--lifelong-learning--bespoke__contact__related-links {
                            grid-column: 13 / span 6;
                            grid-row: 2;
                        }
                    }
                }

                .key-information--lifelong-learning-group,
                .key-information--lifelong-learning,
                .ki-shortc__list {
                    @include grid.standard-grid();
                }

                .key-information--lifelong-learning-group,
                .ki-shortc__list {
                    grid-column: 1 / -1;
                }

                .lifelong-learning__tutors,
                .lifelong-learning__testimonials {
                    @include grid.content-grid();

                    grid-template-rows: repeat(2, auto);

                    h2 {
                        grid-column: 1 / span 18;
                    }

                    .related-content {
                        grid-column: 4 / span 12;
                    }
                }

                .lifelong-learning__tutors {
                    .related-content {
                        grid-column: 4 / span 12;
                    }
                }

                .related-content--profiles {
                    @include grid.content-grid();

                    .card {
                        grid-column: 4 / -4;
                    }
                }

                .lifelong-learning__testimonials {
                    .related-content {
                        grid-column: 1 / span 18;
                    }
                }
            }
        }
    }
}

// Generic styles
.lifelong-learning {
    padding-bottom: measurements.$measure--small2;
    @include mixins.banner(colors.$color-pink80);

    .related-content--profiles {
        .card {
            grid-column: 4 / -4;
            .card__details {
                justify-content: center;
            }
        }
    }

    .banner-text {
        color: colors.$color-purewhite;
        padding-bottom: measurements.$measure--basic;
        padding-top: measurements.$measure--small4;
        @include include-media.media('print') {
            color: colors.$color-nearblack;
        }
    }

    .wrapper--key-information--lifelong-learning,
    .wrapper-ki-shortc {
        background-color: colors.$color-gray1;
        border-bottom: variables.$border-width-default
            variables.$border-style-solid colors.$color-gray3;
        padding-bottom: measurements.$measure--small4;
    }

    .wrapper--lifelong-learning__introduction,
    .wrapper--lifelong-learning__announcement {
        background-color: colors.$color-pink80;
        color: colors.$color-purewhite;

        @include include-media.media('print') {
            color: colors.$color-nearblack;
        }
    }

    .wrapper--lifelong-learning__introduction {
        &:has(+ .wrapper--key-information--lifelong-learning),
        &:has(+ .wrapper-ki-shortc) {
            padding-bottom: measurements.$measure--small4;
        }
    }

    .wrapper--lifelong-learning__announcement {
        padding-bottom: measurements.$measure--small4;
    }

    .wrapper--lifelong-learning__higher-right-course {
        padding: measurements.$measure--threequarters;
        background-color: colors.$color-gray1;
        border-top: variables.$border-width-default solid colors.$color-gray3;

        .tabs__panel:not([hidden]) {
            background: colors.$color-gray13;
            .tabs__panel__content {
                @include include-media.media('>tablet', '<small') {
                    .tabs__panel__heading,
                    .tabs__panel__body {
                        grid-column: 1 / -1;
                    }
                }
            }
        }

        .tabs__links {
            justify-content: left;
        }

        .tabs .tabs__panel {
            border: variables.$border-width-default
                variables.$border-style-solid colors.$color-gray3;
        }

        .wrapper--key-information--lifelong-learning,
        .wrapper-ki-shortc {
            background-color: initial;
            border-bottom: initial;
            h2,
            h3,
            .key-information--lifelong-learning__dates,
            .ki-shortc__list__dates {
                grid-column: 1/-1;
            }
        }
    }

    time.ki__time:has(+ .ki__series-label) {
        margin-right: measurements.$measure--basic;
    }

    .ki__heading-start {
        display: inline-block;
        margin-bottom: measurements.$measure--half;
    }

    .wrapper--key-information--lifelong-learning__register-interest {
        grid-column: 1 / -1;
        @include grid.content-grid();
        margin-top: measurements.$measure--basic;

        @include include-media.media('<between') {
            @include grid.standard-grid();
            display: none;
        }

        .key-information--lifelong-learning__register-interest {
            grid-column: 1/-1;
            @include include-media.media('>=small') {
                grid-column: 7/-2;
            }
            @include include-media.media('>=between', '<small') {
                grid-column: 9/-2;
            }
            @include include-media.media('>=tablet', '<between') {
                grid-column: 11/-2;
            }
            @include include-media.media('>=mobile', '<tablet') {
                grid-column: 2/-2;
            }
            @include include-media.media('>=mobile') {
                display: flex;
                justify-content: flex-end;
            }
            p {
                margin: auto measurements.$measure--basic;
                @include include-media.media('<mobile') {
                    text-align: center;
                    margin: measurements.$measure--basic 0
                        measurements.$measure--basic;
                }
            }
            .cta-block__cta {
                margin-top: 0;
                @include include-media.media('<mobile') {
                    margin: 0 measurements.$measure--basic;
                }
                a {
                    border: variables.$border-width-default
                        variables.$border-style-solid colors.$color-pink90;
                    color: colors.$color-pink90;
                    &:hover {
                        background: colors.$color-pink90;
                        color: colors.$color-purewhite;
                    }
                }
            }
        }

        // Controls visibility of Register interest button outside Key Information section's entry points
        &[data-onload-mobile-only='false'] {
            display: grid;
        }

        &[data-onload-mobile-only='true'] {
            display: none;
            @include include-media.media('<between') {
                display: grid;
            }
        }
    }

    .lifelong-learning__announcement__event {
        position: relative;

        .lifelong-learning__announcement__event--title {
            position: relative;
            top: measurements.$measure--small3;
            background-color: colors.$color-nearblack;
            color: colors.$color-purewhite;
            width: fit-content;
            padding: measurements.$measure--half measurements.$measure--half
                measurements.$measure--half measurements.$measure--basic;

            &:after {
                content: '';
                position: absolute;
                top: 0;
                right: -(measurements.$measure--small4);
                width: measurements.$measure--small4;
                height: 100%;
                background: linear-gradient(
                    to top left,
                    #ffffff00 0%,
                    #ffffff00 50%,
                    colors.$color-nearblack 50%,
                    colors.$color-nearblack 100%
                );
            }

            h2 {
                @include content.h5style();
                margin-top: initial;
            }
        }
    }

    .lifelong-learning__introduction,
    .lifelong-learning__announcement {
        @include page.default-margin();
        @include page.default-padding();

        @include include-media.media('<tablet') {
            padding-left: 0;
            padding-right: 0;
        }
    }

    .lifelong-learning__introduction {
        .standfirst {
            margin-top: initial;
        }
    }

    .lifelong-learning__announcement {
        padding-bottom: measurements.$measure--basic;
    }

    .lifelong-learning__announcement__event--content {
        @include typography.smalltype();
        width: fit-content;
        padding: measurements.$measure--medium2 measurements.$measure--basic
            measurements.$measure--basic measurements.$measure--basic;
        background-color: colors.$color-purewhite;
        color: colors.$color-nearblack;
        border-radius: measurements.$measure--half;

        p {
            @include typography.smalltype();
            margin-top: initial;
        }
    }

    .lifelong-learning__selling-points__background {
        background: linear-gradient(
            180deg,
            colors.$color-pink80 50%,
            colors.$color-gray1 50%
        );
        background-repeat: no-repeat;
        border-bottom: variables.$border-width-default
            variables.$border-style-solid colors.$color-gray3;
        padding-bottom: measurements.$measure--small3;
    }

    .lifelong-learning__selling-points {
        @include page.default-margin();
        @include page.default-padding();

        background-color: colors.$color-purewhite;
        border: variables.$border-style-solid variables.$border-width-hairline
            colors.$color-gray3;
        padding-bottom: measurements.$measure--small2;
        padding-top: measurements.$measure--small2;

        @include include-media.media('>=desktop') {
            display: flex;
            flex-direction: row;
            flex-wrap: nowrap;
            padding-bottom: measurements.$measure--medium5;
            padding-top: measurements.$measure--medium5;
        }
    }

    .lifelong-learning__selling-points__card {
        display: flex;
        margin-bottom: measurements.$measure--small4;

        &:last-child {
            margin-bottom: 0;
        }

        @include include-media.media('>=desktop') {
            margin-bottom: 0;
            margin-right: measurements.$measure--small2;

            &:last-of-type {
                margin-right: 0;
            }
        }

        .icon {
            font-size: measurements.$measure--small5;
            min-width: measurements.$measure--medium3;
            margin-right: measurements.$measure--small4;

            @include include-media.media('>mobile') {
                min-width: measurements.$measure--medium2;
            }

            @include include-media.media('>between') {
                margin-right: measurements.$measure--basic;
            }
        }

        &:nth-child(1) {
            .icon {
                color: colors.$color-green50;
            }
        }

        &:nth-child(2) {
            .icon {
                color: colors.$color-teal50;
            }
        }

        &:nth-child(3) {
            .icon {
                color: colors.$color-purple50;
            }
        }
    }

    .lifelong-learning__selling-points__title {
        font-weight: variables.$font-weight-bold;
    }

    .key-information--lifelong-learning-group,
    .key-information--lifelong-learning {
        grid-template-rows: repeat(2, auto);

        > h2,
        h3 {
            color: colors.$color-pink80;
        }

        > h2 {
            grid-column: 2 / -2;
        }

        > h3 {
            grid-column: 1 / -1;
        }

        .key-information--lifelong-learning__icon {
            margin-right: measurements.$measure--basic;
        }

        > ul,
        > .pagination__wrapper {
            grid-column: 2 / -2;
            max-width: unset;
        }

        > .key-information--lifelong-learning__controls {
            grid-column: 2 / -2;
            justify-content: center;
        }

        > ul > li {
            background-color: colors.$color-purewhite;
            border: variables.$border-width-hairline
                variables.$border-style-solid colors.$color-gray3;
            padding: 0 measurements.$measure--basic measurements.$measure--basic
                measurements.$measure--basic;
        }

        > ul > li > ul {
            margin-left: 0;
            margin-right: 0;
        }
    }

    .ki-shortc {
        grid-template-rows: repeat(2, auto);
    }

    .ki-shortc__list {
        grid-template-rows: repeat(2, auto);
        .ki-shortc__list__dates {
            background-color: colors.$color-purewhite;
            border: variables.$border-width-hairline
                variables.$border-style-solid colors.$color-gray3;
            padding: 0 measurements.$measure--basic measurements.$measure--basic
                measurements.$measure--basic;
            grid-column: 2 / -2;
            max-width: unset;
        }

        .ki-shortc__list__head {
            color: colors.$color-pink80;
        }
    }

    .lifelong-learning__start-date__cta {
        text-align: center;

        .cta-block__cta > span {
            @include typography.smalltype();
            display: block;
        }
    }

    .related-content__heading {
        @include content.heading--centered(colors.$color-pink80);
    }

    .lifelong-learning__related-courses {
        padding-bottom: measurements.$measure--medium8;
        padding-top: measurements.$measure--medium8;
    }

    .lifelong-learning__tutors__wrap {
        display: flex;
        flex-direction: column;
        justify-content: center;
    }

    .lifelong-learning__tutors,
    .lifelong-learning__testimonials {
        padding-bottom: measurements.$measure--medium8;
        padding-top: measurements.$measure--medium8;

        h2 {
            @include content.heading--centered(colors.$color-pink80);
        }

        .related-content {
            display: flex;
            flex-direction: column;
            justify-content: center;
        }
    }

    .slider:not([data-small='true']) {
        margin-bottom: 0;
    }

    .lifelong-learning__testimonials {
        .related-content {
            .card__details {
                justify-content: center;
            }
        }
    }

    .lifelong-learning__video {
        background: colors.$color-red5;
        margin-bottom: measurements.$measure--basic;
        padding: 0 measurements.$measure--basic;
        @include include-media.media('>=tablet') {
            padding: 0 measurements.$measure--small4;
        }

        .embedded-video {
            padding: measurements.$measure--basic 0;
            @include include-media.media('>=tablet') {
                padding: measurements.$measure--small4 0;
            }
        }
    }

    @include include-media.media('>=tablet') {
        .tabs .tabs__panel {
            border: variables.$border-width-default
                variables.$border-style-solid colors.$color-gray3;
        }
    }

    .lifelong-learning__content {
        margin-top: measurements.$measure--basic;

        & + .lifelong-learning__contact {
            margin-top: measurements.$measure--small4;
        }

        .overview__subject-wrapper {
            margin-top: measurements.$measure--basic;
            padding: measurements.$measure--basic;
            background-color: colors.$color-pink90;
            color: colors.$color-purewhite;

            h3 {
                margin-top: 0;
            }

            .cta-block {
                a {
                    @include mixins-cta.cta-basic-light-bg(
                        colors.$color-gray3,
                        palette.$color-text
                    );

                    &:focus,
                    &:active {
                        @include outline.anchor-default-outline(
                            palette.$color-outline--dark
                        );
                    }
                }
            }
        }
    }

    .lifelong-learning__contact {
        @include page.default-padding();

        background-color: colors.$color-pink90;
        color: colors.$color-purewhite;
        display: flex;
        flex-direction: column;
        justify-content: space-evenly;
        padding-bottom: measurements.$measure--small4;
        padding-top: measurements.$measure--small4;

        @include include-media.media('<small') {
            @include page.default-margin();
        }

        @include include-media.media('>=between') {
            flex-direction: row;
        }

        .lifelong-learning__contact__heading {
            margin-top: 0;
            text-align: center;

            @include include-media.media('>=between') {
                align-self: center;
                text-align: left;
            }
        }

        .cta-block {
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            max-width: unset;

            @include include-media.media('<between') {
                @include typography.smalltype();
            }

            @include include-media.media('>=desktop') {
                flex-direction: row;
            }

            li {
                align-self: stretch;
                margin-top: measurements.$measure--basic;

                @include include-media.media('<desktop') {
                    margin-right: 0;
                }

                @include include-media.media('>=desktop') {
                    margin-right: measurements.$measure--basic;
                    margin-top: 0;
                }

                a {
                    @include mixins-cta.cta-basic-light-bg(
                        colors.$color-gray3,
                        palette.$color-text
                    );

                    align-self: stretch;
                    display: flex;
                    justify-content: center;

                    &:focus,
                    &:active {
                        @include outline.anchor-default-outline(
                            palette.$color-outline--dark
                        );
                    }

                    &,
                    &:active,
                    &:focus,
                    &:hover {
                        span {
                            .fa-phone {
                                @include fa-extra.fa-icon-rotate(90deg, 1);
                            }
                        }
                    }
                }
            }
        }
    }

    .wrapper--text-highlight-block {
        background: colors.$color-purewhite;
        margin-top: measurements.$measure--basic;
        border: variables.$border-width-hairline variables.$border-style-solid
            colors.$color-gray2;
    }

    .text-highlight-block {
        @include page.default-padding();
        padding-top: measurements.$measure--basic;
        padding-bottom: measurements.$measure--small1;
        background-image: url('https://www.citystgeorges.ac.uk/__data/assets/file/0006/698784/grey-stripes.svg');
        background-size: 10%;

        .text-highlight__preheading {
            @include mixins.text-highlight(
                palette.$color-lifelong-learning--lead,
                colors.$color-purewhite,
                variables.$font-weight-normal
            );
        }

        .text-highlight__heading {
            margin: 0;
            span {
                @include mixins.text-highlight(
                    palette.$color-lifelong-learning--accent,
                    colors.$color-purewhite,
                    variables.$font-weight-normal
                );
                margin-bottom: measurements.$measure--half;
                padding: measurements.$measure--quarter 0;
                font-weight: variables.$font-weight-normal;
            }
        }
    }

    .text-highlight__body {
        @include page.default-padding();
        padding-bottom: measurements.$measure--small3;
    }

    .text-highlight__body__intro {
        font-weight: variables.$font-weight-medium;
    }
}

.ki__series-label {
    @include typography.smalltype();
    text-transform: uppercase;
    display: inline-flex;
    align-items: center;
    background: palette.$color-ki-label-bg;
    border: variables.$border-width-default solid palette.$color-ki-label-border;
    color: palette.$color-ki-label-txt;
    padding: measurements.$measure--quarter measurements.$measure--threequarters;
    border-radius: measurements.$measure--quarter; // 0.25rem
    font-weight: variables.$font-weight-bold; // 700
    margin-right: measurements.$measure--basic;
    &:last-child {
        margin-right: 0;
    }
}

.ki__series-label::before {
    content: '';
    width: 0.625rem; // 10px
    height: 0.625rem;
    background: palette.$color-ki-label-txt;
    border-radius: 50%;
    display: inline-block;
    margin-right: 0.625rem;
}

.ki__series-label--alt {
    background: palette.$color-ki-label-bg--alt;
    border: variables.$border-width-default solid
        palette.$color-ki-label-border--alt;
    color: palette.$color-ki-label-txt--alt;
}

.ki__series-label--alt::before {
    background: palette.$color-ki-label-txt--alt;
}

@mixin display-tabs-content(
    $link-background: colors.$color-purewhite,
    $panel-background: colors.$color-gray1,
    $panel-border-color: colors.$color-gray3
) {
    @include page.standard-box();

    background-color: $link-background;
    padding-top: measurements.$measure--small4;

    .tabs__links {
        display: none;
    }

    .tabs__panel {
        background-color: $panel-background;
        border-top: 0;
        padding: 0;

        @include include-media.media('>=tablet') {
            border: variables.$border-width-default
                variables.$border-style-solid $panel-border-color;
        }

        &[hidden] {
            display: block;
        }

        &:not([hidden]) {
            .tabs__panel__content {
                margin-left: 0;
                margin-right: 0;
            }
        }
    }

    .tabs__panel__heading {
        @include content.heading--centered(colors.$color-pink80);
    }
}

@include include-media.media('screen') {
    .js .lifelong-learning .modal__content,
    .js .lifelong-learning .modal__content a:not(:hover):not(:active) {
        color: palette.$color-text;
    }

    .js .lifelong-learning .paginated-list .page ul,
    .js .lifelong-learning .paginated-list .page ol {
        list-style-type: none;
        margin-left: 0;
    }

    .js .lifelong-learning .modal__trigger {
        @include mixins-cta.cta-basic-light-bg(
            colors.$color-red50,
            colors.$color-purewhite
        );
        padding: measurements.$measure--threequarters
            measurements.$measure--small2;
    }

    .js .lifelong-learning__content .tabs__links {
        @include page.default-margin();
    }

    .js .lifelong-learning__content .accordion {
        @include page.default-margin();
    }

    .js .lifelong-learning__content > div:not(.tabs):not(.tabs--accordion) {
        @include display-tabs-content();
    }

    .js .lifelong-learning--bespoke .tabs {
        @include include-media.media('<tablet') {
            @include display-tabs-content();
        }
    }

    .js main {
        > .lifelong-learning {
            .lifelong-learning__content .tabs__panel:not([hidden]) {
                padding: 0;

                .tabs__panel__content {
                    @include grid.standard-grid();

                    grid-template-rows: repeat(2, auto);

                    @include include-media.media('<=mobile') {
                        @include page.default-padding();
                    }

                    .tabs__panel__heading {
                        grid-row: 1;
                    }

                    .tabs__panel__body {
                        grid-row: 2;
                    }
                }
            }
        }

        > .navigation--secondary + .lifelong-learning {
            .lifelong-learning__content .tabs__panel:not([hidden]) {
                > .tabs__panel__content {
                    @include include-media.media('>=small') {
                        @include grid.content-grid();
                    }
                }
            }
        }
    }
}

.js main {
    > .lifelong-learning {
        .lifelong-learning__content > div:not(.tabs):not(.tabs--accordion) {
            > .tabs__panel {
                @include grid.standard-grid();

                grid-template-rows: repeat(2, auto);
                padding: 0;

                @include include-media.media('<=mobile') {
                    @include page.default-padding();
                }

                .tabs__panel__heading {
                    grid-row: 1;
                }

                .tabs__panel__body {
                    grid-row: 2;
                }

                .tabs__panel__heading,
                .tabs__panel__body {
                    grid-row: 2;
                    grid-column: 1 / span 24;

                    @include include-media.media('>mobile', '<=between') {
                        grid-column: 5 / span 16;
                    }

                    @include include-media.media('>between') {
                        grid-column: 7 / span 12;
                    }
                }
            }
        }
    }

    > .navigation--secondary + .lifelong-learning {
        .lifelong-learning__content > div:not(.tabs):not(.tabs--accordion) {
            > .tabs__panel {
                @include include-media.media('>=small') {
                    @include grid.content-grid();

                    .tabs__panel__heading,
                    .tabs__panel__body {
                        grid-column: 4 / span 12;
                    }
                }
            }
        }
    }
}

.lifelong-learning {
