@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../base/page';
@use '../../layout/grid';

.banner-text {
    color: colors.$color-purewhite;
    padding-top: measurements.$measure--medium9;
    padding-bottom: measurements.$measure--medium3;
    grid-column: 1/-1;

    .banner-text__content {
        @include page.default-margin();
        @include page.default-padding();

        @include include-media.media('<tablet') {
            padding: 0;
        }
    }

    // Centered banners, as used on Research degrees for example
    &.banner--center {
        .banner-text__content {
            @include grid.standard-grid();
            @include page.standard-box();
            h1,
            p {
                grid-column: 1/-1;
                @include include-media.media('>tablet') {
                    grid-column: 2/-2;
                }
                @include include-media.media('>between') {
                    grid-column: 3/-3;
                }
                @include include-media.media('>desktop') {
                    grid-column: 5/15;
                }
            }
        }
    }
}
