@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/functions';
@use '../abstracts/measurements';
@use '../abstracts/variables';

@keyframes slide-left-in {
    from {
        transform: translateX(-100%);
    }

    to {
        transform: none;
    }
}

@keyframes slide-right-out {
    from {
        transform: none;
    }

    to {
        transform: translateX(100%);
    }
}

@mixin ghost-out() {
    animation: slide-right-out variables.$transition-duration ease 0s both
        normal;
    background-color: colors.$color-gray3;
    bottom: 0;
    content: '';
    height: measurements.$measure--half;
    left: 0;
    opacity: 0;
    position: absolute;
    transform: translateX(105%);
    transition: opacity variables.$transition-duration ease
        variables.$transition-duration;
    width: 100%;
    z-index: functions.z-index('default');

    @include include-media.media('reducemotion') {
        animation: none;
        transition: none;
    }
}

@mixin ghost-in() {
    animation: slide-left-in variables.$transition-duration ease 0s both normal;
    opacity: 1;
    transform: translateX(-105%);
    transition: none;

    @include include-media.media('reducemotion') {
        animation: none;
        transition: none;
    }
}
