@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';

// pattern used in paint layouts
.promo-box {
    background-color: colors.$color-red50;
    background-image: linear-gradient(
        to right,
        colors.$color-red50,
        colors.$color-pink80
    );
    color: colors.$color-purewhite;
    padding: 0 measurements.$measure--small2 measurements.$measure--basic;

    a {
        border-bottom-color: colors.$color-purewhite;
        color: colors.$color-purewhite;
    }
}

.promo-box__wrapper {
    display: block;
    padding-top: measurements.$measure--small1;

    &:nth-of-type(2) {
        margin-top: measurements.$measure--small5;
    }

    @include include-media.media('>tablet') {
        display: flex;
    }
}

.promo-box__card {
    grid-column: 1/-1;
    flex: 1;
    &:nth-of-type(2) {
        margin-top: measurements.$measure--small5;
    }

    @include include-media.media('>tablet') {
        &:nth-of-type(2) {
            margin-top: 0;
        }
    }

    &:first-of-type {
        margin-right: measurements.$measure--small4;
    }
}

.promo-box__card__body {
    display: flex;

    img {
        min-width: measurements.$measure--medium4;
        max-width: measurements.$measure--medium4;
        min-height: measurements.$measure--medium4;
        max-height: measurements.$measure--medium4;
        display: block;
        margin-right: measurements.$measure--small1;
    }
}
