@use '../../abstracts/colors';
@use '../../abstracts/functions';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../anchors/cta--basic';
@use '../../base/page';

////
/// Skip links
/// @group patterns
////

.skip-links {
    background-color: colors.$color-gray10;
    border: 0;
    clip: rect(0, 0, 0, 0);
    color: colors.$color-purewhite;
    height: 1px;
    margin: -1px;
    overflow: hidden;
    padding: 0;
    position: absolute;
    width: 1px;

    .skip-links__link {
        @include cta--basic.cta--basic(
            colors.$color-purewhite,
            colors.$color-red50,
            colors.$color-purewhite,
            colors.$color-red70,
            colors.$color-purewhite,
            square
        );

        > .skip-links__intro {
            @include mixins.sr-only();
        }
    }

    &:active,
    &:focus,
    &:focus-within {
        clip: auto;
        height: auto;
        margin: 0;
        overflow: visible;
        padding-bottom: measurements.$measure--half;
        padding-top: measurements.$measure--half;
        position: relative;
        z-index: functions.z-index('above');
        width: auto;

        .skip-links__link {
            clip: auto;
            height: auto;
            margin: 0;
            overflow: visible;
            padding-bottom: measurements.$measure--half;
            padding-left: measurements.$measure--small2;
            padding-right: measurements.$measure--small2;
            padding-top: measurements.$measure--half;
            position: static;
            width: auto;
        }
    }

    .skip-links__content {
        @include page.standard-box();

        display: flex;
        flex-direction: row;

        p {
            align-self: center;
            display: flex;
            margin-bottom: measurements.$measure--quarter;
            margin-right: measurements.$measure--basic;
            margin-top: measurements.$measure--quarter;
            max-width: unset;
        }
    }

    .skip-links__content ul {
        display: flex;
        flex-direction: row;
        flex-wrap: wrap;
        list-style: none;
        margin-left: 0;
        margin-top: 0;
        max-width: unset;

        li {
            margin-bottom: measurements.$measure--quarter;
            margin-left: 0;
            margin-top: measurements.$measure--quarter;

            &:not(:last-of-type) {
                margin-right: measurements.$measure--basic;
            }
        }
    }
}
