@use 'sass:list';
@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../anchors/card/card--side-image';
@use '../../anchors/inline';

$colors: (
    blue70: colors.$color-gray4,
    pink90: colors.$color-gray4,
    red70: colors.$color-gray4,
);

@each $class, $color in card--side-image.$colors {
    $textColor: list.nth($color, 1);
    .related-links--with-images__cards {
        .card--related-links--with-images {
            &:not(.background--purewhite):not(.background--gray2) {
                &.background--#{$class} {
                    color: colors.$color-purewhite;
                    .link-decorator {
                        color: colors.$color-purewhite;
                    }
                    a {
                        @include inline.anchor-inline(
                            $textColor,
                            $textColor,
                            $textColor,
                            $textColor
                        );
                        &:hover {
                            @include include-media.media('hover') {
                                color: colors.$color-gray11;
                            }
                        }
                    }
                }
            }
        }
    }
}

.related-links--with-images__cards {
    @include include-media.media('>=tablet') {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        grid-column-gap: measurements.$measure--small2;
    }

    @include include-media.media('<tablet') {
        .card--related-links--with-images {
            &:not([data-image='true']) {
                .card--related-links--with-images__links__content {
                    padding-top: measurements.$measure--quarter;
                }
            }
        }
    }

    list-style: none;
    margin: 0;
    max-width: unset;
    padding-bottom: measurements.$measure--small1;

    .card--related-links--with-images {
        height: max-content;
        &.background--purewhite,
        &.background--gray2 {
            border: variables.$border-width-hairline
                variables.$border-style-solid colors.$color-gray1;
            &:not([data-image='true']) {
                border-top: measurements.$measure--half
                    variables.$border-style-solid colors.$color-red50;
            }
        }
        .card--related-links--with-images__links__content {
            padding: 0 measurements.$measure--basic measurements.$measure--basic
                measurements.$measure--basic;
            .card--related-links--with-images__links {
                p {
                    display: table;
                    span {
                        display: table-cell;
                        padding-right: measurements.$measure--half;
                    }
                }
            }
        }
    }
}
