@use '../abstracts/colors';
@use '../abstracts/measurements';
@use '../abstracts/palette';
@use '../abstracts/variables';
@use '../anchors/cta--basic';
@use '../anchors/outline';
@use 'content';

form:not([class]),
.form {
    fieldset {
        border: none;
        margin: 0;
        padding: 0;

        .form__label,
        label {
            @include content.content-style();

            display: block;
            margin-bottom: measurements.$measure--quarter;
            margin-top: measurements.$measure--small2;
        }

        .form__label--required {
            &:after {
                content: ' *';
                color: palette.$color-required;
            }
        }
    }

    input,
    textarea {
        @include content.body-baseline();

        &:focus {
            color: colors.$color-gray10;
            font-style: normal;
            font-weight: variables.$font-weight-medium;
            outline: 0;
        }

        &::placeholder {
            font-style: italic;
        }

        &:placeholder-shown {
            color: colors.$color-gray7;
        }

        &:not([type='submit']) {
            width: 100%;

            &:focus {
                @include outline.outline-properties();
            }
        }

        &[type='submit'] {
            @include cta--basic.cta--basic();

            -webkit-appearance: none;
            appearance: none;
            border: 0;
            margin-top: measurements.$measure--small2;

            &:active,
            &:focus {
                @include outline.outline-properties();
            }
        }
    }

    .form__submit-container {
        text-align: right;
    }

    .form__required-note--marker {
        color: palette.$color-required;
    }
}

/* FormAssembly */
.web2020 .wFormContainer {
    margin-bottom: 0;
    margin-left: 0;
    margin-right: 0;
    margin-top: 0;
    max-width: unset;

    .wForm {
        padding-left: 0;
        padding-right: 0;
    }
}
