@use 'sass:list';
@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/variables';
@use '../../anchors/card/card--side-image';

////
/// Infographic
/// @group patterns
////

card--side-image.$colors: (
    blue50: (
        colors.$color-blue50,
        colors.$color-purple50,
    ),
    purple50: (
        colors.$color-purple50,
        colors.$color-blue50,
    ),
    red50: (
        colors.$color-red50,
        colors.$color-purple50,
    )
);

.infographic {
    @include include-media.media('<tablet') {
        .infographic__panel {
            padding: measurements.$measure--small4 measurements.$measure--basic;
            &.infographic__panel__panel1.background--purple50 {
                padding-bottom: 0;
            }
        }
    }

    @include include-media.media('>=tablet') {
        display: flex;
        flex-wrap: wrap;
        .infographic__panel {
            flex: 1;
            display: flex;
            justify-content: center;
            flex-direction: column;
            padding: measurements.$measure--small4;
        }
    }

    // Panel background and text highlight
    @each $name, $color in card--side-image.$colors {
        $color-primary: list.nth($color, 1);
        $color-secondary: list.nth($color, 2);
        &[data-theme='#{$name}'] {
            .infographic__panel {
                .infographic__description__text__highlight {
                    @include mixins.text-highlight($color-primary);
                }
                &[data-theme-background='true'] {
                    .infographic__description__text__highlight {
                        @include mixins.text-highlight($color-secondary);
                    }
                }
            }
        }
    }

    .infographic__panel {
        &[data-type='image'] {
            text-align: center;
        }
        &[data-type='text'] {
            .infographic__description__text {
                margin: 0;
                color: colors.$color-purewhite;
            }
            span:not(.infographic__description__text__highlight) {
                &:not(last-of-type) {
                    margin-right: measurements.$measure--threequarters;
                }
            }
            span.infographic__description__text__highlight {
                font-weight: variables.$font-weight-medium;
                line-height: calc(
                    #{measurements.$measure--small4} + #{measurements.$measure--quarter}/
                        2
                );
                margin: 0 measurements.$measure--threequarters 0 0;
            }
        }
    }

    .infographic__caption {
        flex-basis: 100%;
        .infographic__caption__source {
            display: flex;

            a {
                margin-left: measurements.$measure--quarter;
                margin-right: measurements.$measure--quarter;
            }
        }
    }
}
