@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/variables';
@use '../../anchors/pagination';
@use '../../base/typography';

.v26-pagination__wrapper {
    @include include-media.media('print') {
        .v26-pagination__controls,
        .v26-pagination__summary {
            display: none;
        }
    }

    @include include-media.media('screen') {
        .v26-pagination__controls {
            display: flex;
            flex-wrap: nowrap;
            justify-content: flex-end;

            @include include-media.media('<tablet') {
                align-items: stretch;
                flex-wrap: wrap;
                justify-content: center;
            }

            a,
            button,
            [aria-current='page'] {
                @include pagination.anchor-v26pagination();

                span {
                    display: inline-block;
                    padding-left: measurements.$measure--basic;
                    padding-right: measurements.$measure--basic;
                }
            }
            .v26-pagination__controls__element {
                min-width: measurements.$measure--medium3;
                justify-content: center;
                text-align: center;
                @include include-media.media('<mobile') {
                    min-width: measurements.$measure--medium2;
                }
                @include include-media.media('<tiny') {
                    min-width: measurements.$measure--medium1;
                }
            }

            .v26-pagination__controls__ellipsis {
                align-items: center;
                display: flex;
                justify-content: center;
                @include include-media.media('<tablet') {
                    min-width: measurements.$measure--small3;
                }

                span {
                    display: inline-block;
                    padding-bottom: variables.$border-width-default;
                }
            }

            a,
            button,
            .v26-pagination__controls__ellipsis,
            span.v26-pagination__controls__button--next,
            span.v26-pagination__controls__button--prev,
            [aria-current='page'] {
                margin-right: measurements.$measure--half;
                margin-top: measurements.$measure--threequarters;
                min-height: variables.$minimum-control-height;
                padding-bottom: measurements.$measure--quarter;

                :before,
                span {
                    align-self: center;
                }
            }

            [data-page] {
                display: none;

                &[aria-expanded='true'],
                &[data-page='1'],
                &.v26-pagination__controls__button--last {
                    display: flex;
                }

                &[data-proximity='1'],
                &[data-proximity='-1'] {
                    @include include-media.media('>=tablet') {
                        display: flex;
                    }
                }

                &[data-proximity='2'],
                &[data-proximity='-2'] {
                    @include include-media.media('>=desktop') {
                        display: flex;
                    }
                }
            }

            [aria-current='page'] {
                display: flex;
                justify-content: center;
                flex-direction: column;
                margin-top: measurements.$measure--threequarters;
                padding-left: measurements.$measure--half;
                padding-right: measurements.$measure--half;
                align-self: center;
                border: variables.$border-style-solid
                    variables.$border-width-hairline colors.$color-nearblack;
                font-weight: variables.$font-weight-black;
            }

            .v26-pagination__controls__ellipsis {
                display: none;
            }

            &:not([data-pagecount='2']):not([data-pagecount='3']):not([data-pagecount='4']):not([data-pagecount='5']) {
                [data-page='1'] {
                    &:not([aria-expanded='true']) {
                        &:not([data-proximity='1']):not([data-proximity='-1']) {
                            & + .v26-pagination__controls__ellipsis {
                                @include include-media.media('<tablet') {
                                    display: flex;
                                }
                            }
                        }

                        &:not([data-proximity='1']):not([data-proximity='-1']):not([data-proximity='2']):not([data-proximity='-2']) {
                            & + .v26-pagination__controls__ellipsis {
                                @include include-media.media(
                                    '>=tablet',
                                    '<desktop'
                                ) {
                                    display: flex;
                                }
                            }
                        }

                        &:not([data-proximity='1']):not([data-proximity='-1']):not([data-proximity='2']):not([data-proximity='-2']):not([data-proximity='3']):not([data-proximity='-3']) {
                            & + .v26-pagination__controls__ellipsis {
                                @include include-media.media('>=desktop') {
                                    display: flex;
                                }
                            }
                        }
                    }
                }

                .v26-pagination__controls__button--penultimate {
                    &:not([aria-expanded='true']) {
                        &:not([data-proximity='-1']) {
                            & + .v26-pagination__controls__ellipsis {
                                @include include-media.media('<tablet') {
                                    display: flex;
                                }
                            }
                        }

                        &:not([data-proximity='1']):not([data-proximity='-1']) {
                            & + .v26-pagination__controls__ellipsis {
                                @include include-media.media(
                                    '>=tablet',
                                    '<desktop'
                                ) {
                                    display: flex;
                                }
                            }
                        }

                        &:not([data-proximity='1']):not([data-proximity='-1']):not([data-proximity='2']):not([data-proximity='-2']) {
                            & + .v26-pagination__controls__ellipsis {
                                @include include-media.media('>=desktop') {
                                    display: flex;
                                }
                            }
                        }
                    }
                }
            }

            .v26-pagination__controls__button--next,
            .v26-pagination__controls__button--prev {
                display: flex;

                &:before {
                    @include typography.font-family('sharp');

                    align-self: center;
                    font-size: typography.$font-size--icon;
                    font-weight: variables.$font-weight-normal;
                    padding-left: measurements.$measure--half;
                    padding-right: measurements.$measure--half;
                }
                .v26-pagination__controls__icon {
                    display: none;
                }
                @include include-media.media('<tablet') {
                    .v26-pagination__controls__icon {
                        margin-top: variables.$fontawesome-icon-shim-top; /* Visual shim to compensate for icon whitespace */
                        display: flex;
                        justify-content: center;
                    }
                    .v26-pagination__controls__txt {
                        display: none;
                        @include mixins.sr-only();
                    }
                }
            }
            span.v26-pagination__controls__button--next,
            span.v26-pagination__controls__button--prev {
                border: variables.$border-style-solid
                    variables.$border-width-hairline colors.$color-nearblack;
                color: colors.$color-nearblack;
                font-weight: variables.$font-weight-text;
                cursor: default;
                opacity: variables.$pagination-non-active-opacity;

                span {
                    display: inline-block;
                    padding-bottom: variables.$border-width-hairline;
                    padding-left: measurements.$measure--basic;
                    padding-right: measurements.$measure--basic;
                }
            }
            .v26-pagination__controls__button--next {
                margin-right: 0;
            }

            &[data-pagecount='2'],
            &[data-pagecount='3'],
            &[data-pagecount='4'],
            &[data-pagecount='5'] {
                .v26-pagination__controls__button {
                    display: flex;
                }

                .pagination__controls__ellipsis {
                    display: none;
                }
            }
        }

        .v26-pagination__summary {
            @include typography.smalltype();
            margin-top: 0;
            max-width: unset;
            text-align: right;
        }
    }
}

.content .v26-pagination__wrapper {
    @include include-media.media('screen') {
        max-width: typography.$max-line-length;
    }
}
