@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../outline';
@use '../../abstracts/variables';
@use '../../base/content';

@mixin search-contact-research-card() {
    .card__details {
        border-color: colors.$color-gray1;
        border-style: variables.$border-style-solid;
        border-width: variables.$border-width-hairline;
        display: block;

        @include include-media.media('<=between') {
            background-color: colors.$color-gray1;
        }

        .card__details__text {
            padding-bottom: measurements.$measure--basic;
        }

        .card__type {
            color: colors.$color-red50;
        }
    }
}

@mixin contact-research-card() {
    .card__details {
        .card__tag {
            .icon {
                color: colors.$color-red50;
            }
        }
    }

    .wrapper--card--contact__address {
        @include content.content-style();

        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        margin-top: variables.$content-element-margin;

        address {
            .card--contact__addressline {
                display: block;
            }
        }
    }
}

@mixin landscape-card() {
    .card__details {
        flex-direction: row;

        .card__thumbnail {
            width: measurements.$measure--huge5;
        }

        .card--news__label--news,
        .card--event__label--event {
            position: absolute;

            & + .card__thumbnail {
                margin-top: measurements.$measure--medium3;

                & + .card__details__text {
                    margin-top: measurements.$measure--medium3;
                    padding-top: 0;
                }
            }
        }
    }
}

@mixin card-anchor-colors(
    $background: transparent,
    $color: colors.$color-nearblack,
    $background-hover: colors.$color-gray1,
    $color-hover: colors.$color-nearblack,
    $color-outline: colors.$color-nearblack,
    $icon: colors.$color-red50,
    $arrow-background: colors.$color-nearblack,
    $arrow-color: colors.$color-purewhite,
    $arrow-background-hover: colors.$color-red50,
    $arrow-color-hover: colors.$color-purewhite,
    $border: colors.$color-gray1
) {
    background-color: $background;
    color: $color;

    &:focus,
    &:active {
        @include outline.outline-properties($color-outline);
    }

    &,
    &:focus,
    &:active,
    &:visited {
        border-color: $border;
        color: $color;
    }

    &:hover {
        @include include-media.media('hover') {
            background-color: $background-hover;
            border-color: $border;
            color: $color;

            &:after {
                background-color: $arrow-background-hover;
                color: $arrow-color-hover;
            }
        }
    }

    &:after {
        background-color: $arrow-background;
        color: $arrow-color;
    }

    @include include-media.media('<=between') {
        background-color: $background-hover;

        &:after {
            background-color: $arrow-background-hover;
        }
    }

    .card__type {
        color: $icon;
    }

    .card__tag {
        .icon {
            color: $icon;
        }
    }
}
