@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/functions';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../anchors/mixins-cta';
@use '../../base/typography';
@use '../../layout/grid';

.promo-area__wrap {
    padding-top: measurements.$measure--small4;
    padding-bottom: measurements.$measure--small4;

    .promo-area {
        display: grid;
        position: relative;
        margin-bottom: measurements.$measure--medium3;
        @include grid.x-column-grid(24);

        &.layout__left--full {
            .promo-area__content {
                grid-column: 2 / 13;

                @include include-media.media('<=small') {
                    grid-column: 2 / 18;
                }

                @include include-media.media('<=tablet') {
                    grid-column: 4 / 22;
                }

                @include include-media.media('<=mobile') {
                    grid-column: 3 / 23;
                }
            }
        }

        &.layout__right--full {
            .promo-area__content {
                grid-column: 13 / 24;

                @include include-media.media('<=small') {
                    grid-column: 8 / 24;
                }

                @include include-media.media('<=tablet') {
                    grid-column: 4 / 22;
                }

                @include include-media.media('<=mobile') {
                    grid-column: 3 / 23;
                }
            }
        }

        &.layout__right--full,
        &.layout__left--full {
            @include include-media.media('<tablet') {
                margin-bottom: 0;
            }

            img {
                @include include-media.media('<tablet') {
                    height: auto;
                    width: auto;
                    max-width: inherit;
                }

                @include include-media.media('<mobile') {
                    height: 100%;
                }
            }
        }

        &.layout__left--split {
            .promo-area__content {
                grid-column: 2 / 12;
                margin-right: -(measurements.$measure--medium3);

                @include include-media.media('<desktop') {
                    grid-column: 1 / 12;
                }

                @include include-media.media('<small') {
                    grid-column: 1 / 14;
                }

                @include include-media.media('<tablet') {
                    margin-right: inherit;
                }
            }

            .promo-area__image {
                grid-column: 11 / 24;
                margin-top: -(measurements.$measure--medium7);
                padding-left: measurements.$measure--small4;

                @include include-media.media('<desktop') {
                    grid-column: 11 / 25;
                }

                @include include-media.media('<small') {
                    grid-column: 8 / 25;
                }

                @include include-media.media('<between') {
                    grid-column: 11 / 25;
                    padding-left: 0;
                }
            }
        }

        &.layout__right--split {
            .promo-area__content {
                grid-column: 14 / 24;
                margin-left: -(measurements.$measure--medium3);

                @include include-media.media('<desktop') {
                    grid-column: 14 / -1;
                }

                @include include-media.media('<small') {
                    grid-column: 12 / -1;
                }

                @include include-media.media('<tablet') {
                    margin-left: inherit;
                }
            }

            .promo-area__image {
                grid-column: 2 / 15;
                margin-top: -(measurements.$measure--medium7);
                padding-right: measurements.$measure--small4;

                @include include-media.media('<desktop') {
                    grid-column: 1 / 15;
                }

                @include include-media.media('<small') {
                    grid-column: 1 / 18;
                }

                @include include-media.media('<=between') {
                    grid-column: 1 / 15;
                    padding-right: 0;
                }
            }
        }

        &.layout__left--split,
        &.layout__right--split {
            margin-top: measurements.$measure--medium7;
            margin-bottom: 0;

            @include include-media.media('<tablet') {
                margin-top: 0;
            }

            .promo-area__content {
                margin-top: 0;
                margin-bottom: 0;

                @include include-media.media('<tablet') {
                    grid-column: 2 / 24;
                    padding: measurements.$measure--basic 0 0 0;

                    .promo-area__heading {
                        margin-right: measurements.$measure--small1;
                        margin-left: measurements.$measure--small1;
                    }

                    .promo-area__container {
                        @include include-media.media('<=mobile') {
                            padding: measurements.$measure--small2;
                        }

                        @include include-media.media('>mobile') {
                            padding: measurements.$measure--medium1;
                        }
                    }

                    .promo-area__text {
                        p:first-of-type {
                            margin-top: 0;
                        }
                    }

                    .promo-area__image--mobile {
                        text-align: center;
                        display: inline;

                        img {
                            @include include-media.media('<tablet') {
                                width: 100%;
                            }
                        }
                    }
                }
            }

            .promo-area__image {
                @include include-media.media('<tablet') {
                    display: none;
                }

                figure,
                picture {
                    height: 100%;
                    margin: 0;
                }

                img {
                    height: auto;
                    width: 100%;
                    max-width: inherit;
                }
            }
        }

        /// general all layout styles
        .promo-area__content {
            padding: measurements.$measure--medium1;
            margin-top: measurements.$measure--medium8;
            z-index: functions.z-index('above');
            color: colors.$color-purewhite;
            margin-bottom: -(measurements.$measure--small4);

            p {
                @include typography.font-family('heading');
                @include typography.heading-font-features();
                @include typography.betatype();
            }

            @include include-media.media('<=tablet') {
                margin-top: measurements.$measure--small4;
                margin-bottom: measurements.$measure--small4;
            }

            .promo-area__heading {
                margin-top: 0;
                font-weight: variables.$font-weight-book;
                margin-bottom: measurements.$measure--basic;
            }

            .promo-area__text__details {
                margin-top: measurements.$measure--small3;

                p {
                    @include typography.font-family('default');
                    @include typography.body-font-features();
                    @include typography.alphatype();
                }

                span {
                    margin-right: measurements.$measure--half;
                }
            }

            .promo-area__cta {
                display: inline-block;
                margin-top: measurements.$measure--basic;

                @include include-media.media('<between') {
                    display: block;

                    ul {
                        max-width: inherit;
                    }
                    a {
                        display: block;
                    }
                }
            }

            &.background--pink90,
            &.background--red60,
            &.background--teal70 {
                .cta-block__cta a {
                    @include mixins-cta.cta-outlined-dark-bg();
                }
            }

            &.background--brown10 {
                color: colors.$color-gray10;

                .promo-area__text__details {
                    span {
                        color: colors.$color-red60;
                    }
                }

                .cta-block__cta a {
                    @include mixins-cta.cta-outlined-light-bg();
                }
            }
        }

        .promo-area__image--mobile {
            display: none;
        }

        .promo-area__image {
            height: 100%;
            overflow: hidden;
            position: absolute;
            width: 100%;
            z-index: functions.z-index('default');

            figure {
                margin-top: 0;
            }

            picture {
                display: block;
                height: 100%;
            }

            @include include-media.media('<=tablet') {
                figure {
                    height: 100%;
                }
            }
        }
    }
}
