@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/palette';
@use '../../abstracts/variables';
@use '../../anchors/discreet';
@use '../../anchors/outline';
@use '../../anchors/reset';
@use '../../base/typography';

/*
    19/9/2019
    General Usage:

     <h3>
        <a href="#" class="linked-heading">
            <span class="linked-heading__text">Linked heading</span>
            <span class="linked-heading__icons">
                <span class="fas fa-chevron-right"></span>
                <span class="fas fa-long-arrow-right"></span>
            </span>
        </a>
    </h3>
*/

.linked-heading {
    @include reset.anchor-reset();
    @include outline.anchor-default-outline(palette.$color-outline);
    position: relative;
    padding-right: measurements.$measure--medium1;
    display: inline-block;
    transition: none;
    background-image: none;
    background-size: 0;

    &:hover {
        transition: none;
        background-image: none;
        background-size: 0;

        .linked-heading__text {
            &:before {
                opacity: 1;
                width: 100%;
            }
        }

        .linked-heading__icons {
            span:nth-child(1) {
                display: none;
                visibility: hidden;
                opacity: 0;
                animation: slide-right-out 600ms;
            }

            span:nth-child(2) {
                display: inherit;
                visibility: visible;
                opacity: 1;
                animation: slide-left-in 600ms;
            }
        }
    }

    &:active {
        .linked-heading__text {
            &:before {
                opacity: 1;
                width: 100%;
            }
        }
    }

    &:focus,
    &:active {
        outline-color: colors.$color-gray11;
    }

    &:visited {
        color: colors.$color-gray11;
    }
}

.linked-heading__icons {
    background: colors.$color-red50;
    color: colors.$color-purewhite;
    position: absolute;
    right: 0;
    top: 0;
    background: colors.$color-red50;
    border-radius: 100%;
    display: flex;
    justify-content: center;
    align-items: center;

    span {
        position: absolute;
        font-weight: variables.$font-weight-normal;

        &:nth-child(1) {
            font-size: typography.$font-size--mobile;
        }

        &:nth-child(2) {
            font-size: typography.$font-size--1080p;
            font-weight: variables.$font-weight-light;
            display: none;
            opacity: 0;
            visibility: hidden;
            animation: slide-right-out 600ms;
        }
    }
}

h2 {
    .linked-heading__icons {
        height: measurements.$measure--small4;
        width: measurements.$measure--small4;
    }
}

h3 {
    .linked-heading__icons {
        height: 1.8rem;
        width: 1.8rem;
    }
}

.linked-heading__text {
    @include discreet.anchor-discreet-before(colors.$color-red50);

    border-bottom-color: palette.$color-text;
    border-bottom-style: variables.$border-style-solid;
    border-bottom-width: variables.$border-width-default;
    color: colors.$color-gray11;
    position: relative;
}
