@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../base/page';
@use '../../base/typography';
@use '../../layout/grid';

@mixin featured-profiles-block(
    $text-color,
    $link-color,
    $link-color-engaged,
    $profile-bg-color,
    $profile-bg-color-engaged,
    $profile-link-color-engaged,
    $outline-color: colors.$color-nearblack
) {
    color: colors.$color-gray4;

    a {
        color: $link-color;
        background-image: none;
        border-bottom: $link-color variables.$border-style-solid
            variables.$border-width-default;
    }

    .linked-heading {
        grid-column: 2 / -2;
        border-bottom: 0;

        &:focus {
            outline-color: $link-color-engaged;
            outline-offset: measurements.$measure--half;
        }
        .linked-heading__text {
            color: $text-color;
            border-bottom-color: $text-color;
        }
    }

    .wrapper--featured-profiles__heading-intro {
        color: $text-color;
    }

    .wrapper--featured-profiles__profile {
        a.featured-profiles__profile {
            background: $profile-bg-color;
            border-bottom: 0;

            &:hover {
                @include include-media.media('hover') {
                    background: $profile-bg-color-engaged;

                    .featured-profiles__profile__label {
                        h3 {
                            color: $profile-link-color-engaged;
                            border-bottom-color: $profile-link-color-engaged;
                        }

                        p {
                            color: $profile-link-color-engaged;
                        }

                        .fa-long-arrow-right {
                            visibility: visible;
                            color: colors.$color-red50;
                        }
                    }
                }
            }

            &:active,
            &:focus {
                outline-color: $outline-color;
            }

            .featured-profiles__profile__image {
                width: 35%;
            }

            .featured-profiles__profile__label {
                width: 100%;
                margin-left: measurements.$measure--basic;

                h3 {
                    display: inline;
                    color: $link-color;
                    border-bottom-color: $link-color;
                    background-image: none;
                    border-bottom: $link-color variables.$border-style-solid
                        variables.$border-width-default;
                }

                p {
                    color: $text-color;
                }

                .fa-long-arrow-right {
                    display: block;
                    visibility: hidden;
                    font-size: typography.$font-size--epsilon;
                    font-weight: variables.$font-weight-light;
                    margin-top: measurements.$measure--quarter;
                }
            }
        }

        .featured-profiles__profile__image
            + .featured-profiles__profile__label {
            flex-basis: calc(65% - #{measurements.$measure--basic});
        }
    }
}

.featured-profiles-block {
    @include grid.content-grid();
    grid-column: 1 / -1;
    padding: measurements.$measure--basic 0 measurements.$measure--small4;

    @include include-media.media('<between') {
        @include page.default-padding();
    }
}

.featured-profiles__profile {
    display: flex;
    padding: 0 measurements.$measure--basic measurements.$measure--basic 0;
    transition: variables.$transition-duration--long;

    @include include-media.media('<tablet') {
        margin-top: measurements.$measure--small1;

        &:first-child {
            margin-top: 0;
        }
    }
}

.wrapper--featured-profiles__profile {
    justify-content: flex-start;

    @include include-media.media('>=tablet') {
        grid-template-columns: repeat(3, 1fr);
        display: grid;
        grid-column-gap: measurements.$measure--basic;
        grid-row-gap: measurements.$measure--basic;
    }

    @include include-media.media('>between') {
        grid-column-gap: measurements.$measure--small2;
        grid-template-columns: repeat(2, 1fr);
    }

    @include include-media.media('>desktop') {
        grid-template-columns: repeat(3, 1fr);
    }
}

.featured-profiles__heading,
.wrapper--featured-profiles__heading-intro,
.wrapper--featured-profiles__profile {
    grid-column: 1 / -1;

    @include include-media.media('>between') {
        grid-column: 2 / 18;
    }

    @include include-media.media('>desktop') {
        grid-column: 2 / 18;
    }
}

.featured-profiles-block {
    &.background--purple80 {
        @include featured-profiles-block(
            colors.$color-purewhite,
            colors.$color-gray4,
            colors.$color-gray4,
            colors.$color-purple90,
            colors.$color-purewhite,
            colors.$color-gray10,
            colors.$color-purewhite
        );
    }
    &.background--gray9 {
        @include featured-profiles-block(
            colors.$color-purewhite,
            colors.$color-gray4,
            colors.$color-gray4,
            colors.$color-gray10,
            colors.$color-purewhite,
            colors.$color-gray10,
            colors.$color-purewhite
        );
    }
    &.background--gray2 {
        @include featured-profiles-block(
            colors.$color-nearblack,
            colors.$color-nearblack,
            colors.$color-nearblack,
            colors.$color-purewhite,
            colors.$color-pink90,
            colors.$color-purewhite
        );
    }
    &.background--gray1 {
        @include featured-profiles-block(
            colors.$color-nearblack,
            colors.$color-nearblack,
            colors.$color-nearblack,
            colors.$color-purewhite,
            colors.$color-pink90,
            colors.$color-purewhite
        );
    }
    &.background--purewhite {
        @include featured-profiles-block(
            colors.$color-gray10,
            colors.$color-gray10,
            colors.$color-purple90,
            colors.$color-gray2,
            colors.$color-pink90,
            colors.$color-purewhite
        );
    }
}
