@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../base/page';

.destination-leaver {
    grid-column: 1/-1;

    @include include-media.media('>tablet') {
        .destination-leaver-content {
            display: flex;
            flex-wrap: wrap;
        }
        .destination-leaver-content:not([data-length='1']) {
            div {
                width: 50%;
            }
        }
    }
}

.wrapper--destination-leavers-HE {
    margin-bottom: measurements.$measure--basic;

    @include include-media.media('>tablet') {
        .wrapper--finder__filters {
            .finder__filters {
                .finder__filter:not(.finder__tag) {
                    width: 100%;
                }
            }
        }

        .finder__query__submit {
            margin-left: initial;
        }
    }
    .wrapper--finder__filters {
        .finder__filters {
            label:not(.finder__filters__label--always) {
                border: initial;
                clip: initial;
                height: initial;
                overflow: initial;
                position: initial;
                width: initial;
                margin-bottom: measurements.$measure--half;
                color: colors.$color-nearblack;
            }

            .finder__filters__reset--desktop {
                margin-top: measurements.$measure--basic;
            }
        }
    }
    .wrapper--finder_filters--filters {
        display: block;
    }

    .wrapper--destination-leavers-HE__info-text {
        margin-left: measurements.$measure--small2;
        margin-right: measurements.$measure--small2;
    }
}

.destination {
    .destination-content {
        margin-left: measurements.$measure--small2;
        margin-right: measurements.$measure--small2;
    }
}

.wrapper--finder__filters[data-open='false'] {
    .wrapper--finder__filters--mobile__filters__content--text {
        display: none;
    }
}

.wrapper--finder__filters--mobile__filters__content--text {
    @include include-media.media('<small') {
        padding-left: measurements.$measure--small2;
        padding-right: measurements.$measure--small2;
    }
}

.destination-content {
    border-top: variables.$border-width-hairline solid colors.$color-gray4;
}

.destination-leaver {
    @include include-media.media('>=tablet') {
        @include page.default-margin();
    }

    .chart-row {
        margin-top: measurements.$measure--basic;
        padding-left: initial;
        padding-right: initial;
        margin-left: initial;
        margin-right: initial;

        // @include include-media.media('>=tablet', '<small') {
        //     display: block;
        //     .chart {
        //         width: 100%;
        //     }

        //     .chart__columns {
        //         display: flex;
        //     }
        // }

        .chart {
            @include include-media.media('>=small') {
                width: 50%;
            }

            path:nth-child(1) {
                stroke: colors.$color-pink30;
            }
            path:nth-child(2) {
                stroke: colors.$color-teal100;
            }
            path:nth-child(3) {
                stroke: colors.$color-blue60;
            }
            path:nth-child(4) {
                stroke: colors.$color-brown80;
            }
            path:nth-child(5) {
                stroke: colors.$color-red40;
            }
            path:nth-child(6) {
                stroke: colors.$color-blue80;
            }
            path:nth-child(7) {
                stroke: colors.$color-purple40;
            }

            .chart__legend__item:nth-child(1) {
                .fa.fa-circle {
                    color: colors.$color-pink30;
                }
            }
            .chart__legend__item:nth-child(2) {
                .fa.fa-circle {
                    color: colors.$color-teal100;
                }
            }
            .chart__legend__item:nth-child(3) {
                .fa.fa-circle {
                    color: colors.$color-blue60;
                }
            }
            .chart__legend__item:nth-child(4) {
                .fa.fa-circle {
                    color: colors.$color-brown80;
                }
            }
            .chart__legend__item:nth-child(5) {
                .fa.fa-circle {
                    color: colors.$color-red40;
                }
            }
            .chart__legend__item:nth-child(6) {
                .fa.fa-circle {
                    color: colors.$color-blue80;
                }
            }
            .chart__legend__item:nth-child(7) {
                .fa.fa-circle {
                    color: colors.$color-purple40;
                }
            }
        }
    }
}
