@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/measurements';
@use '../abstracts/mixins';
@use '../abstracts/variables';
@use '../anchors/img';
@use '../base/page';

// <Desktop-specific layout - secondary navigation never present
main {
    @include include-media.media('<=small') {
        > .login {
            @include page.default-margin();
        }
    }
}

main > .login {
    header {
        align-items: center;
        display: flex;
        flex-direction: column;
        flex-wrap: nowrap;
        justify-content: center;
        padding-top: measurements.$measure--small2;

        a {
            @include img.anchor-img();

            display: inline-block;
            width: 100%;

            @include include-media.media('<small') {
                height: measurements.$measure--medium7;
            }

            @include include-media.media('>=small') {
                max-width: measurements.$measure--huge5;
            }

            .logo {
                width: 100%;

                @include include-media.media('<small') {
                    height: 100%;
                }
            }
        }

        h1 {
            @include mixins.sr-only();

            margin-top: variables.$heading-margin;
        }
    }

    .login__message {
        max-width: unset;
        text-align: center;
    }

    form {
        @include page.default-padding();

        background-color: colors.$color-gray1;
        margin-top: measurements.$measure--basic;
        padding-bottom: measurements.$measure--small2;
        padding-top: measurements.$measure--basic;

        input[type='submit'] {
            display: block;
            margin-left: auto;
            margin-right: auto;
        }
    }

    footer {
        margin-top: measurements.$measure--small2;
        padding-bottom: measurements.$measure--small2;

        p {
            max-width: unset;
            text-align: center;
        }
    }
}
