@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../base/page';
@use '../../base/typography';

// <Desktop-specific layout - secondary navigation never present
main > .case-study {
    @include include-media.media('<small') {
        .banner-standfirst-label {
            .banner__image {
                grid-column: 1 / span 24;
            }
        }
    }
}

// Desktop-specific layout - for finder pages
main > .listing {
    @include include-media.media('>=small') {
        .banner-text {
            @include page.default-padding();
        }
    }
}

// Desktop-specific layout
main > article {
    @include include-media.media('>=small') {
        .banner-standfirst-label {
            display: grid;
            .banner__image {
                grid-column: 1 / span 24;
            }

            .banner__standfirst {
                grid-column: 3 / 23;
            }
        }
    }
}

// Desktop specific layout if secondary navigation is present
main {
    @include include-media.media('>=small') {
        .navigation--secondary {
            & + article {
                .banner-standfirst-label {
                    .banner__image {
                        grid-column: 1 / span 18;
                    }

                    .banner__standfirst {
                        grid-column: 3 / 17;
                    }
                }
            }
        }
    }
}

// Generic styles
.banner-standfirst-label {
    .banner__image {
        overflow: hidden;
        &:not(.banner__image--svg) {
            &:after {
                background-image: none;
            }
        }
    }

    .banner__block-color {
        background-color: colors.$color-brown30;
        grid-column: 1 / -1;
        height: measurements.$measure--huge1;

        @include include-media.media('<tablet') {
            height: measurements.$measure--large1;
        }
    }

    .banner__standfirst {
        background: colors.$color-purewhite;
        margin-top: 0;
        color: colors.$color-nearblack;
        grid-column: 1 / -1;
        opacity: 1;
        text-align: center;

        @include include-media.media('>=tablet') {
            margin-top: -(measurements.$measure--medium9);
            grid-column: 2 / 24;
        }

        @include include-media.media('>small') {
            grid-column: 2 / 18;
        }

        @include include-media.media('>desktop') {
            grid-column: 3 / 17;
        }

        .outline-cta--bright {
            margin-top: measurements.$measure--threequarters;
            @include typography.alphatype();
        }
    }

    .labels {
        @include typography.smalltype();

        color: colors.$color-gray7;
        font-weight: variables.$font-weight-bold;
        margin-bottom: measurements.$measure--half;
    }

    .standfirst {
        margin-left: auto;
        margin-right: auto;
        text-align: center;
    }
}
