@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/functions';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/variables';
@use '../../anchors/outline';
@use '../../base/content';
@use '../../base/page';
@use '../../base/typography';
@use '../../layout/grid';

// > Desktop
main .find-us {
    @include include-media.media('>=small') {
        @include grid.content-grid();
        .find-us__content {
            grid-column: 2/-2;
        }
    }
}

// < Desktop
main .find-us {
    @include include-media.media('<small') {
        .find-us__content {
            grid-column: 1/-1;
            @include page.default-margin();
        }
    }
}

// Generic
.find-us {
    padding-bottom: measurements.$measure--medium1;
}

.campus-map-v25 {
    //Clerkenwell campus
    &[data-campus='498711'] {
        .find-us__header {
            background: colors.$color-red50;
        }
    }
    // Moorgate campus
    &[data-campus='763053'] {
        .find-us__header {
            background: colors.$color-orange50;
        }
    }
    // Tooting campus
    &[data-campus='795583'] {
        .find-us__header {
            background: colors.$color-teal60;
        }
    }
}
.find-us__header,
.campus-map-v25__container,
.campus-map-v25__controls,
.find-us__content {
    grid-column: 1/-1;
}

.find-us .tabs__panel__content {
    margin: 0 auto;
    max-width: 55ch;
}

.find-us__header {
    background: colors.$color-pink80;
    text-align: center;
    color: colors.$color-purewhite;
    padding: measurements.$measure--small3;
}

.campus-map-v25__container {
    background: colors.$color-gray1;
    display: flex;
    flex-direction: column;
}

.campus-map-v25__controls {
    display: flex;
    flex-direction: column;
    margin: measurements.$measure--small2;
    position: relative;
}

#map-controls.campus-map-v25__controls {
    display: none;
}

.campus-map-v25__controls__container {
    display: flex;
    @include include-media.media('<mobile') {
        flex-direction: column;
    }
}

.campus-map-v25__controls__search__wrap {
    background: colors.$color-purewhite;
    flex: 2;
    margin-right: measurements.$measure--small4;
    position: relative;
    display: flex;
    border: variables.$border-width-hairline variables.$border-style-solid
        colors.$color-gray3;

    &:focus-within {
        outline: variables.$border-width-default variables.$border-style-dotted
            colors.$color-nearblack;
        outline-offset: variables.$border-width-default;
    }

    @include include-media.media('>=small') {
        margin-right: measurements.$measure--small4;
    }

    @include include-media.media('<small') {
        margin-right: measurements.$measure--basic;
    }

    @include include-media.media('<mobile') {
        flex: 1;
        margin-right: 0;
        margin-bottom: measurements.$measure--basic;
    }

    &:before {
        content: '\f002';
        font-family: 'Font Awesome 7 Pro';
        font-weight: variables.$font-weight-book;
        position: absolute;
        color: colors.$color-gray6;
        margin: measurements.$measure--basic;
    }

    .campus-map-v25__controls__search {
        border: none;
        padding: measurements.$measure--threequarters
            measurements.$measure--medium2;
        flex: 1;
        width: 100%;
        @include typography.smalltype();
        font-feature-settings: normal;

        &:focus,
        &:active {
            outline: none;
        }
    }

    .campus-map-v25__controls__search__clear {
        @include typography.epsilontype();
        align-items: center;
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        height: measurements.$measure--small5;
        justify-content: center;
        position: absolute;
        right: measurements.$measure--half;
        top: 0.35rem;
        width: measurements.$measure--small5;

        &:focus {
            @include outline.outline-properties();
        }

        .campus-map-v25__controls__search__clear__text {
            @include mixins.sr-only();
        }

        .icon {
            /*
            // temp overide with xmark-temp-styling below

            --fa-primary-color: #{colors.$color-gray7};
            --fa-primary-opacity: 1;
            --fa-secondary-color: #{colors.$color-gray1};
            --fa-secondary-opacity: 1;
            */
            @include content.xmark-temp-styling;

            letter-spacing: 0;
            line-height: 1;
        }

        &:focus,
        &:active {
            outline: variables.$border-width-default
                variables.$border-style-dotted colors.$color-nearblack;
            outline-offset: variables.$border-width-default;
        }
    }
}

.campus-map-v25__controls__locations__heading__wrap {
    flex: 1;
    position: relative;

    .campus-map-v25__controls__locations__heading {
        background: colors.$color-purewhite;
        border: variables.$border-width-hairline variables.$border-style-solid
            colors.$color-gray3;
        width: 100%;
        padding: measurements.$measure--threequarters;
        cursor: pointer;
        display: flex;
        @include typography.smalltype();

        &:focus,
        &:active {
            outline: variables.$border-width-default
                variables.$border-style-dotted colors.$color-nearblack;
            outline-offset: variables.$border-width-default;
        }

        &[data-show='false'] {
            span {
            }
            &:after {
                content: '\f0d7'; //f0d7 f0dd
            }
        }

        &[data-show='true'] {
            position: absolute;
            border-bottom: 0;
            z-index: functions.z-index('inpage');

            @include include-media.media('<mobile') {
                position: initial;
            }

            &:after {
                content: '\f00d'; //\f0de
            }
        }

        span {
            flex: 1;
            text-align: left;
            width: 100%;
            display: block;
        }

        &:after {
            font-family: 'Font Awesome 7 Pro';
            font-weight: variables.$font-weight-extrablack;
            right: 0;
            color: colors.$color-red60;
            text-align: right;
        }
    }
}

.campus-map-v25__controls__locations {
    background: colors.$color-purewhite;
    display: flex;
    flex-wrap: wrap;
    box-shadow: rgba(0, 0, 0, 0.25) 0 measurements.$measure--basic
        measurements.$measure--medium3 (-(measurements.$measure--threequarters));

    &:focus {
        outline: 0;
        border: 0;
    }

    .accordion {
        flex-basis: 50%;
        position: relative;

        button {
            border-top: solid variables.$border-width-default transparent;
        }

        @include include-media.media('<=tablet') {
            flex-basis: 100%;
        }

        .accordion__body {
            position: absolute;
            width: 100%;
            z-index: functions.z-index('above');
        }
    }

    .accordion.accordion--location {
        display: none;
    }

    &[data-show='true'] {
        position: absolute;
        width: 100%;
        top: 2.93rem;
        z-index: functions.z-index('above');
        border: variables.$border-width-hairline variables.$border-style-solid
            colors.$color-gray3;

        @include include-media.media('<mobile') {
            top: measurements.$measure--large4;
        }
    }

    &[data-show='false'] {
        display: none;
    }
}

.find-us__content {
    @include include-media.media('<small') {
        @include page.default-margin();
    }
}

.query__suggestions__wrapper {
    position: absolute;
    left: 0;
    width: 100%;

    #query__suggestions {
        position: absolute;
        background: colors.$color-purewhite;
        z-index: functions.z-index('inpage');
        margin: 0;
        padding: measurements.$measure--basic;
        width: 100%;
        max-width: 100%;
        top: measurements.$measure--medium3;
        box-shadow: rgba(0, 0, 0, 0.25) 0 measurements.$measure--basic
            measurements.$measure--medium3
            (-(measurements.$measure--threequarters));
        border-radius: 0 0 measurements.$measure--half
            measurements.$measure--half;
        list-style: none;

        &[data-show='false'] {
            display: none;
        }
    }
}

// Google map popup
@include include-media.media('<tablet') {
    .gm-style-iw.gm-style-iw-c {
        width: 25rem;
    }
}

#info-window h3 {
    margin-top: 0;
}
