@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../base/typography';

@mixin timetable($color: colors.$color-pink80) {
    padding-bottom: measurements.$measure--small2;
    margin-top: measurements.$measure--small2;

    .timetable-heading {
        color: colors.$color-nearblack;
        display: table;
        height: 100%;
        padding: measurements.$measure--small2 measurements.$measure--basic
            measurements.$measure--small2 measurements.$measure--basic;
        width: 100%;

        @include include-media.media('>tablet') {
            border-left: variables.$border-width-thick dotted $color;
            padding: 0;

            span {
                display: table-cell;
                text-align: center;
                vertical-align: middle;
            }
        }

        span {
            font-weight: variables.$font-weight-bold;
        }
    }

    .timetable-row {
        background-color: colors.$color-purewhite;
        margin-bottom: variables.$border-width-default;
        padding: measurements.$measure--quarter measurements.$measure--basic;

        &:last-child {
            margin-bottom: 0;
        }

        span {
            line-height: typography.$line-height-ratio--body;
            padding: measurements.$measure--quarter 0;

            @include include-media.media('>tablet') {
                padding: 0;
                display: inline-block;
            }

            &.separator {
                color: colors.$color-gray4;
                padding: 0;
            }
        }

        &:last-of-type {
            .icon {
                color: $color;
                margin-right: measurements.$measure--quarter;
            }
        }
    }
}

@mixin timetable-terms($color: colors.$color-pink80) {
    @include include-media.media('>tablet') {
        display: grid;
        grid-template-columns: measurements.$measure--huge1 auto;
    }

    .timetable-column:first-child {
        border-top: variables.$border-width-thick dotted $color;

        @include include-media.media('>tablet') {
            border: none;
        }
    }
}

.timetable {
    @include timetable();
}

.timetable-terms {
    @include timetable();
    @include timetable-terms();
}
