@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/functions';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/palette';
@use '../../abstracts/variables';
@use '../../anchors/cta--border';
@use '../../anchors/inline';
@use '../../anchors/outline';
@use '../../base/content';
@use '../../base/typography';

.no-js {
    .how-to-apply--pgt--no-js {
        display: block;
    }

    .tabs .how-to-apply--pgt--js {
        display: none;
    }
}

.js {
    .how-to-apply--pgt--no-js {
        display: none;
    }

    .tabs .how-to-apply--pgt--js {
        display: block;
    }

    .how-to-apply--pgt--js__modal {
        display: none;

        &[data-open='true'] {
            display: block;
        }
    }
}

.how-to-apply--pgt--js__modal {
    @include mixins.veil();

    bottom: 0;
    left: 0;
    position: fixed;
    right: 0;
    top: 0;
    z-index: functions.z-index('modal');

    .how-to-apply--pgt--js__modal__content {
        background-color: colors.$color-purewhite;
        box-shadow: 0 measurements.$measure--half measurements.$measure--small1
            0 rgba(0, 0, 0, 0.3);
        color: colors.$color-nearblack;
        display: block;
        margin-left: auto;
        margin-right: auto;
        margin-top: measurements.$measure--small2;
        max-height: calc(100% - #{2 * measurements.$measure--small1});
        overflow-y: scroll;
        padding-bottom: measurements.$measure--small3;
        padding-left: measurements.$measure--small2;
        padding-right: measurements.$measure--small2;
        padding-top: measurements.$measure--small3;
        position: relative;
        text-align: left;
        width: 90%;
        overflow: scroll;

        @include include-media.media('>=tablet') {
            margin-top: 15vh;
            max-height: calc(100% - 30vh);
        }

        @include include-media.media('>=small') {
            width: 70%;
        }

        @include include-media.media('>=desktop') {
            width: 60%;
        }

        .how-to-apply--pgt--js__modal__content-wrapper {
            margin-left: auto;
            margin-right: auto;
            max-width: typography.$max-line-length;
        }

        p {
            @include content.content-style();

            text-align: left;
        }

        .how-to-apply--pgt--js__options {
            display: flex;
            flex-direction: row;
            flex-wrap: wrap;
            justify-content: center;
            list-style: none;
            margin-left: 0;
            max-width: unset;

            // Remove button/link top margin when multiple locations exist. Ensures these selections stay
            // close to relevant heading, helping user identify grouped content.
            &.how-to-apply--pgt--js__options--multiple-locations {
                margin-top: 0;
            }

            li {
                margin-bottom: measurements.$measure--half;
                margin-right: measurements.$measure--half;
            }

            button,
            a {
                @include cta--border.cta--border(
                    $background: colors.$color-purewhite,
                    $color: colors.$color-nearblack,
                    $border: colors.$color-gray4,
                    $hover-color: colors.$color-nearblack,
                    $hover-border: colors.$color-gray4,
                    $outline: colors.$color-nearblack,
                    $corners: square
                );
            }

            button {
                padding: 0;
                span {
                    display: inline-block;
                    padding: measurements.$measure--half
                        measurements.$measure--small2;
                }
            }
        }

        .how-to-apply--pgt--js__modal__alternative {
            a {
                @include inline.anchor-inline(
                    $color: palette.$color-inline-link,
                    $visited: palette.$color-inline-link--visited,
                    $hover: palette.$color-text--dark,
                    $outline: palette.$color-outline
                );
            }
        }

        .how-to-apply--pgt--js__close {
            color: colors.$color-gray7;
            padding: measurements.$measure--threequarters;
            position: absolute;
            right: 0;
            top: 0;

            @include outline.anchor-default-outline(colors.$color-nearblack);

            &:hover {
                @include include-media.media('hover') {
                    background-image: none;
                    border: none;
                    background-color: colors.$color-gray1;
                    color: colors.$color-gray10;
                }
            }

            &:active {
                background-color: colors.$color-gray1;
                color: colors.$color-gray10;
            }

            &:focus {
                color: colors.$color-gray10;
            }

            &:active,
            &:focus {
                outline-offset: 0;
            }
        }

        .how-to-apply--pgt--js__modal__reset {
            display: block;
            position: absolute;
            left: 0;
            top: 0;

            button {
                color: colors.$color-red50;
                padding: measurements.$measure--threequarters;
                text-align: center;

                @include outline.anchor-default-outline(
                    colors.$color-nearblack
                );

                &:hover {
                    @include include-media.media('hover') {
                        background-image: none;
                        border: none;
                        background-color: colors.$color-gray1;
                        color: colors.$color-gray10;
                    }
                }

                &:active {
                    background-color: colors.$color-gray1;
                    color: colors.$color-gray10;
                }

                &:focus {
                    color: colors.$color-gray10;
                }

                &:active,
                &:focus {
                    outline-offset: 0;
                }
            }
        }

        .how-to-apply--pgt--js__modal__progress {
            display: flex;
            flex-direction: row;
            flex-wrap: nowrap;
            justify-content: center;
            list-style: none;
            margin-left: 0;
            margin-top: 1.5rem;
            max-width: unset;
            text-align: left;

            // Bespoke positioning required when two modal steps present and user at final step
            &[data-further-steps-pending='false'] {
                &[data-total-steps='2'] {
                    .how-to-apply--pgt--js__modal__progress__previous {
                        &:after {
                            @media (max-width: 580px) {
                                left: 60%;
                            }
                            @media (max-width: 400px) {
                                left: 62%;
                            }
                            @media (max-width: 350px) {
                                left: 64%;
                            }
                            @media (max-width: 310px) {
                                left: 66%;
                            }
                        }
                    }
                }
            }

            li {
                position: relative;
                text-align: center;
                width: 11rem;
                margin-left: 0;
                margin-right: 0;

                .how-to-apply--pgt--js__modal__progress__wrapper {
                    margin: auto;
                }

                .how-to-apply--pgt--js__modal__progress__circle {
                    align-items: center;
                    border-radius: 100%;
                    border-width: variables.$border-width-thicker;
                    display: flex;
                    height: measurements.$measure--medium1;
                    justify-content: center;
                    margin: 0 auto;
                    width: measurements.$measure--medium1;
                }

                .how-to-apply--pgt--js__modal__progress__text {
                    @include content.content-style();
                    @include typography.smalltype();

                    color: colors.$color-gray7;
                    display: block;
                    font-weight: variables.$font-weight-text;
                    line-height: measurements.$measure--small1;
                    margin-top: measurements.$measure--half;
                    text-align: center;
                }

                &.how-to-apply--pgt--js__modal__progress__current {
                    z-index: functions.z-index('above');
                    .how-to-apply--pgt--js__modal__progress__circle {
                        background-color: colors.$color-red50;
                        border-color: colors.$color-red50;
                        border-style: variables.$border-style-solid;
                        color: colors.$color-red50;
                    }
                    @include include-media.media('<tablet') {
                        .how-to-apply--pgt--js__modal__progress__text {
                            display: none;
                        }
                    }
                }

                &.how-to-apply--pgt--js__modal__progress__previous {
                    &:after {
                        background-color: colors.$color-red50;
                        content: ' ';
                        display: block;
                        height: measurements.$measure--quarter;
                        position: absolute;
                        top: measurements.$measure--small1;
                        left: 60%;
                        width: 100%;
                        @media (max-width: 580px) {
                            left: 62%;
                            width: 97%;
                        }
                        @media (max-width: 520px) {
                            left: 64%;
                            width: 98%;
                        }
                        @include include-media.media('<mobile') {
                            left: 67%;
                        }
                        @include include-media.media('<tiny') {
                            left: 72%;
                            width: 92%;
                        }
                    }

                    button {
                        align-items: center;
                        display: flex;
                        flex-direction: column;
                        justify-content: center;

                        &:hover {
                            .how-to-apply--pgt--js__modal__progress__circle {
                                background-color: colors.$color-red50;
                                color: colors.$color-purewhite;
                            }

                            .how-to-apply--pgt--js__modal__progress__text {
                                color: colors.$color-nearblack;
                            }

                            .icon {
                                &:before {
                                    content: '\f00d';
                                }
                            }
                        }

                        &:active,
                        &:focus {
                            @include outline.outline-properties(
                                colors.$color-nearblack
                            );
                        }
                    }

                    .how-to-apply--pgt--js__modal__progress__circle {
                        background-color: colors.$color-purewhite;
                        border-color: colors.$color-red50;
                        border-style: variables.$border-style-solid;
                        color: colors.$color-red50;
                    }
                }

                &.how-to-apply--pgt--js__modal__progress__next {
                    &:before {
                        background-color: colors.$color-gray3;
                    }
                }

                &:nth-of-type(2) {
                    // 'Next' progress indicator, when two bubbles present
                    &.how-to-apply--pgt--js__modal__progress__next {
                        &:not(.how-to-apply--pgt--js__modal__progress__last) {
                            &:before {
                                content: ' ';
                                display: block;
                                height: measurements.$measure--quarter;
                                right: 60%;
                                position: absolute;
                                top: measurements.$measure--small1;
                                width: 80%;
                                @include include-media.media('<small') {
                                    right: 61%;
                                }
                                @media (max-width: 400px) {
                                    right: 62%;
                                }
                                @include include-media.media('<tiny') {
                                    right: 63%;
                                }
                                @media (max-width: 360px) {
                                    right: 64%;
                                }
                                @media (max-width: 335px) {
                                    right: 65%;
                                }
                                @media (max-width: 315px) {
                                    right: 66%;
                                }
                            }
                        }
                    }
                }
                &:nth-of-type(3) {
                    // 'Next' progress indicator, when three bubbles present
                    &.how-to-apply--pgt--js__modal__progress__next {
                        &:not(.how-to-apply--pgt--js__modal__progress__last) {
                            &:before {
                                content: ' ';
                                display: block;
                                height: measurements.$measure--quarter;
                                right: 6.5rem;
                                position: absolute;
                                top: measurements.$measure--small1;
                                width: 82%;
                                @include include-media.media('<tablet') {
                                    right: 61%;
                                }
                                @media (max-width: 550px) {
                                    right: 63%;
                                }
                                @media (max-width: 500px) {
                                    right: 65%;
                                }
                                @include include-media.media('<mobile') {
                                    right: 67%;
                                }
                                @include include-media.media('<tiny') {
                                    right: 69%;
                                }
                                @media (max-width: 350px) {
                                    right: 71%;
                                }
                                @media (max-width: 325px) {
                                    right: 73%;
                                }
                                @media (max-width: 310px) {
                                    right: 74%;
                                }
                            }
                        }
                    }
                }

                &.how-to-apply--pgt--js__modal__progress__next {
                    .how-to-apply--pgt--js__modal__progress__circle {
                        border-color: colors.$color-gray3;
                        border-style: variables.$border-style-dashed;

                        .icon {
                            color: colors.$color-purewhite;
                        }
                    }
                }
            }
        }
    }
}
