@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../base/content';
@use '../../base/page';
@use '../../base/typography';

.module-selector-wrapper {
    margin-top: measurements.$measure--small4;
}

.module-selector {
    @include page.standard-box();
    @include mixins.gradient-border(colors.$color-red50, colors.$color-pink60);
    position: relative;
    padding: measurements.$measure--basic;
    background-color: colors.$color-red5;
    overflow: hidden;
    text-align: center;

    @include include-media.media('<tablet') {
        margin: 0;
    }
    @include include-media.media('>=tablet', '<small') {
        margin: 0 measurements.$measure--basic;
    }
    @include include-media.media('>=small', '<large') {
        margin: 0;
    }

    @include include-media.media('>=between') {
        display: flex;
        flex-direction: row;
        padding: measurements.$measure--small4;
        text-align: left;
    }
}

.module-selector__heading {
    @include content.h3style();
}

.module-selector__content {
    .module-selector__content__text {
        max-width: 100%;
    }
}

.module-selector__heading,
.module-selector__content,
.module-selector__button {
    @include include-media.media('>=between') {
        width: calc(33% - #{measurements.$measure--small2});
        margin-right: measurements.$measure--small2;
    }
}

.module-selector__button {
    margin: measurements.$measure--small4 0 0 0;

    @include include-media.media('>=between') {
        margin: 0;
    }

    @include include-media.media('<tablet') {
        display: flex;
        flex-direction: column;

        a {
            display: block;
        }
    }

    a {
        @include typography.alphatype();
    }
}

.module-selector__content,
.module-selector__heading {
    margin-bottom: measurements.$measure--basic;

    @include include-media.media('>between') {
        margin-bottom: 0;
    }
}

.module-selector__content,
.module-selector__heading,
.module-selector__button {
    align-self: center;
    position: relative;
}

.module-selector__content,
.module-selector__button {
    text-align: center;
}

.module-selector__heading-text {
    color: colors.$color-gray7;
}

.module-selector__background {
    display: block;
    right: 0;
    position: absolute;
    right: -#{measurements.$measure--large2};
    height: 100%;
    top: 0;

    @include include-media.media('>=tablet') {
        right: 0;
    }
}

.no-js {
    .module-selector__button {
        margin: measurements.$measure--basic 0 0 0;
    }

    .module-selector {
        @include include-media.media('>=tablet') {
            display: block;
        }

        .modal__content {
            background: transparent;
        }
    }

    .module-selector__button {
        text-align: left;
    }
}
