@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';

@mixin dropdown-red-bg() {
    background-color: colors.$color-red60;
    color: colors.$color-purewhite;
    padding: measurements.$measure--basic measurements.$measure--basic 0;
    &:after {
        content: '';
        width: 0;
        border-left: measurements.$measure--basic variables.$border-style-solid
            transparent;
        border-right: measurements.$measure--basic variables.$border-style-solid
            transparent;
        border-top: measurements.$measure--basic variables.$border-style-solid
            colors.$color-red60;
        margin: auto;
        display: block;
        top: measurements.$measure--basic;
        position: relative;
    }
    select {
        &:focus {
            outline-color: colors.$color-purewhite;
        }
    }
}
