@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../base/typography';

.card--findus {
    .card__details {
        border-color: colors.$color-gray1;
        border-style: variables.$border-style-solid;
        border-width: variables.$border-width-hairline;
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        @include include-media.media('<mobile') {
            display: block;
            .card__thumbnail {
                img {
                    width: 100%;
                }
            }
        }

        .wrapper--card__thumbnail {
            flex: 1;
        }

        .card__details__text {
            padding-bottom: measurements.$measure--basic;
            flex: 1;
        }

        .card--findus__label--findus {
            @include typography.smalltype();

            color: colors.$color-gray7;
            font-style: italic;
            margin-top: 0;
        }

        .card--findus__details__address {
            display: flex;
            flex-direction: row;
            flex-wrap: nowrap;

            .icon {
                color: colors.$color-red50;
                padding-right: measurements.$measure--small2;
            }
        }
    }
}
