@use '../abstracts/media' as include-media;
@use '../abstracts/measurements';
@use '../abstracts/variables';
@use '../base/content';
@use '../base/page';
@use '../base/typography';
@use '../fontawesome-6/fa-extra';
@use '../layout/grid';

.user-journey {
    .content-wrapper {
        @include grid.standard-grid();
        grid-template-rows: auto;

        @include include-media.media('<=mobile') {
            grid-template-areas: 'main main main main main main';
        }

        @include include-media.media('>mobile') {
            grid-template-areas: '. . main main main main main main main main . .';
        }

        @include include-media.media('>between') {
            grid-template-areas: '. . . . . main main main main main main main main . . . . .';
        }

        > .content {
            @include page.standard-box();
            grid-area: main;
        }
    }
}

.user-journey__steps {
    li:not(:last-of-type) {
        &:after {
            @include typography.font-family('sharp');
            @include fa-extra.fa-icon-rotate(90deg, 1);
            content: '\f54b';
            display: block;
            font-size: typography.$font-size--icon;
            font-weight: variables.$font-weight-light;
            margin-top: measurements.$measure--basic;
            text-align: center;
        }
    }

    li:last-of-type {
        &:after {
            @include typography.font-family('sharp');
            font-size: typography.$font-size--icon;
            content: '\f11e';
            display: block;
            font-weight: variables.$font-weight-light;
            margin-top: measurements.$measure--basic;
            text-align: center;
        }
    }

    h3 {
        @include content.body-baseline();
        @include typography.body-font-features();
        font-weight: variables.$font-weight-medium;
    }
}
