@use '../../abstracts/media' as include-media;
@use '../../abstracts/measurements';
@use '../../abstracts/palette';
@use '../../abstracts/variables';
@use '../../anchors/discreet';
@use '../../anchors/img';
@use '../../base/typography';

////
/// Figure
/// @group patterns
////

figure a {
    @include img.anchor-img();
}

figure figcaption,
.figcaption-like {
    @include typography.smalltype();
    color: palette.$color-text--caption;
    font-weight: variables.$font-weight-book;
    line-height: measurements.$measure--small1;
    margin-top: measurements.$measure--quarter;

    a {
        @include discreet.anchor-discreet();
    }
}

.figcaption__credit {
    display: block;
}

figure.figure--svg img {
    @include include-media.media('<=mobile') {
        padding-bottom: 100vw;
    }
}
