@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/palette';
@use '../../abstracts/variables';
@use '../../base/typography';

.card--course {
    .wrapper--card__label__details {
        float: right; // Makes styles more manageable; avoids text overlap on card heading

        @include include-media.media('<tablet') {
            display: flex;
            flex-direction: row;
        }
        .card--course__label--clearing {
            float: right;

            p {
                @include typography.smalltype();

                background-color: colors.$color-yellow40;
                font-weight: variables.$font-weight-bold;
                padding: measurements.$measure--threequarters;
                margin: measurements.$measure--basic;

                @include include-media.media('<tablet') {
                    margin: measurements.$measure--basic 0
                        measurements.$measure--basic
                        measurements.$measure--basic;
                }

                @include include-media.media('<mobile') {
                    margin: 0;
                }

                @include include-media.media('<mobile') {
                    position: absolute;
                }
            }
        }

        .card--course__label--stgeorges {
            margin-top: measurements.$measure--threequarters;
            p {
                @include typography.smalltype();
                background-color: palette.$color-stgeorges;
                color: colors.$color-purewhite;
                font-weight: variables.$font-weight-bold;
                margin-top: 0;
                padding: measurements.$measure--threequarters;
                display: inline-block;
            }
        }
    }

    // Add a margin to allow for spacing between clearing label and card text that follows
    .card--course__label--clearing + .card__details__text {
        @include include-media.media('<mobile') {
            margin-top: measurements.$measure--medium3;
        }
    }
}
