@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../anchors/anchors';
@use '../../anchors/ghost-animation';
@use '../../anchors/outline';
@use '../../anchors/reset';
@use '../../base/content';
@use '../../base/typography';

@mixin tabs-links-style() {
    .tabs__links {
        align-items: stretch;
        bottom: -0.4rem;
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        justify-content: center;
        list-style-type: none;
        margin-bottom: 0;
        margin-left: 0;
        margin-top: measurements.$measure--basic;
        max-width: unset;
        overflow-x: hidden;
        position: relative;
    }

    .tabs__links li {
        margin-bottom: 0;
        margin-top: 0;
        max-width: unset;
        text-align: center;
        margin-right: measurements.$measure--threequarters;
        display: flex;
        align-items: flex-end;
    }

    .tabs__links li:last-of-type {
        margin-right: 0;
    }

    .tabs__links li button {
        @include anchors.anchor-span();
        @include reset.anchor-reset();
        background-image: none;
        border-bottom-color: transparent;
        border-bottom-style: variables.$border-style-dotted;
        border-bottom-width: variables.$border-width-default;
        border-color: transparent;
        border-style: variables.$border-style-dotted;
        border-width: variables.$border-width-default;
        color: colors.$color-gray7;
        display: block;
        overflow: hidden;
        padding: 0;
        position: relative;
        transition: none;
        width: 100%;

        > span {
            @include content.h6style();
            align-items: flex-end;
            border-bottom-color: transparent;
            border-bottom-style: variables.$border-style-solid;
            border-bottom-width: measurements.$measure--half;
            display: flex;
            height: 100%;
            line-height: typography.$line-height-ratio--body;
            margin-top: 0;
            padding-bottom: measurements.$measure--half;
            padding-left: measurements.$measure--half;
            padding-right: measurements.$measure--half;
            padding-top: measurements.$measure--half;

            @include include-media.media('>between') {
                padding-left: measurements.$measure--threequarters;
                padding-right: measurements.$measure--threequarters;
            }
        }

        > span::before {
            @include ghost-animation.ghost-out();
        }

        &[aria-selected='false'] {
            &:hover > span::before {
                @include include-media.media('hover') {
                    @include ghost-animation.ghost-in();
                }
            }
        }

        &[aria-selected='true'] {
            font-weight: variables.$font-weight-bold;

            > span {
                border-bottom-color: colors.$color-red50;
                color: colors.$color-gray11;
            }
        }

        &:hover {
            @include include-media.media('hover') {
                background: none;
                border-bottom-color: transparent;
                border-bottom-style: variables.$border-style-dotted;
                border-bottom-width: variables.$border-width-default;
                border-color: transparent;
                border-style: variables.$border-style-dotted;
                border-width: variables.$border-width-default;
            }
        }

        &:focus {
            background: colors.$color-gray1;
            border-color: colors.$color-gray11;
            border-style: variables.$border-style-dotted;
            border-width: variables.$border-width-default;
            color: colors.$color-gray7;
            padding: 0;

            span {
                outline: none;
            }
        }

        &:active {
            background: colors.$color-gray1;
            border-color: colors.$color-gray11;
            border-style: variables.$border-style-dotted;
            border-width: variables.$border-width-default;
            color: colors.$color-gray11;

            span {
                outline-width: 0;
            }
        }
    }
}

.tabs {
    .tabs__links li {
        &:only-child {
            display: none;
        }
    }
}

@include include-media.media('print') {
    .js .tabs > .tabs__links,
    .js .tabs--accordion > .accordion {
        display: none;
    }

    .js .tabs .tabs__panel[hidden] {
        display: block;
    }
}

@include include-media.media('screen') {
    .js .tabs {
        @include tabs-links-style();
    }

    .js .tabs .tabs__panel {
        padding: measurements.$measure--threequarters
            measurements.$measure--half measurements.$measure--half
            measurements.$measure--half;
        background: colors.$color-gray1;
        border-top: variables.$border-width-default
            variables.$border-style-solid colors.$color-gray3;

        @include include-media.media('>=tablet') {
            border: variables.$border-width-default
                variables.$border-style-solid colors.$color-gray3;
        }

        &:focus {
            @include outline.outline-properties(colors.$color-nearblack);

            outline-offset: 0;
        }
    }

    .js .tabs .tabs__panel__content {
        padding: measurements.$measure--small4 0;
        @include include-media.media('<tablet') {
            padding-bottom: measurements.$measure--basic;
        }
    }

    .js .tabs .tabs__panel__heading {
        margin-top: 0;
    }
}

@include include-media.media('screen', '<=tablet') {
    .js .tabs--accordion > .accordion {
        display: block;
    }

    .js .tabs--accordion > .accordion .accordion__heading {
        border-bottom-color: colors.$color-gray1;
        border-bottom-style: variables.$border-style-solid;
        border-bottom-width: variables.$border-width-default;
        outline-color: transparent;
        outline-style: variables.$border-style-dotted;
        outline-width: variables.$border-width-default;

        &:active {
            border-bottom-color: colors.$color-gray1;
            text-decoration: underline;
        }

        &[data-open='true'] button {
            .accordion__heading__text {
                background: colors.$color-red50;
                color: colors.$color-purewhite;
                text-decoration: underline;
            }
            .accordion__heading__indicator {
                padding: measurements.$measure--basic 0.89rem;
            }
        }

        &[data-open='false'] {
            &:focus button {
                outline-color: colors.$color-gray11;
            }
            button {
                .accordion__heading__text {
                    background: transparent;
                    color: colors.$color-gray10;
                }
                .accordion__heading__indicator {
                    background: colors.$color-red50;
                    color: colors.$color-purewhite;
                }
            }
        }
    }

    .js .tabs--accordion > .accordion .accordion__heading button {
        padding: 0;
        display: block;

        &:hover {
            @include include-media.media('hover') {
                background: colors.$color-purewhite;
                color: colors.$color-gray10;
            }
        }
    }

    .js
        .tabs--accordion
        > .accordion
        .accordion__heading
        button
        .accordion__heading__text {
        padding: measurements.$measure--basic;
    }

    .js
        .tabs--accordion
        > .accordion
        .accordion__heading
        button
        .accordion__heading__indicator {
        align-self: normal;
        padding: measurements.$measure--basic;
        text-align: center;
        text-decoration: underline;
        background: colors.$color-red50;
        color: colors.$color-purewhite;
        &:before {
            vertical-align: sub;
        }
    }

    .js .tabs--accordion > .accordion .accordion {
        .accordion__heading {
            button {
                .accordion__heading__text,
                .accordion__heading__indicator {
                    background: transparent;
                    color: colors.$color-linkblue;
                }
            }
            &[data-open='false'] {
                border-bottom-color: colors.$color-gray2;
                border-bottom-style: variables.$border-style-solid;
                border-bottom-width: variables.$border-width-hairline;
            }
        }
    }

    // Nested tab inside tab that switches to accordion
    .js .tabs--accordion .tabs--accordion > .accordion .accordion__heading {
        &[data-open='true'] {
            button {
                .accordion__heading__indicator,
                .accordion__heading__text {
                    background: colors.$color-red50;
                    color: colors.$color-purewhite;
                }
            }
        }
        &[data-open='false'] {
            button {
                .accordion__heading__indicator {
                    background: colors.$color-red50;
                    color: colors.$color-purewhite;
                }
                .accordion__heading__text {
                    color: colors.$color-gray10;
                }
            }
        }
    }

    .js .tabs--accordion > .tabs {
        display: none;
    }
}

@include include-media.media('screen', '>tablet') {
    .js .tabs--accordion > .accordion {
        display: none;
    }

    .js .tabs--accordion > .tabs {
        display: block;
    }

    .js .tabs--accordion > .tabs .accordion--nested {
        @include include-media.media('>tablet') {
            display: block;
        }
    }
}

// tabs variation with grey underline
.js .tabs--grey-underline {
    .tabs__links li button > span {
        border-bottom-color: colors.$color-gray1;
    }
    .tabs__links li button[aria-selected='true'] > span {
        border-bottom-color: colors.$color-pink80;
    }

    .tabs__panel__body .tabs {
        // nested tabs
        .tabs__links {
            justify-content: left;

            li button > span {
                border-bottom-color: colors.$color-gray3;
                &:before {
                    background-color: colors.$color-gray5;
                }
            }

            li button[aria-selected='true'] > span {
                border-bottom-color: colors.$color-red50;
            }
        }

        .tabs__panel {
            background: colors.$color-gray1;
        }
    }
}

// Desktop specific layout if secondary navigation is present for standard pages
main {
    @include include-media.media('>=small') {
        .navigation--secondary {
            & + .standard-content {
                @include include-media.media('>=small', '<desktop') {
                    .tabs .tabs__links li {
                        margin-right: measurements.$measure--half;
                        button > span {
                            @include typography.extrasmalltype();
                            padding-left: measurements.$measure--half;
                            padding-right: measurements.$measure--half;
                        }
                    }
                }

                @include include-media.media('>=desktop', '<large') {
                    .tabs .tabs__links li button > span {
                        @include typography.smalltype();
                    }
                }
            }
        }
    }
}
