@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/functions';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/palette';
@use '../../abstracts/variables';
@use '../../anchors/img';
@use '../../anchors/outline';
@use '../../anchors/underline-basic';
@use '../../anchors/underline-transition';
@use '../../base/content';
@use '../../base/page';
@use '../../base/typography';
@use '../../layout/grid';

////
/// Global Header
/// @group patterns
////
.global-header {
    &:not(.global-header--withpromo) {
        @include mixins.box-shadow();
    }

    background-color: colors.$color-purewhite;
    position: relative;
    z-index: functions.z-index('unveiled');

    @include include-media.media('print') {
        display: none;
    }

    .global-header__content {
        position: relative;

        @include include-media.media('<small') {
            align-items: flex-start;
            display: flex;
            flex-direction: row;
            flex-wrap: nowrap;
            justify-content: space-between;
        }

        @include include-media.media('>=small') {
            @include page.standard-box();
            @include grid.standard-grid();

            grid-template-rows: repeat(3, auto);
        }

        @include include-media.media('>=desktop') {
            grid-row-gap: measurements.$measure--basic;
            grid-template-rows: repeat(2, auto);
        }
    }
}

.header-logo {
    @include include-media.media('<small') {
        align-self: center;
        justify-content: flex-start;
        padding-bottom: measurements.$measure--half;
        padding-left: measurements.$measure--half;
        padding-right: measurements.$measure--half;
        padding-top: measurements.$measure--half;
        width: measurements.$measure--huge5;
    }

    @include include-media.media('>=small') {
        grid-column-end: span 3;
        grid-column-start: 1;
        grid-row-end: span 2;
        grid-row-start: 1;
    }

    a {
        @include img.anchor-img();

        display: inline-block;
        width: 100%;

        @include include-media.media('<small') {
            height: measurements.$measure--medium7;
        }

        @include include-media.media('>=small') {
            margin-bottom: measurements.$measure--basic;
            margin-top: measurements.$measure--small2;
        }

        .logo {
            width: 100%;

            @include include-media.media('<small') {
                height: 100%;
            }
        }
    }
}

.global-header__utility {
    display: none;
    .global-header__utility__sub-menu {
        border: 1px solid colors.$color-gray5;
        padding: 8px 12px;
        border-left: 5px solid palette.$color-brand-primary;
    }
    .dd-menu--open {
        .global-header__utility__link-btn {
            border-color: colors.$color-gray5;
            border-left-color: palette.$color-brand-primary;
        }
    }

    .global-header__utility__link-btn {
        border: 1px solid transparent;
        border-left-width: 5px;
        padding: 10px;
        border-bottom: 0;
        z-index: 2;
        position: relative;
        background: white;

        &:focus {
            @include outline.anchor-default-outline(palette.$color-outline);
        }
        &::after {
            //Needed to hide part of the border
            content: '';
            background: white;
            height: 2px;
            display: block;
            position: absolute;
            width: 100%;
            left: 0;
            bottom: -1px;
        }
    }

    .global-header__utility__text {
        color: colors.$color-gray7;
        margin: 0 5px;
    }
    @include include-media.media('>=small') {
        display: block;
        grid-column-end: 24;
        grid-column-start: 4;
        grid-row-end: 1;
        grid-row-start: 1;
        margin-top: measurements.$measure--small2;
    }

    & > ul {
        align-items: center;
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        height: 100%;
        justify-content: flex-end;

        margin-left: 0;
        margin-top: 0;
        max-width: unset;

        & > li {
            a {
                display: inline-block;
                padding: 10px;
            }
            &:not(:last-of-type) {
                margin-right: measurements.$measure--threequarters;
            }
        }
    }

    ul {
        list-style: none;

        li {
            @include typography.smalltype();

            a {
                @include underline-transition.underline-transition--subelement(
                    colors.$color-gray7,
                    colors.$color-gray10,
                    variables.$border-width-thick,
                    colors.$color-nearblack,
                    'global-header__utility__text'
                );

                height: 100%;

                .global-header__utility__icon {
                    color: colors.$color-gray333;
                    margin-left: measurements.$measure--quarter;
                    top: -#{variables.$border-width-default};
                }

                &:hover .global-header__utility__icon {
                    @include include-media.media('hover') {
                        color: colors.$color-gray10;
                    }
                }
            }
        }
    }
}
.global-header__utility__sub-menu {
    background-color: colors.$color-purewhite;
    z-index: functions.z-index('above');
    width: 150%;
    box-shadow: 0 measurements.$measure--half measurements.$measure--small1 0
        rgba(0, 0, 0, 0.3);
    li {
        border-top: 1px solid colors.$color-gray5;
        &:first-child {
            border-top: none;
            a {
                padding-bottom: 8px;
                padding-top: 5px;
            }
        }
        a {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 8px 0 5px 0;
        }
    }
}
.global-header__controls {
    @include include-media.media('<small') {
        align-items: center;
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        justify-content: flex-end;
        width: 50%;
    }

    @include include-media.media('>=small') {
        align-self: stretch;
        display: flex;
        grid-column-end: span 1;
        grid-column-start: 24;
        grid-row-end: 1;
        grid-row-start: 1;
        margin-top: measurements.$measure--small2;
    }
}

.navigation--primary {
    display: none;

    @include include-media.media('>=small') {
        display: block;
        grid-column-end: span 24;
        grid-column-start: 1;
        grid-row-end: 3;
        grid-row-start: 3;
        padding-bottom: measurements.$measure--small2;
    }

    @include include-media.media('>=desktop') {
        grid-column-end: span 21;
        grid-column-start: 4;
        grid-row-end: 2;
        grid-row-start: 2;
    }

    > ul {
        align-items: flex-end;
        height: 100%;
    }
}

.announcement {
    background-color: colors.$color-gray10;
    color: colors.$color-purewhite;
    padding-bottom: measurements.$measure--basic;
    padding-top: measurements.$measure--basic;
    position: relative;
    z-index: functions.z-index('inpage');
    width: 100%;

    .announcement__content {
        @include content.h6style();
        @include page.standard-box();

        font-weight: variables.$font-weight-normal;
        margin-top: 0;
        text-align: center;

        sup,
        sub {
            font-size: typography.$font-size--super;
            line-height: typography.$font-size--super;
        }

        a {
            @include underline-basic.underline-basic(
                $inactive-color: colors.$color-purewhite,
                $hover-color: colors.$color-purewhite,
                $underline-width: variables.$border-width-default,
                $outline: colors.$color-purewhite
            );
        }
    }
}
