@use './variables' as variables;
@use 'sass:map';
@use 'sass:string';
@use 'sass:meta';

// ------------------------------------------------------------
// Breakpoints (your existing system)
// ------------------------------------------------------------

$breakpoints: variables.$breakpoints;

// ------------------------------------------------------------
// Media expressions (hover, print, etc.)
// ------------------------------------------------------------

$media-expressions: (
    hover: '(hover: hover)',
    nohover: '(hover: none)',
    print: 'print',
    reducemotion: '(prefers-reduced-motion: reduce)',
    screen: 'screen',
) !default;

// ------------------------------------------------------------
// Helpers
// ------------------------------------------------------------

@function bp($name) {
    $key: if(
        sass(meta.type-of($name) == 'string'): $name; else: unquote('#{$name}'),
    );

    @if map.has-key($breakpoints, $key) {
        @return map.get($breakpoints, $key);
    }

    @error "Unknown breakpoint: #{$name}";
}

@function expr($name) {
    @if map.has-key($media-expressions, $name) {
        @return map.get($media-expressions, $name);
    }

    @error "Unknown media expression: #{$name}";
}

// ------------------------------------------------------------
// Condition parser
// ------------------------------------------------------------

@function parse-condition($condition) {
    // ----------------------------------------------------------
    // Media expressions (hover, print, reduced motion, etc.)
    // ----------------------------------------------------------
    @if map.has-key($media-expressions, $condition) {
        @return expr($condition);
    }

    // ----------------------------------------------------------
    // >=
    // ----------------------------------------------------------
    @if string.index($condition, '>=') == 1 {
        $key: string.slice($condition, 3);
        @return '(min-width: #{bp($key)})';
    }

    // ----------------------------------------------------------
    // <=
    // ----------------------------------------------------------
    @if string.index($condition, '<=') == 1 {
        $key: string.slice($condition, 3);
        @return '(max-width: #{bp($key)})';
    }

    // ----------------------------------------------------------
    // >
    // ----------------------------------------------------------
    @if string.index($condition, '>') == 1 {
        $key: string.slice($condition, 2);
        @return '(min-width: #{bp($key) + 1px})';
    }

    // ----------------------------------------------------------
    // <
    // ----------------------------------------------------------
    @if string.index($condition, '<') == 1 {
        $key: string.slice($condition, 2);
        @return '(max-width: #{bp($key) - 1px})';
    }

    // ----------------------------------------------------------
    // direct match: tablet, 4k, 1080p, etc.
    // ----------------------------------------------------------
    @return '(min-width: #{bp($condition)})';
}

// ------------------------------------------------------------
// Main mixin (drop-in replacement for include-media)
// ------------------------------------------------------------

@mixin media($conditions...) {
    $query: '';

    @each $c in $conditions {
        $part: parse-condition($c);

        @if $query == '' {
            $query: $part;
        } @else {
            $query: '#{$query} and #{$part}';
        }
    }

    @media #{$query} {
        @content;
    }
}
