@use '../../../abstracts/media' as include-media;
@use '../../../abstracts/colors';
@use '../../../abstracts/functions' as abstracts-functions;
@use '../../../abstracts/measurements';
@use '../../../abstracts/mixins';
@use '../../../abstracts/palette';
@use '../../../abstracts/variables' as abstracts-variables;
@use '../../../anchors/outline';
@use '../../../base/typography';
@use '../../../fontawesome-7/functions';
@use '../../../fontawesome-7/variables';

.v25-finder__filter {
    width: 100%;
}
.v26-finder_filters__checkbox_wrap {
    position: relative;
    margin-bottom: measurements.$measure--basic;

    &:has([name='meta_clearing_sand']) {
        background-color: colors.$color-purple5;
        border-left: abstracts-variables.$border-width-thicker solid
            colors.$color-purple70;
        padding-top: measurements.$measure--small4;
        padding-bottom: measurements.$measure--small4;
        padding-left: measurements.$measure--small1;
        padding-right: measurements.$measure--small1;
    }

    .v26-finder_filters__checkbox[name='meta_clearing_sand'] {
        &:not(:checked) + .v26-finder_filters__label {
            &::before {
                background-color: colors.$color-purewhite;
            }
        }

        &:focus {
            top: measurements.$measure--small4;
            left: measurements.$measure--small1;
        }
    }
}
.v26-finder__accordion__count {
    margin: 0 measurements.$measure--quarter;
    color: colors.$color-red50;
}
.v26-finder_filters__checkbox {
    position: absolute;
    cursor: pointer;
    left: 0;
    top: 0;
    width: measurements.$measure--small2;
    height: measurements.$measure--small2;
    z-index: abstracts-functions.z-index('above');
    margin: 0;
    appearance: none;

    &:focus {
        @include outline.outline-properties();
    }
    &:disabled,
    &:disabled + label {
        cursor: not-allowed;
        opacity: 0.65;
    }
}

.v26-finder_filters__label {
    display: block;
    padding-left: measurements.$measure--small4;
    font-size: measurements.$measure--basic;
    line-height: measurements.$measure--small2;
    position: relative;

    &::before {
        content: '';
        border: abstracts-variables.$border-width-hairline solid
            colors.$color-gray8;
        border-radius: measurements.$measure--quarter;
        width: measurements.$measure--small2;
        height: measurements.$measure--small2;
        position: absolute;
        top: 0;
        left: 0;
    }

    &:after {
        font: var(--fa-font-solid);
        content: functions.fa-content(variables.$var-check);
        display: block;
        width: measurements.$measure--small2;
        height: measurements.$measure--small2;
        position: absolute;
        top: 0;
        left: 0;
        opacity: 0;
        color: colors.$color-purewhite;
        display: flex;
        align-items: center;
        justify-content: center;
    }

    .v26-finder_filters__checkbox:checked ~ & {
        &::before {
            background-color: colors.$color-red50;
            border-color: colors.$color-red50;
        }
        &::after {
            opacity: 1;
        }
    }
}
.v26-finder__filters__reset--desktop {
    margin-left: auto;
}

.v26-finder__results__clear-filters {
    display: flex;
    align-items: center;
    gap: measurements.$measure--threequarters;
    flex-wrap: wrap;
    padding: measurements.$measure--basic measurements.$measure--basic 0 0;
    &:empty {
        display: none;
    }
    @include include-media.media('<small') {
        padding-bottom: measurements.$measure--basic;
    }
}

.v26-finder__clear-filter-tag {
    @include typography.extrasmalltype();
    background-color: colors.$color-zinc30;
    padding: 0 measurements.$measure--threequarters;
    border: initial;
    box-shadow: initial;
    min-width: measurements.$measure--small4;
    align-items: center;
    height: measurements.$measure--small2;

    .icon {
        display: flex;
        flex-direction: column;
        justify-content: center;
        margin-left: measurements.$measure--half;
    }

    &:hover,
    &:focus,
    &:active {
        background-color: colors.$color-zinc60;
        color: colors.$color-purewhite;
        border: initial;
    }
}

.v26-finder__filters__heading {
    @include include-media.media('>small') {
        @include mixins.sr-only();
    }
}

.wrapper--v26-finder__filters--mobile__toggle {
    display: none;
    background-color: colors.$color-gray11;
    color: colors.$color-purewhite;
    padding: measurements.$measure--threequarters measurements.$measure--basic;
    font-size: typography.$font-size--basic;

    &:focus,
    &:active {
        @include outline.anchor-default-outline(palette.$color-outline);
    }

    .icon {
        font-size: typography.$font-size--gamma;
    }
    @include include-media.media('<small') {
        display: block;
    }
}

.wrapper--v26-finder__filters {
    @include include-media.media('<small') {
        &[data-open='true'] {
            display: block;
            position: fixed;
            top: 0;
            left: 0;
            background: colors.$color-purewhite;
            width: 100vw;
            height: 100vh;
            z-index: abstracts-functions.z-index('modal');
            overflow-y: scroll;
        }
    }
}
.wrapper--v26-finder__filters--mobile__filters {
    @include include-media.media('<small') {
        display: none;
        .wrapper--v26-finder__filters[data-open='true'] &,
        .v26-finder__ssr__toggle:checked ~ & {
            display: block;
        }
    }
}
.wrapper--v26-finder__filters--mobile__apply {
    width: 100%;
    .icon {
        display: none;
    }
    button {
        width: 100%;
    }
}

.wrapper--v26-finder__filters--mobile__filters__close {
    @include outline.anchor-default-outline(palette.$color-outline);
    display: flex;
    align-items: center;
    justify-content: center;
    position: absolute;
    right: measurements.$measure--medium3;
    top: measurements.$measure--basic;
    color: colors.$color-purewhite;
    font-size: measurements.$measure--small2;
    padding: measurements.$measure--half;
    &:focus {
        outline-offset: -(measurements.$measure--half) + abstracts-variables.$border-width-thick; //override mixin offset value as button has transparent padding to allow for tap area.
    }
    span {
        display: flex;
        justify-content: center;
        align-items: center;
        width: measurements.$measure--small4;
        height: measurements.$measure--small4;
        background-color: colors.$color-gray11;
    }
}
.wrapper--v26-finder__filters__footer {
    display: none;
    grid-template-columns: 1fr 1fr;
    gap: measurements.$measure--basic;
    margin-top: measurements.$measure--basic;
    button {
        &:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }
    }
    @include include-media.media('<small') {
        .wrapper--v26-finder__filters[data-open='true'] & {
            display: grid;
        }
    }
}
.wrapper--v26-finder__filters__header {
    display: flex;
    justify-content: space-between;
}

.v26-finder__results__summary {
    @include include-media.media('<small') {
        padding-right: measurements.$measure--basic;
    }
}
.v26-finder__results__summary__heading {
    margin-top: 0;
    @include typography.font-family('default');
    @include typography.alphatype();
}

/*===Reset/Clear fitlers button=====*/

.v26-finder__reset {
    display: inline-flex;
    align-items: center;
    font-size: typography.$font-size--basic;
    font-weight: abstracts-variables.$font-weight-medium;

    &:focus,
    &:active {
        @include outline.anchor-default-outline(palette.$color-outline);
        //Additional focus styles added.  These are due to be rolled out globallly so can be removed once anchor-inline mixin has been updated to incorporate them
        color: colors.$color-purewhite;
        background-size: 100% 100%;
        background-image: linear-gradient(
            120deg,
            colors.$color-gray11 0%,
            colors.$color-gray11 100%
        );
    }
    .icon {
        margin-left: measurements.$measure--half;
    }
    .v26-finder__reset__text {
        width: 100%;
        text-decoration: underline;
    }
    .v26-finder__filters__reset--desktop & {
        @include include-media.media('<small') {
            display: none;
        }
    }
    .wrapper--v26-finder__filters__header & {
        display: none;
        @include include-media.media('<small') {
            display: block;
        }
        .wrapper--v26-finder__filters[data-open='true'] & {
            @include include-media.media('<small') {
                display: none;
            }
        }
    }
    .wrapper--v26-finder__filters[data-open='true'] > & {
        @include include-media.media('<small') {
            display: none;
        }
    }
    .wrapper--v26-finder__filters__footer & {
        text-decoration: none;
        .icon {
            display: none;
        }
    }
}
.wrapper--v26-finder_filters--filters {
    .v26-finder__query__submit {
        background-color: colors.$color-gray11;
        color: colors.$color-purewhite;
        padding: measurements.$measure--basic measurements.$measure--small4;
    }
}

//SSR styles
.v26-finder__ssr__toggle {
    @include include-media.media('>small') {
        display: none;
    }
    & ~ {
        .v26-finder__ssr__toggle-label {
            display: inline;

            .v26-finder__ssr__toggle__text--hide {
                display: none;
            }
            @include include-media.media('>small') {
                display: none;
            }
        }
    }
    &:checked {
        & ~ .v26-finder__ssr__toggle-label {
            .v26-finder__ssr__toggle__text--hide {
                display: inline;
            }
            .v26-finder__ssr__toggle__text--show {
                display: none;
            }
            @include include-media.media('>small') {
                display: none;
            }
        }
    }
}
