@use 'sass:list';
@use '../../abstracts/colors';
@use '../../abstracts/functions';
@use '../../abstracts/measurements';
@use '../../abstracts/palette';
@use '../../abstracts/variables';
@use '../../anchors/card/card--side-image';
@use '../../anchors/outline';
@use '../../anchors/reset';
@use '../../base/typography';

////
/// Single Colour Content
/// @group pattern
////

.sc-content {
    margin: measurements.$measure--threequarters 0;
}

.sc-content__text {
    padding: measurements.$measure--threequarters;
    margin-top: 0;
}

.sc-content__heading {
    @include typography.betatype();

    display: inline-block;
    margin: measurements.$measure--basic 0;
    padding: measurements.$measure--threequarters
        measurements.$measure--threequarters 0
        measurements.$measure--threequarters;
    margin: 0;
}

.sc-content--link {
    position: relative;

    .card-link {
        position: absolute;
        width: 100%;
        height: 100%;
        top: 0;
        left: 0;
        z-index: functions.z-index('above');
    }

    .sc-content__heading {
        padding: 0;
        margin-top: measurements.$measure--half;
    }

    .sc-content__icon {
        display: flex;
        justify-content: center;
        position: absolute;
        bottom: 0;
        right: 0;
        padding: measurements.$measure--threequarters
            measurements.$measure--basic;
        font-weight: variables.$font-weight-normal;
    }

    .sc-content__text {
        margin-right: measurements.$measure--small4;
    }

    a {
        @include reset.anchor-reset();

        display: inline-block;
        padding: 0 measurements.$measure--threequarters
            measurements.$measure--threequarters
            measurements.$measure--threequarters;

        &:focus,
        &:active {
            .card-link {
                @include outline.outline-properties(palette.$color-outline);
            }
        }
    }
}

$level-colors: (
    'grey': (
        palette.$color-sc-grey-bg,
        palette.$color-sc-grey-bg-text,
        palette.$color-sc-grey-btn,
        palette.$color-sc-grey-btn-text,
    ),
    'purple': (
        palette.$color-sc-purple-bg,
        palette.$color-sc-purple-bg-text,
        palette.$color-sc-purple-btn,
        palette.$color-sc-purple-btn-text,
    ),
    'deep-magenta': (
        palette.$color-sc-deep-magenta-bg,
        palette.$color-sc-deep-magenta-bg-text,
        palette.$color-sc-deep-magenta-btn,
        palette.$color-sc-deep-magenta-btn-text,
    ),
    'teal': (
        palette.$color-sc-teal-bg,
        palette.$color-sc-teal-bg-text,
        palette.$color-sc-teal-btn,
        palette.$color-sc-teal-btn-text,
    ),
    'yellow': (
        palette.$color-sc-yellow-bg,
        palette.$color-sc-yellow-bg-text,
        palette.$color-sc-yellow-btn,
        palette.$color-sc-yellow-btn-text,
    ),
    'green': (
        palette.$color-sc-green-bg,
        palette.$color-sc-green-bg-text,
        palette.$color-sc-green-btn,
        palette.$color-sc-green-btn-text,
    ),
    'blue': (
        palette.$color-sc-blue-bg,
        palette.$color-sc-blue-bg-text,
        palette.$color-sc-blue-btn,
        palette.$color-sc-blue-btn-text,
    ),
    'red': (
        palette.$color-sc-red-bg,
        palette.$color-sc-red-bg-text,
        palette.$color-sc-red-btn,
        palette.$color-sc-red-btn-text,
    ),
    'white-purple': (
        colors.$color-purewhite,
        colors.$color-gray10,
        palette.$color-sc-purple-btn,
        palette.$color-sc-purple-btn-text,
    ),
    'white-grey': (
        colors.$color-purewhite,
        colors.$color-gray10,
        palette.$color-sc-grey-btn,
        palette.$color-sc-grey-btn-text,
    ),
);

$level-border-colors: (
    'white-purple': (
        palette.$color-sc-purple-btn,
        palette.$color-sc-purple-btn-text,
    ),
    'white-grey': (
        palette.$color-sc-grey-btn,
        palette.$color-sc-grey-btn-text,
    ),
);

@each $level, $colors in $level-colors {
    $bg: list.nth($colors, 1);
    $bg-text: list.nth($colors, 2);
    $button: list.nth($colors, 3);
    $button-text: list.nth($colors, 4);

    .sc-content--#{$level} {
        color: $button-text;
        background-color: $button;
    }

    .sc-content--#{$level}.sc-content--link {
        color: $bg-text;
        background-color: $bg;

        .sc-content__heading {
            color: $button-text;
            background-color: $button;
        }

        a {
            background-color: $button;

            &:hover,
            &:focus,
            &:active {
                background-image: linear-gradient(
                    120deg,
                    $button 0%,
                    $button 100%
                );
            }

            .sc-content__heading {
                border-bottom: variables.$border-width-default
                    variables.$border-style-solid
                    $button-text;
            }
        }

        .sc-content__icon {
            color: $button-text;
            background-color: $button;
        }
    }
}

@each $level, $colors in $level-border-colors {
    $button: list.nth($colors, 1);
    $button-text: list.nth($colors, 2);

    .sc-content--#{$level} {
        border: variables.$border-width-default
            variables.$border-style-solid
            $button;
    }
}
