@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/variables';
@use '../../base/content';
@use '../../base/page';
@use '../../base/typography';

////
/// Statistics block
/// @group patterns
////
.statistics-block {
    background: colors.$color-purewhite;

    @include include-media.media('>=tablet') {
        padding: measurements.$measure--basic 0;
    }

    // Block renders as slider < tablet
    @include include-media.media('<tablet') {
        padding: 0 measurements.$measure--small2 measurements.$measure--basic
            measurements.$measure--small2;
        margin-top: 0;

        &[data-slider-render='tablet'] {
            .slider-block--mobile {
                [data-visible='false'] {
                    display: none;
                }
                .slider-block__control {
                    display: flex;
                    .slider-block__control__buttons--dot {
                        display: block;
                    }
                }
            }
        }
    }

    .statistics-block__heading {
        padding: measurements.$measure--basic;
        text-align: center;
    }

    .ksp__items {
        @include page.default-margin();

        margin: 0;
        max-width: none;
        text-align: center;

        // Generic properties for all statistics
        .ksp__item {
            border-right: variables.$border-width-default
                variables.$border-style-solid colors.$color-gray1;
            list-style-type: none;
            padding-left: measurements.$measure--basic;
            padding-right: measurements.$measure--basic;

            &:last-of-type {
                border-right: 0;
            }

            // Control vertical right border depending on device width
            @include include-media.media('<tablet') {
                border-right: 0;
                padding: 0;
                margin: 0;
            }

            h2 {
                @include content.h1style();

                font-weight: variables.$font-weight-light;

                .animate--number__unit--post {
                    @include typography.alphatype();
                    margin-left: measurements.$measure--quarter;
                }
            }
        }

        .ksp__item__overline {
            @include typography.font-family('default');
            color: colors.$color-gray7;
            font-size: typography.$font-size--alpha;
            font-weight: variables.$font-weight-book;
        }

        .ksp__item__pre-figure,
        .ksp__item__figure,
        .ksp__item__post-figure,
        .ksp__item__text-only {
            @include typography.font-family('heading');

            font-weight: variables.$font-weight-light;
            display: inline;
            color: colors.$color-red50;
        }

        .ksp__item__text {
            @include typography.font-family('default');

            color: colors.$color-gray10;
            font-size: typography.$font-size--alpha;
            font-weight: variables.$font-weight-text;
            margin: measurements.$measure--basic 0;
        }

        .ksp__item__icon {
            display: block;
            margin: 0 auto;
            width: 52px; // Icon height matches text height.

            @include include-media.media('<tablet') {
                margin: 0;
                display: inline;
            }
        }

        .ksp__item__heading--top-padding,
        .ksp__item__icon--top-padding {
            @include include-media.media('<tablet') {
                padding-top: measurements.$measure--basic;
            }
        }

        // Animation
        .animation-incomplete {
            opacity: 0;
        }

        .animation-incomplete.animation-complete {
            opacity: 1;
            transition: opacity 1500ms;
        }

        .animate--number--init {
            .animate--number__unit {
                opacity: 0;
            }
        }

        .animate--number--complete {
            .animate--number__unit {
                transition: opacity 1s;
                opacity: 1;
            }
        }

        // Control individual statistic width based on parent class
        &.ksp__items--2 {
            @include include-media.media('>=tablet') {
                display: flex;
                flex-direction: row;
                flex-wrap: nowrap;

                .ksp__item {
                    width: 50%;
                }
            }
        }

        &.ksp__items--3 {
            @include include-media.media('>=tablet') {
                display: flex;
                flex-direction: row;
                flex-wrap: nowrap;

                .ksp__item {
                    width: 33%;
                    padding: 0 measurements.$measure--basic;
                }
            }
        }

        &.ksp__items--4 {
            @include include-media.media('>=tablet') {
                display: flex;
                flex-direction: row;
                flex-wrap: nowrap;

                .ksp__item {
                    width: 25%;
                }
            }
        }
    }
}
