@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/mixins';
@use '../abstracts/variables';
@use 'outline';
@use 'reset';

@mixin pathway-card(
    $card-text-color: colors.$color-nearblack,
    $card-text-hover-color: colors.$color-nearblack,
    $card-background-color: transparent,
    $card-background-hover-color: colors.$color-gray1,
    $card-heading-color: colors.$color-nearblack,
    $section-title-color: colors.$color-nearblack,
    $border-color: colors.$color-gray1,
    $outline-color: colors.$color-nearblack
) {
    @include reset.anchor-reset();
    @include mixins.background-color-and-transition(
        $card-background-color,
        $card-background-hover-color
    );

    border: variables.$border-width-hairline variables.$border-style-solid
        $border-color;
    color: $card-text-color;
    display: block;

    .card--pathway__content__heading {
        color: $section-title-color;
    }

    .card--pathway__content__heading__text {
        border-bottom-color: $section-title-color;
        border-bottom-style: variables.$border-style-solid;
        border-bottom-width: variables.$border-width-default;
    }

    p {
        color: $card-text-color;
    }

    .card--pathway__content__img {
        transition: transform variables.$transition-duration ease-in-out;
        overflow: hidden;
    }

    @include include-media.media('reducemotion') {
        transition: none;
    }

    &:hover {
        @include include-media.media('hover') {
            .card--pathway__content__img {
                transform: scale(1.02);
            }

            .card--pathway__content__heading,
            p {
                color: $card-text-hover-color;
            }

            .card--pathway__content__heading__text {
                border-bottom-color: $card-text-hover-color;
            }
        }
    }

    &:active,
    &:focus {
        @include outline.outline-properties($outline-color);

        .card--pathway__content__heading,
        p {
            color: $card-text-hover-color;
        }

        .card--pathway__content__heading__text {
            border-bottom-color: $card-text-hover-color;
        }
    }

    &:visited {
        .card--pathway__content__heading {
            color: $section-title-color;
        }

        p {
            color: $card-text-color;
        }

        .card--pathway__content__heading__text {
            border-bottom-color: $section-title-color;
        }
    }
}
