@use 'search--inline';
@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/functions';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/palette';
@use '../../abstracts/variables';
@use '../../anchors/inline';
@use '../../anchors/outline';
@use '../../anchors/reset';
@use '../../base/content';
@use '../../base/typography';

.search {
    .search__results__summary__heading {
        @include typography.font-family('default');
        @include typography.alphatype();
        @include typography.body-font-features();
    }

    .wrapper--search__results:not(.tabs) {
        .tabs__links {
            display: none;
        }
    }

    .wrapper--search__results,
    .wrapper--search__othersites {
        @include include-media.media('<=between') {
            margin-left: -#{measurements.$measure--basic};
            margin-right: -#{measurements.$measure--basic};
        }

        @include include-media.media('>between', '<small') {
            margin-left: -#{measurements.$measure--small2};
            margin-right: -#{measurements.$measure--small2};
        }
    }

    .wrapper--search__results {
        .tabs__panel__body {
            padding-bottom: measurements.$measure--small4;
        }
    }

    .search-form__query + .wrapper--search__results {
        .tabs__links {
            margin-top: 1.75rem;
        }
    }

    .search__bestbets {
        margin-top: measurements.$measure--medium3;
    }

    .search__othersites {
        background-color: colors.$color-gray1;
        border-color: colors.$color-gray3;
        border-style: variables.$border-style-solid;
        border-width: variables.$border-width-default;
        padding: measurements.$measure--basic;

        @include include-media.media('<small') {
            margin-top: measurements.$measure--small4;
        }

        .search__othersites__heading {
            @include content.h3style();

            margin-top: 0;
        }
    }

    .search__results__summary {
        border-bottom: variables.$border-width-hairline
            variables.$border-style-solid colors.$color-gray3;
        padding-bottom: measurements.$measure--basic;
        margin-left: auto;
        margin-right: auto;
        max-width: calc(
            #{typography.$max-line-length} + #{measurements.$measure--huge5} + #{measurements.$measure--basic}
        );
    }

    .search__results__list,
    .search__results__browse-more,
    .search__results__browse-more ul,
    .search__bestbets__list {
        list-style: none;
        margin-left: auto;
        margin-right: auto;
        max-width: calc(
            #{typography.$max-line-length} + #{measurements.$measure--huge5} + #{measurements.$measure--basic}
        );

        .card--search {
            padding-bottom: measurements.$measure--basic;

            .card__heading {
                .icon {
                    color: palette.$color-inline-link;
                    margin-left: measurements.$measure--half;
                }
            }

            a {
                @include reset.anchor-reset();

                background-color: transparent;
                color: colors.$color-nearblack;

                &:hover {
                    @include include-media.media('hover') {
                        color: colors.$color-nearblack;
                    }
                }

                &:active,
                &:focus {
                    @include outline.outline-properties(
                        colors.$color-nearblack
                    );

                    color: colors.$color-nearblack;
                }

                .card__heading {
                    @include content.h4style();

                    background-image: linear-gradient(
                        120deg,
                        palette.$color-inline-link 0%,
                        palette.$color-inline-link 100%
                    );
                    background-position: 0 100%;
                    background-repeat: no-repeat;
                    background-size: 100% 0;
                    border-bottom-color: palette.$color-inline-link;
                    border-bottom-style: variables.$border-style-solid;
                    border-bottom-width: variables.$border-width-default;
                    color: palette.$color-inline-link;
                    display: inline;
                    max-width: typography.$max-line-length;
                    transition: background-size variables.$transition-duration
                        variables.$transition-function;

                    @include include-media.media('reducemotion') {
                        transition: none;
                    }
                }

                &:hover {
                    @include include-media.media('hover') {
                        .card__thumbnail {
                            transform: scale(1.02);
                        }

                        .card__heading {
                            background-size: 100% 100%;
                            background-image: linear-gradient(
                                120deg,
                                palette.$color-inline-link 0%,
                                palette.$color-inline-link 100%
                            );
                            color: colors.$color-purewhite;
                        }
                    }
                }
            }

            .card__label {
                @include typography.smalltype();

                color: colors.$color-gray8;
                font-style: italic;
            }

            .card__details {
                display: flex;
                flex-wrap: nowrap;

                @include include-media.media('<small') {
                    flex-direction: column;
                }

                @include include-media.media('>=small') {
                    flex-direction: row;
                }
            }

            .card__thumbnail + .card__details__text {
                @include include-media.media('<small') {
                    padding-left: 0;
                    padding-top: measurements.$measure--basic;
                }

                @include include-media.media('>=small') {
                    padding-left: measurements.$measure--basic;
                    padding-top: 0;
                }
            }

            .card__details__text {
                width: 100%;
            }

            .card__description {
                @include content.content-style();

                margin-top: variables.$content-element-margin;
                max-width: typography.$max-line-length;
            }

            .card__url {
                @include typography.smalltype();
                margin-top: measurements.$measure--basic;
                max-width: unset;
                color: colors.$color-gray7;
                word-break: break-word;
            }

            .card__thumbnail {
                align-self: flex-start;
                flex-shrink: 0;
                height: auto;
                transition: transform variables.$transition-duration ease-in-out;
                width: measurements.$measure--huge5;

                @include include-media.media('reducemotion') {
                    transition: none;
                }
            }

            & + .card--search {
                border-top: variables.$border-width-hairline
                    variables.$border-style-solid colors.$color-gray3;
                padding-top: measurements.$measure--basic;
            }
        }

        .card {
            .card__anchor {
                .card__type {
                    color: colors.$color-nearblack;
                    font-size: typography.$font-size--alpha;
                }

                .card__heading {
                    @include content.h4style();

                    background-image: linear-gradient(
                        120deg,
                        palette.$color-inline-link 0%,
                        palette.$color-inline-link 100%
                    );
                    background-position: 0 100%;
                    background-repeat: no-repeat;
                    background-size: 100% 0;
                    border-bottom-color: palette.$color-inline-link;
                    border-bottom-style: variables.$border-style-solid;
                    border-bottom-width: variables.$border-width-default;
                    color: palette.$color-inline-link;
                    display: inline;
                    max-width: typography.$max-line-length;
                    transition: background-size variables.$transition-duration
                        variables.$transition-function;

                    @include include-media.media('reducemotion') {
                        transition: none;
                    }
                }

                .card__details__text {
                    padding: initial;
                    padding-bottom: measurements.$measure--basic;
                }

                &:hover {
                    @include include-media.media('hover') {
                        .card__heading {
                            background-size: 100% 100%;
                            background-image: linear-gradient(
                                120deg,
                                palette.$color-inline-link 0%,
                                palette.$color-inline-link 100%
                            );
                            color: colors.$color-purewhite;
                        }
                    }
                }
            }

            & + .card {
                border-top: variables.$border-width-hairline
                    variables.$border-style-solid colors.$color-gray3;
                padding-top: measurements.$measure--basic;
            }

            .card--profile--thumbnailAvailable {
                flex-direction: row-reverse;
                justify-content: space-between;
                padding-bottom: measurements.$measure--basic;

                @include include-media.media('<=mobile') {
                    flex-direction: column-reverse;
                }
            }
        }
    }

    .search__bestbets__list {
        @include include-media.media('>small') {
            max-width: initial;
        }
        .card--search .card__details {
            padding: measurements.$measure--basic;

            &,
            &:active,
            &:focus {
                border-color: colors.$color-gray3;
                border-style: variables.$border-style-solid;
                border-width: variables.$border-width-hairline;
            }

            &:hover {
                @include include-media.media('hover') {
                    border-color: colors.$color-gray3;
                    border-style: variables.$border-style-solid;
                    border-width: variables.$border-width-hairline;
                }
            }
        }
    }

    .search__results__list {
        .card {
            margin-top: initial;
            .card__anchor {
                &:after {
                    content: '';
                    background-color: initial;
                    color: initial;
                }
            }

            .card__tag {
                .icon {
                    color: colors.$color-nearblack;
                }
            }
        }
    }

    .search__othersites__noresults {
        display: block;
    }

    .search__othersites__site + .search__othersites__noresults {
        display: none;
    }

    .search__query__suggestions {
        background-color: colors.$color-purewhite;
        border-radius: 0 0 measurements.$measure--half
            measurements.$measure--half;
        border-top: 0;
        border: variables.$border-width-hairline variables.$border-style-solid
            colors.$color-gray2;
        box-shadow: rgba(0, 0, 0, 0.25) 0 measurements.$measure--basic
            measurements.$measure--medium3
            (-(measurements.$measure--threequarters));
        color: colors.$color-purewhite;
        font-weight: variables.$font-weight-bold;
        left: 0;
        list-style: none;
        margin-left: 0;
        max-width: unset;
        position: absolute;
        top: measurements.$measure--medium1;
        width: 100%;
        z-index: functions.z-index('above');

        li {
            font-weight: variables.$font-weight-text;
            margin-top: 0;

            button {
                color: palette.$color-text;
                height: 100%;
                padding: measurements.$measure--half
                    measurements.$measure--small4 measurements.$measure--half
                    measurements.$measure--small4;
                text-align: left;
                width: 100%;

                &:focus {
                    outline-color: colors.$color-nearblack;
                    outline-offset: (-(variables.$border-width-default));
                    outline-style: variables.$border-style-dotted;
                    outline-width: variables.$border-width-default;
                    text-decoration: underline;
                }

                &:active {
                    @include outline.outline-properties();

                    outline-offset: 0;
                }

                &:hover {
                    background-color: colors.$color-linkblue;
                    color: colors.$color-purewhite;
                    text-decoration: underline;
                }

                .search__suggestion {
                    font-weight: variables.$font-weight-bold;
                }
            }
        }
    }

    .search__query__suggestions.hide {
        display: none;
    }

    .search__othersites__site__heading {
        @include typography.font-family('default');
        @include typography.alphatype();
        @include typography.body-font-features();

        font-weight: variables.$font-weight-text;
    }

    .search__othersites__site__heading,
    .search__results__more,
    .search__summary__noresults {
        a {
            @include inline.anchor-inline();
        }

        .icon {
            color: palette.$color-inline-link;
        }
    }

    .search__results__more {
        max-width: calc(
            #{typography.$max-line-length} + #{measurements.$measure--huge5} + #{measurements.$measure--basic}
        );
        margin-left: auto;
        margin-right: auto;
        text-align: right;
    }

    @mixin selected-select() {
        background-color: colors.$color-purewhite;
        border-color: colors.$color-red60;
        color: colors.$color-red60;
        font-weight: variables.$font-weight-medium;
    }

    .search__select {
        color: colors.$color-nearblack;
        height: auto;
        margin-top: measurements.$measure--half;
        position: relative;

        @include include-media.media('<tablet') {
            margin-bottom: measurements.$measure--half;
        }

        @include include-media.media('>=tablet') {
            margin-right: measurements.$measure--basic;
        }

        label {
            @include mixins.sr-only();
            @include typography.smalltype();

            color: colors.$color-red50;
            display: block;
            font-weight: variables.$font-weight-text;
            padding-bottom: measurements.$measure--basic;
        }

        select {
            @include typography.font-family('default');
            @include typography.body-font-features();
            @include typography.alphatype();

            background-color: colors.$color-gray1;
            border-color: colors.$color-gray4;
            border-style: variables.$border-style-solid;
            border-width: variables.$border-width-default;
            bottom: measurements.$measure--quarter;
            color: colors.$color-nearblack;
            font-weight: variables.$font-weight-text;
            height: measurements.$measure--medium4;
            position: relative;
            width: 100%;

            &:focus {
                @include outline.outline-properties();
            }
        }

        &:not(.search__select--sort) {
            &.search__select--selected {
                select {
                    @include selected-select();
                }
            }
        }

        &.search__select--sort {
            &.search__select--selected {
                select {
                    @include include-media.media('<tablet') {
                        @include selected-select();
                    }
                }
            }
        }
    }
}
