@use '../../../abstracts/colors';
@use '../../../abstracts/measurements';

.content-separator {
    height: 0.3rem;
    display: block;
    background-color: colors.$color-red50;
    margin: measurements.$measure--small5 0;
}

.content-separator--transition-start {
    width: 20%;
}
.content-separator--transition-complete {
    width: 100%;
    transition: width ease 0.5s;
}
