@use '../../../abstracts/colors';
@use '../../../abstracts/measurements';
@use '../../../abstracts/variables';
@use '../../../anchors/outline';
@use '../../../base/typography';

.finder__accordion {
    width: 100%;
    padding: 0 measurements.$measure--basic;
    border-bottom: variables.$border-width-hairline solid colors.$color-gray4;

    &:focus-within {
        @include outline.outline-properties(colors.$color-gray11);
    }
}
.v26-finder__accordion__content {
    display: flex;
    flex-direction: column;
    padding-bottom: measurements.$measure--half;
    &[data-closed='true'] {
        display: none;
    }
}
.v26-finder__accordion__heading {
    margin: 0;
    font-size: typography.$font-size--beta;
}
.v26-finder__accordion__toggle {
    width: 100%;
    display: flex;
    align-items: center;
    padding: measurements.$measure--threequarters 0;
    border-bottom: colors.$color-gray4;

    &:focus {
        @include outline.outline-reset();
    }

    .finder__accordion__toggle__icon {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: measurements.$measure--small2;
        height: measurements.$measure--small2;
        background-color: colors.$color-gray11;
        border-radius: 100%;
        color: colors.$color-purewhite;
        margin-left: auto;
        font-size: typography.$font-size--basic;

        .v26-finder__accordion__toggle[aria-expanded='true'] & {
            transform: rotate(180deg);
        }
    }
}
