@use '../abstracts/media' as include-media;
@use '../abstracts/colors';
@use '../abstracts/measurements';
@use '../abstracts/palette';
@use '../anchors/inline';
@use '../base/page';
@use '../layout/grid';

// Desktop-specific layout
main {
    @include include-media.media('>=small') {
        > .listing {
            grid-column: 1 / span 24;

            .banner-text {
                @include grid.standard-grid();
                padding-left: measurements.$measure--half;
                padding-right: measurements.$measure--half;

                .banner-text__content {
                    grid-column: 3/-3;
                    margin-right: 0;
                    margin-left: 0;
                    padding-left: 0;
                    padding-right: 0;
                }
            }

            .finder {
                @include grid.x-column-grid(24);
                display: grid;

                .finder__query,
                .wrapper--finder__filters,
                .finder__results {
                    grid-column: 3 / -3;
                }

                .finder__query {
                    margin-left: 0;
                    margin-right: 0;
                }

                .wrapper--finder__filters .finder__filters__heading,
                .finder__results__summary {
                    margin: 0;
                    padding-left: 0;
                    padding-right: 0;
                }

                .wrapper--finder__filters .wrapper--finder_filters--filters {
                    margin: 0;
                }

                .finder__results__list {
                    @include grid.x-column-grid(20);

                    .finder__results__card {
                        grid-column: 3 / -3;
                    }

                    &.finder__results__list--three-up {
                        display: flex;

                        .finder__results__card {
                            grid-column: unset;
                            width: calc(50% - #{measurements.$measure--basic});
                        }
                    }
                }
            }
        }
    }
}

// Desktop specific layout if secondary navigation is present
main {
    @include include-media.media('>=small') {
        .navigation--secondary {
            grid-column: 1 / span 6;

            & + .listing {
                grid-column: 7 / span 18;

                .banner-text {
                    display: inherit;

                    .banner-text__content {
                        margin-left: measurements.$measure--small2;
                        margin-right: measurements.$measure--small2;
                    }
                }

                .finder {
                    display: block;

                    .finder__query {
                        margin-left: measurements.$measure--small2;
                        margin-right: measurements.$measure--small2;
                    }

                    .wrapper--finder__filters .finder__filters__heading,
                    .finder__results__summary,
                    .finder__results__announcement {
                        @include page.default-margin();
                    }

                    .wrapper--finder__filters
                        .wrapper--finder_filters--filters {
                        @include page.default-margin();
                    }

                    .finder__results__list {
                        @include grid.content-grid();

                        .finder__results__card {
                            grid-column: 3 / -3;
                        }

                        &.finder__results__list--three-up {
                            display: flex;

                            .finder__results__card {
                                grid-column: unset;
                            }
                        }
                    }
                }
            }
        }
    }
}

// layout no side navigation present
main {
    @include include-media.media('<small') {
        .listing {
            .banner-text {
                .banner-text__content {
                    padding-left: measurements.$measure--half;
                    padding-right: measurements.$measure--half;
                    margin-left: measurements.$measure--small2;
                    margin-right: measurements.$measure--small2;
                }
            }
        }
    }

    @include include-media.media('<tablet') {
        .listing {
            .banner-text {
                .banner-text__content {
                    margin-left: measurements.$measure--half;
                    margin-right: measurements.$measure--half;
                }
            }
        }

        .finder {
            .finder__query {
                margin-left: measurements.$measure--half;
                margin-right: measurements.$measure--half;
            }
        }
    }
}

// Generic
.listing {
    /*** BANNER COLOURS
     *
     * Each listing has a unique theme ID attribute for banner colour styling
     ***/

    // Courses
    &[data-theme-id='494808'] {
        .banner-text {
            background-color: colors.$color-gray666;
            color: colors.$color-purewhite;
        }
    }

    // No search component
    &[data-theme-id='531052'],
    &[data-theme-id='592970'],
    &[data-theme-id='495139'] {
        .banner-text {
            background: colors.$color-brown30;
            background: linear-gradient(
                180deg,
                colors.$color-brown30 0%,
                colors.$color-purewhite 100%
            );
            color: colors.$color-nearblack;
        }
    }

    // Generic banner rules
    .banner-text {
        background: colors.$color-gray666;
        color: colors.$color-purewhite;
        padding-bottom: measurements.$measure--large1;
        padding-top: measurements.$measure--small2;
    }

    /*** END BANNER COLOURS ***/

    .content {
        margin: 0;
    }

    padding-bottom: measurements.$measure--small2;

    .finder__query {
        margin-top: -(measurements.$measure--medium7);
        @include include-media.media('<tablet') {
            margin-left: 0;
            margin-right: 0;
        }
    }

    @include include-media.media('<tablet') {
        .finder__results {
            @include page.default-padding();
        }
    }

    .wrapper--listing__content {
        @include page.default-padding();

        background-color: colors.$color-pink90;
        color: colors.$color-purewhite;
        margin-top: measurements.$measure--small2;
        padding-bottom: measurements.$measure--small2;
        padding-top: measurements.$measure--basic;

        .card--contact {
            border-top: 0;

            .icon {
                color: colors.$color-purewhite;
            }

            a {
                @include inline.anchor-inline(
                    colors.$color-gray4,
                    colors.$color-gray4,
                    colors.$color-gray11,
                    palette.$color-outline--dark
                );
            }
        }
    }

    @include include-media.media('<small', '>=tablet') {
        .finder__results__list--three-up {
            .card--news a {
                flex-direction: column;

                img {
                    width: 100%;
                }
            }
        }
    }

    @include include-media.media('<tablet') {
        .wrapper--finder__filters--mobile[data-open='false'] {
            margin-top: -#{measurements.$measure--medium7};
        }

        .finder__query ~ .wrapper--finder__filters--mobile[data-open='false'] {
            margin-top: unset;
        }
    }

    @include include-media.media('>=tablet') {
        .wrapper--finder__filters {
            margin-top: -#{measurements.$measure--medium7};
        }

        .finder__query ~ .wrapper--finder__filters {
            margin-top: unset;
        }
    }
}
