@use 'sass:map';
@use 'finder-filters';
@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/functions';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/palette';
@use '../../abstracts/variables';
@use '../../anchors/cta--basic';
@use '../../anchors/inline';
@use '../../anchors/outline';
@use '../../anchors/underline-basic';
@use '../../base/content';
@use '../../base/page';
@use '../../base/typography';
@use '../../layout/grid';
@use '../../fontawesome-7/mixins' as fa-mixins;
@use '../../fontawesome-7/variables' as fa-variables;

main {
    @include include-media.media('>=tablet') {
        > article {
            .finder {
                .finder__results__list {
                    @include grid.content-grid();

                    grid-auto-rows: auto;

                    .card {
                        grid-column: 3 / -3;
                    }

                    &.finder__results__list--three-up {
                        display: flex;
                        flex-direction: row;
                        flex-wrap: wrap;

                        .card {
                            grid-column: unset;
                            padding: measurements.$measure--quarter;
                            width: calc(33% - #{measurements.$measure--basic});
                        }
                    }
                }
            }
        }
    }
}

main {
    > article {
        .finder {
            .finder__results__list {
                &.finder__results__list--three-up {
                    margin-left: 0;
                    margin-right: 0;
                    max-width: unset;

                    @include include-media.media('>mobile') {
                        @include page.default-margin();
                    }
                }
            }
        }
    }
}

// Desktop-specific layout
main {
    @include include-media.media('>=small') {
        > article {
            .finder {
                .banner-text .banner-text__content {
                    @include grid.x-column-grid(24);

                    display: grid;
                    margin: 0;
                    padding: 0;

                    h1,
                    p {
                        grid-column: 3 / -3;
                    }
                }
            }
        }
    }

    @include include-media.media('>=desktop') {
        > article {
            .finder {
                .banner-text .banner-text__content {
                    h1,
                    p {
                        grid-column: 4 / -4;
                    }
                }

                .finder__query,
                .wrapper--finder__filters,
                .finder__results {
                    grid-column: 4 / -4;
                }

                .finder__results__list {
                    @include grid.content-grid();

                    .card {
                        grid-column: 3 / -3;
                    }

                    &.finder__results__list--three-up {
                        display: flex;

                        .card {
                            grid-column: unset;
                            padding: measurements.$measure--quarter;
                            width: calc(33% - #{measurements.$measure--basic});
                        }
                    }
                }
            }
        }
    }
}

// Desktop specific layout if secondary navigation is present
main {
    @include include-media.media('>=small') {
        .navigation--secondary {
            & + article {
                .finder {
                    .banner-text .banner-text__content {
                        @include page.standard-box();
                        display: block;
                    }
                }
            }
        }
    }
}

.finder__query {
    background-color: colors.$color-gray11;
    padding: measurements.$measure--small2;
    position: relative;

    & > div {
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        height: 100%;
    }

    @include include-media.media('>=tablet') {
        margin-left: measurements.$measure--small2;
        margin-right: measurements.$measure--small2;
    }
}

.finder__query__input {
    @include typography.font-family('default');
    @include typography.body-font-features();
    @include typography.alphatype();

    @include include-media.media('>=tablet') {
        @include typography.gammatype();
    }

    background-color: colors.$color-purewhite;
    display: flex;
    flex-grow: 1;
    font-weight: variables.$font-weight-text;
    padding: 0;
    position: relative;

    &:focus-within {
        @include outline.outline-properties(colors.$color-purewhite);
    }

    input {
        @include typography.font-family('default');
        @include typography.body-font-features();
        @include typography.gammatype();

        border: variables.$border-width-hairline solid transparent;
        font-style: normal;
        height: 100%;
        min-width: 0; // Constrains width in Firefox
        padding-bottom: measurements.$measure--half;
        padding-left: measurements.$measure--half;
        padding-right: measurements.$measure--medium5;
        padding-top: measurements.$measure--half;
        width: 100%;

        &:focus {
            color: colors.$color-gray10;
            font-style: normal;
            font-weight: variables.$font-weight-medium;
            outline: 0;
        }

        &::placeholder {
            font-style: italic;
        }

        &:placeholder-shown {
            color: colors.$color-gray7;
        }
    }

    .finder__clear {
        @include typography.epsilontype();

        align-items: center;
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        height: measurements.$measure--small5;
        justify-content: center;
        position: absolute;
        right: measurements.$measure--half;
        top: measurements.$measure--quarter;
        width: measurements.$measure--small5;

        &:focus {
            @include outline.outline-properties();

            outline-offset: -#{variables.$border-width-thicker};
        }

        .finder__clear__text {
            @include mixins.sr-only();
        }

        .icon {
            @include content.xmark-temp-styling;
            @include fa-mixins.fa-size(map.get(fa-variables.$sizes, '2xs'));

            letter-spacing: 0;
            line-height: 1;
        }

        &:hover {
            background-color: transparent;

            .icon {
                /*
                temp overide with xmark-temp-styling below

                --fa-primary-color: #{colors.$color-gray1};
                --fa-secondary-color: #{colors.$color-gray7};
                */
                @include content.xmark-temp-styling-hover;
            }
        }
    }
}

.finder__query__icon--wrapper {
    background-color: colors.$color-purewhite;
    padding-bottom: measurements.$measure--half;
    padding-left: measurements.$measure--half;
    padding-right: measurements.$measure--basic;
    padding-top: #{measurements.$measure--quarter +
        variables.$border-width-hairline};

    @include include-media.media('<tablet') {
        display: none;
    }
}

.finder__query__submit {
    @include typography.gammatype();
    @include cta--basic.cta--basic(
        colors.$color-purewhite,
        colors.$color-red50,
        colors.$color-purewhite,
        colors.$color-red70,
        colors.$color-purewhite,
        round
    );

    flex-shrink: 0;
    font-weight: variables.$font-weight-book;
    margin-left: measurements.$measure--basic;

    &:hover {
        cursor: pointer;
    }

    @include include-media.media('>=tablet') {
        margin-left: measurements.$measure--small4;
    }

    @include include-media.media('<tablet') {
        padding: measurements.$measure--basic measurements.$measure--small1;

        &:hover {
            padding: measurements.$measure--basic measurements.$measure--small1;
        }
    }

    span {
        margin: auto;
    }

    .finder__query__submit__text {
        @include include-media.media('<tablet') {
            @include mixins.screenreader-only();
        }
    }

    .finder__query__submit__icon {
        font-weight: variables.$font-weight-medium;
        padding: 0 measurements.$measure--half 0 0;

        @include include-media.media('<tablet') {
            display: block;
            padding: 0;
        }
    }
}
.finder__filter__submit {
    margin-bottom: measurements.$measure--threequarters;
    margin-right: measurements.$measure--basic;
    margin-top: measurements.$measure--quarter;
}

.finder__submit {
    @include typography.alphatype();
    margin-left: initial;
}

.finder__didyoumean__button {
    @include inline.anchor-inline(
        palette.$color-inline-link,
        palette.$color-inline-link,
        palette.$color-text--dark,
        palette.$color-outline
    );
}

.finder__filter {
    legend {
        @include content.h3style();
        position: relative;
        display: block;
        width: 100%;
        background-color: colors.$color-purewhite;
        padding: 0;

        button {
            background-image: none;
            border-bottom-color: colors.$color-purewhite;
            padding: measurements.$measure--threequarters
                measurements.$measure--small2;
            width: 100%;

            &:active,
            &:focus {
                outline-offset: -(measurements.$measure--quarter);
            }

            &:hover {
                .icon {
                    color: colors.$color-red50;
                    transition: color variables.$transition-duration--long;
                }
            }

            & > span {
                color: colors.$color-nearblack;
                display: flex;
                flex-direction: row;
                flex-wrap: nowrap;
                justify-content: space-between;
            }
        }

        button[aria-expanded='true'] {
            .icon {
                color: colors.$color-red50;
            }
        }
    }

    label {
        cursor: pointer;
        width: 100%;
    }

    input:not(:disabled) {
        cursor: pointer;
    }

    input[type='radio'] {
        align-self: flex-start;
        display: block;
        margin-right: measurements.$measure--basic;
        margin-top: measurements.$measure--half;
    }

    legend[data-open='true'] {
        &:after {
            border-top: variables.$border-width-hairline solid
                colors.$color-gray3;
            bottom: 0;
            content: '';
            left: measurements.$measure--small2;
            position: absolute;
            width: calc(100% - #{measurements.$measure--medium3});
        }
    }

    legend[data-open='true'] + ul {
        display: block;
    }

    legend[data-open='false'] + ul {
        display: none;
    }

    ul {
        background-color: colors.$color-purewhite;
        list-style-type: none;
        margin-left: 0;
        margin-top: 0;
        max-width: unset;
        padding: measurements.$measure--threequarters
            measurements.$measure--small2;
        position: relative;
    }

    li {
        align-items: center;
        display: flex;
        flex-direction: row;
    }
}

.finder__query__suggestions {
    background-color: colors.$color-purewhite;
    border-radius: 0 0 measurements.$measure--half measurements.$measure--half;
    border-top: 0;
    border: variables.$border-width-hairline variables.$border-style-solid
        colors.$color-gray2;
    box-shadow: rgba(0, 0, 0, 0.25) 0 measurements.$measure--basic
        measurements.$measure--medium3 (-(measurements.$measure--threequarters));
    color: colors.$color-purewhite;
    font-weight: variables.$font-weight-bold;
    left: 0;
    list-style: none;
    margin-left: 0;
    max-width: unset;
    position: absolute;
    top: measurements.$measure--medium1;
    width: 100%;
    z-index: functions.z-index('above');

    li {
        font-weight: variables.$font-weight-text;
        margin-top: 0;

        button {
            color: palette.$color-text;
            height: 100%;
            padding: measurements.$measure--half measurements.$measure--small4
                measurements.$measure--half measurements.$measure--small4;
            text-align: left;
            width: 100%;

            &:focus {
                outline-color: colors.$color-nearblack;
                outline-offset: (-(variables.$border-width-default));
                outline-style: variables.$border-style-dotted;
                outline-width: variables.$border-width-default;
                text-decoration: underline;
            }

            &:active {
                @include outline.outline-properties();

                outline-offset: 0;
            }

            &:hover {
                background-color: colors.$color-linkblue;
                color: colors.$color-purewhite;
                text-decoration: underline;
            }

            .finder__suggestion {
                font-weight: variables.$font-weight-bold;
            }
        }
    }
}

.finder__query__suggestions.hide {
    display: none;
}

.listing {
    &[data-theme-id='498744'] {
        .finder__results__announcement {
            a {
                @include underline-basic.underline-basic(
                    $inactive-color: colors.$color-purewhite,
                    $hover-color: colors.$color-purewhite,
                    $underline-width: variables.$border-width-default,
                    $outline: colors.$color-purewhite
                );
            }
        }
    }
}

.finder__results__announcement {
    padding: measurements.$measure--basic;
    background-color: palette.$color-bg--dark;
    color: colors.$color-purewhite;
    margin-bottom: measurements.$measure--basic;
    margin-top: measurements.$measure--basic;

    p {
        max-width: initial;
        margin-top: initial;
    }
}

.finder__results__summary__heading {
    @include content.h3style();

    text-align: left;

    @include include-media.media('<=mobile') {
        @include typography.betatype();
    }

    span {
        @include content.content-style();

        span {
            color: colors.$color-red50;
            font-weight: variables.$font-weight-bold;

            @include include-media.media('<=mobile') {
                font-weight: variables.$font-weight-medium;
            }
        }
    }
}

.finder__results__summary {
    border-bottom: variables.$border-width-hairline
        variables.$border-style-solid colors.$color-gray4;
    padding-bottom: measurements.$measure--quarter;

    &:not(.finder__results__summary--noresults) {
        @include include-media.media('>=tablet') {
            align-items: center;
            display: flex;
            flex-direction: row;
            flex-wrap: nowrap;
            justify-content: space-between;
        }
    }

    &.finder__results__summary--noresults {
        border-bottom: none;
    }

    button {
        @include inline.anchor-inline();
    }
}

.finder .finder__results {
    @include include-media.media('>=tablet') {
        margin-left: 0;
        margin-right: 0;
    }

    .finder__results__summary,
    .finder__results__updating,
    .finder__results__didyoumean,
    .pagination__wrapper {
        @include include-media.media('>=tablet') {
            margin-left: measurements.$measure--small2;
            margin-right: measurements.$measure--small2;
        }
    }

    .pagination__wrapper {
        border-top: variables.$border-width-hairline
            variables.$border-style-solid colors.$color-gray4;
        max-width: unset;
    }

    .pagination__controls {
        justify-content: center;
    }
}

.finder__results__list {
    list-style-type: none;
    margin-left: 0;
    max-width: unset;
}

.finder .highlightText {
    background-color: colors.$color-red10;
}

.finder__results__updating {
    @include typography.gammatype();

    margin-bottom: variables.$heading-margin;
    margin-top: variables.$heading-margin;

    .icon {
        color: colors.$color-red50;
    }
}

.card {
    margin-top: measurements.$measure--small4;

    &:last-of-type {
        margin-bottom: measurements.$measure--small4;
    }
}

.finder__results__bestbet {
    a .finder__results__card__description {
        color: palette.$color-text;
    }
}

.finder__input-text__wrapper {
    background-color: colors.$color-purewhite;
    display: flex;
    flex: 1;
    padding: measurements.$measure--half measurements.$measure--threequarters
        measurements.$measure--quarter measurements.$measure--quarter;
}

.finder__input-text__label {
    display: none;
}

.finder__icon {
    background-color: colors.$color-purewhite;
    color: colors.$color-gray7;
    font-weight: variables.$font-weight-text;
    margin-bottom: measurements.$measure--half;
    margin-top: measurements.$measure--threequarters;
}

.edge {
    .finder__query__input {
        input {
            &:focus {
                @include outline.outline-properties();
            }
        }

        .finder__clear {
            &:focus {
                @include outline.outline-properties();
            }
        }
    }

    .finder__select select {
        &:focus {
            @include outline.outline-properties();
        }
    }
}

.wrapper--finder__select--sort--desktop {
    display: none;

    @include include-media.media('>=tablet') {
        display: block;

        .finder__select--sort {
            align-items: center;
            display: flex;
            flex-direction: row;
            flex-wrap: nowrap;
            justify-content: flex-end;
            margin-top: 0;

            label {
                flex-shrink: 0;
                margin-right: measurements.$measure--half;
                margin-bottom: measurements.$measure--half;
                padding-bottom: 0;
            }
        }
    }
}

.wrapper--finder__select--sort--mobile {
    display: block;

    @include include-media.media('>=tablet') {
        display: none;
    }
}

.finder--nofilters {
    .finder__results {
        margin-top: measurements.$measure--small2;
    }
}

.no-js {
    .wrapper--finder__select--sort--desktop {
        display: block;
    }
}

.card {
    .card__anchor {
        .card__details__location {
            position: absolute;
            right: 0;
            top: 0;
            background-color: palette.$color-campus--northampton;
            padding: 0.25rem;
            color: colors.$color-purewhite;
            z-index: functions.z-index(above);
            @include typography.smalltype();

            .icon {
                color: colors.$color-purewhite;
                margin-right: initial;
            }
        }

        .card__details__location-tooting {
            background-color: palette.$color-campus--tooting;
        }
    }
}
