@use '../../abstracts/media' as include-media;
@use '../../abstracts/colors';
@use '../../abstracts/measurements';
@use '../../abstracts/mixins';
@use '../../abstracts/variables';
@use '../../base/typography';

.card--socialmedia {
    .card__anchor {
        @include mixins.box-shadow();

        background-color: colors.$color-purewhite;

        &,
        &:focus,
        &:active,
        &:visited {
            border: none;
        }

        &:hover {
            @include include-media.media('hover') {
                @include mixins.box-shadow-darker();

                border: none;

                .card--socialmedia__label--source {
                    background-color: colors.$color-red50;
                    color: colors.$color-purewhite;
                }
            }
        }

        .card--socialmedia__label--source {
            align-items: center;
            background-color: colors.$color-purewhite;
            border-color: colors.$color-red50;
            border-radius: 50%;
            border-style: solid;
            border-width: variables.$border-width-default;
            color: colors.$color-nearblack;
            display: flex;
            height: measurements.$measure--small4;
            justify-content: center;
            margin-bottom: measurements.$measure--half;
            transition: background-color variables.$transition-duration ease-in,
                color variables.$transition-duration ease-in;
            width: measurements.$measure--small4;

            @include include-media.media('reducemotion') {
                transition: none;
            }
        }

        .card__heading {
            @include mixins.sr-only();
        }

        .card--socialmedia__content {
            margin-bottom: measurements.$measure--small3;
        }

        .card--socialmedia__url {
            color: colors.$color-red50;
        }

        .card--socialmedia__label--socialmedia {
            @include typography.smalltype();

            color: colors.$color-gray7;
            font-style: italic;
            margin-left: measurements.$measure--basic;
            margin-top: measurements.$measure--basic;
        }

        .card--socialmedia__label--socialmedia + .card__thumbnail,
        .card--socialmedia__label--socialmedia + .card__thumbnail__wrapper {
            margin-top: variables.$content-element-margin;
        }

        .card__details__text {
            padding-bottom: measurements.$measure--basic;
            padding-top: variables.$heading-margin;
        }

        .card__type {
            margin-top: variables.$content-element-margin;
        }

        &:after {
            content: unset;
            display: none;
        }

        .card--socialmedia__footer {
            @include typography.smalltype();

            .card--socialmedia__screenname {
                span {
                    color: colors.$color-gray4;
                }
            }

            .card--socialmedia__time {
                color: colors.$color-gray7;
                font-style: italic;
            }
        }
    }

    &.card--socialmedia--instagram {
        .card__thumbnail__wrapper {
            position: relative;
        }

        .card--socialmedia__label--source {
            position: absolute;
            top: measurements.$measure--basic;
            left: measurements.$measure--basic;
        }

        .card--socialmedia__label--socialmedia ~ .card__details__text {
            top: measurements.$measure--medium4;
        }

        .card__thumbnail {
            display: block;
        }
    }
}
