@use '../abstracts/palette';
@use '../abstracts/variables';

////
/// Outline mixins
/// @group abstracts
////
@mixin outline-properties($color: palette.$color-outline) {
    outline-color: $color;
    outline-offset: variables.$border-width-thick;
    outline-style: variables.$border-style-solid;
    outline-width: variables.$border-width-default;
}

@mixin anchor-default-outline($color: palette.$color-outline) {
    &:focus,
    &:active {
        @include outline-properties($color);
    }
}

@mixin outline-reset() {
    outline-color: initial;
    outline-offset: initial;
    outline-style: initial;
    outline-width: initial;
}
